insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '2TH', $b$II Têsalônik$b$, $b$["Sămƀŭt Rơh Bar Y-Pôl Njuăl Ma Phung", "TÊSALÔNIK"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','2TH',1,1,null,$b$Y-Pôl, Y-Silvan jêh ri Y-Timôthê, nchih njuăl sămƀŭt ma phung ngih Brah Ndu ƀon Têsalônik, gŭ tâm Brah Ndu, Mbơ̆ he, jêh ri tâm Yêsu Krist, Kôranh Brah he.$b$,true),
('bunong-vn','2TH',1,2,null,$b$Ăn nau yô̆ jêh ri nau đăp mpăn bơh Brah Ndu, Mbơ̆ he, jêh ri bơh Yêsu Krist, Kôranh Brah he, gŭ ndrel ma khân may.$b$,false),
('bunong-vn','2TH',1,3,null,$b$Hơi phung oh nâu, hên ŭch tâm rnê ma Brah Ndu ƀa ƀơ yor ma khân may nâm bu nau di, yor lah nau chroh khân may văch ma toyh lơn, jêh ri nau rŏng ăp nơm khân may văch ma toyh lơn, jêh ri nau rŏng khân may ma bu êng jêng lơ hâu ktang lơn đŏng.$b$,true),
('bunong-vn','2TH',1,4,null,$b$Pô ri hên tâm rnê ma hên nơm yor khân may tâm phung ngih Brah Ndu êng, yor nau khân may srôih jêh ri nau chroh khân may ta nklang lĕ nau ƀư mhĭk jêh ri nau rêh ni khân may dơn jêh.$b$,true),
('bunong-vn','2TH',1,5,null,$b$Nau nây tâm mpơl nau Brah Ndu phat dôih sŏng, gay ma khân may geh nau khư dơi lăp tâm ƀon bri hađăch Brah Ndu, jêh ri yor nây khân may dơn nau rêh ni.$b$,false),
('bunong-vn','2TH',1,6,null,$b$Yor lah Brah Ndu mĭn nau sŏng tâm mplơ̆ nau rêh ni ma phung ƀư rêh ni khân may,$b$,false),
('bunong-vn','2TH',1,7,null,$b$jêh ri ăn ma khân may, phung geh jêh nau rêh ni, nau rlu ndrel ma hên tơ lah Kôranh Brah Yêsu mra tâm mpơl bơh trôk ndrel ma phung Tông mpăr ueh brah păng ta nklang ŭnh hit,$b$,false),
('bunong-vn','2TH',1,8,null,$b$gay tâm rmal phung mâu gĭt năl Brah Ndu ôh, jêh ri phung mâu tông ma nau mhe mhan ueh bơh Kôranh Brah he Yêsu Krist.$b$,false),
('bunong-vn','2TH',1,9,null,$b$Nau tâm rmal ma khân păng mra jêng nau rai lôch n'ho ro, ngai đah muh măt Kôranh Brah jêh ri bơh nau chrêk rmah nau ktang Păng,$b$,false),
('bunong-vn','2TH',1,10,null,$b$tơ lah Păng plơ̆ văch tâm nar nây, gay bu ăn nau chrêk rmah Păng tâm phung kloh ueh Păng, jêh ri tâm rnê ma Păng tâm lĕ rngôch phung chroh jêh ma Păng, yor lah khân may chroh jêh ma nau hên mbơh ma khân may.$b$,false),
('bunong-vn','2TH',1,11,null,$b$Yor nây nđâp ma hên lĕ mbơh sơm ma khân may ƀa ƀơ gay ma Brah Ndu mra njêng khân may khư ma nau păng kuăl, jêh ri ƀư nanê̆ ngăn lĕ nau mĭn ueh, jêh ri kan nau chroh khân may ma nau brah Păng,$b$,true),
('bunong-vn','2TH',1,12,null,$b$gay ma amoh Kôranh Brah he, Yêsu Krist, geh nau tâm rnê tâm khân may, jêh ri khân may geh nau tâm rnê tâm Păng, tĭng nâm nau yô̆ bơh Brah Ndu he, jêh ri Brah Yêsu Krist.$b$,false),
('bunong-vn','2TH',2,1,null,$b$Bi ma nau Kôranh Brah he, Yêsu Krist, mra văch, jêh ri ma nau he tâm rƀŭn ndrel ma Păng. Hơi phung oh nâu, hên vơh vơl ma khân may,$b$,true),
('bunong-vn','2TH',2,2,null,$b$lơi ăn bu ƀư n'gơ mâu lah ƀư rŭng nau mĭn khân may nơih pơih ôh, gĭt lah ma nau mĭn nchâp, ma nau ngơi, mâu lah ma sămƀŭt njuăl bu mra lah luh tă bơh hên, tâm ban ma nar Kôranh Brah tât jêh.$b$,false),
('bunong-vn','2TH',2,3,null,$b$Lơi ăn bu ndơm khân may ôh, yor lah nar nây mâu mra tât ôh lor ma nau cha lơi, jêh ri bunuyh tih, kon nau roh mra tâm mpơl.$b$,false),
('bunong-vn','2TH',2,4,null,$b$Nơm rlăng mra n'hao păng nơm ta klơ lơn ma lĕ rngôch bu rnha Brah Ndu, mâu lah ma ndơ bu mbah, kŏ păng gŭ tâm ngih Brah Ndu, jêh ri mbơh ma păng nơm jêng Brah Ndu.$b$,false),
('bunong-vn','2TH',2,5,null,$b$Khân may mâu kah gĭt hĕ ma nau gâp lah jêh ma khân may nau nây dôl gâp gŭ ndrel ma khân may?$b$,false),
('bunong-vn','2TH',2,6,null,$b$Jêh ri aƀaơ khân may gĭt mbu nơm kân păng, gay ma păng tâm mpơl, gay ma păng mra tâm mpơl tâm rnôk păng.$b$,true),
('bunong-vn','2TH',2,7,null,$b$Yor lah nau khlay ndâp bơh nau tih ntơm pah kan jêh; ƀiă lah mbu nơm kân nau nây aƀaơ aơ ăt kân kŏ tât nar păng luh du.$b$,false),
('bunong-vn','2TH',2,8,null,$b$Dôl nây nơm tih mra tâm mpơl, jêh ri Kôranh Brah Yêsu mra ƀư rai păng ma n'hâm bơh trôm mbung păng, jêh ri ƀư roh păng ma nau chrêk rmah nar Păng plơ̆ văch.$b$,false),
('bunong-vn','2TH',2,9,null,$b$Nơm tih nây mra tâm mpơl ma nau brah Satan, ma ăp ntil nau brah, nau tâm mbên, jêh ri nau khlay mƀruh,$b$,false),
('bunong-vn','2TH',2,10,null,$b$jêh ri ma ăp ntil nau ndơm tih ma phung rai yot, yor lah khân păng mâu sŏk dơn ôh nau rŏng ma nau nanê̆ gay ma tâm rklaih khân păng nơm.$b$,false),
('bunong-vn','2TH',2,11,null,$b$Yor nây Brah Ndu njuăl ma khân păng nau brah ƀư vĭ, ăn khân păng chroh ma nau mƀruh,$b$,true),
('bunong-vn','2TH',2,12,null,$b$gay ma lĕ rngôch mbu nơm mâu chroh ma nau nanê̆, ƀiă lah rŏng ma nau kue, mra dơn nau rtăp rak.$b$,false),
('bunong-vn','2TH',2,13,null,$b$Hơi phung oh nâu Kôranh Brah rŏng, hên ŭch tâm rnê ma Brah Ndu ƀa ƀơ yor khân may, yor lah Brah Ndu săch jêh khân may ntơm bơh sa ơm ma nau tâm rklaih ma nau kloh ueh bơh Brah Huêng Ueh jêh ri ma nau chroh ma nau nanê̆.$b$,true),
('bunong-vn','2TH',2,14,null,$b$Ma nau nây păng kuăl jêh khân may ma nau mhe mhan ueh hên nti, gay ma khân may geh nau chrêk rmah bơh Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','2TH',2,15,null,$b$Pô nây yơh, hơi phung oh nâu, gŭ nâp hom jêh ri djôt prăp lĕ nau nti lah khân may sŏk dơn jêh, gĭt lah ma nau hên ngơi mâu lah ma nau hên njuăl.$b$,false),
('bunong-vn','2TH',2,16,null,$b$Ăn Kôranh Brah he, Yêsu Krist nơm, jêh ri Brah Ndu, Mbơ̆ he nơm rŏng jêh ma he, jêh ri ăn jêh ma he nau păng yô̆ nau bonh leng n'ho ro, jêh ri nau mhe mhan ueh,$b$,false),
('bunong-vn','2TH',2,17,null,$b$tâm bonh leng nuih n'hâm khân may jêh ri ƀư nâp khân may nơm tâm lĕ kan jêh ri nau ngơi ueh.$b$,false),
('bunong-vn','2TH',3,1,null,$b$Jêh ri, hơi phung oh nâu, mbơh sơm ma hên ƀă, gay ma Nau Kôranh Brah Ngơi hăn lam, jêh ri geh nau chrêk rmah nâm bu tâm khân may,$b$,true),
('bunong-vn','2TH',3,2,null,$b$jêh ri gay ma hên klaih bơh phung bunuyh ƀai, jêh ri tih mhĭk, yor lah lĕ rngôch mâu geh nau chroh ôh.$b$,false),
('bunong-vn','2TH',3,3,null,$b$Kôranh Brah gŭ răp jăp. Păng mra ƀư nâp khân may jêh ri king khân may ma brah mhĭk.$b$,false),
('bunong-vn','2TH',3,4,null,$b$Tâm Kôranh Brah hên geh nau rnơm ma khân may ƀư, jêh ri mra ƀư nau hên ntăm jêh ma khân may.$b$,false),
('bunong-vn','2TH',3,5,null,$b$Ăn Kôranh Brah njŭn leo nuih n'hâm khân may ma nau Brah Ndu rŏng, jêh ri ma nau srôih tâm Brah Krist.$b$,false),
('bunong-vn','2TH',3,6,null,$b$Hơi phung oh nâu, hên ntăm ma khân may ma amoh Kôranh Brah he, Yêsu Krist, ăn khân may du ngai bơh phung oh nâu gŭ tâm nau rŭng, mâu di tĭng nâm nau nti khân may sŏk dơn jêh bơh hên.$b$,true),
('bunong-vn','2TH',3,7,null,$b$Khân may nơm gĭt jêh mâm ƀư kơt hên, yor lah hên mâu gŭ ngao krao sach ndrel ma khân may ma nau rŭng ôh,$b$,false),
('bunong-vn','2TH',3,8,null,$b$jêh ri hên mâu mâp sa kapŭng bu dơm dam ôh, ƀiă lah măng nar hên pah kan tâm nau jêr yor mâu ŭch ƀư jâk du huê tâm phung khân may ôh.$b$,false),
('bunong-vn','2TH',3,9,null,$b$Mâu di hên mâu geh nau vay ôh, ƀiă lah hên ŭch ƀư nau tâm ntĭt ma khân may kơt.$b$,true),
('bunong-vn','2TH',3,10,null,$b$Yor dôl hên gŭ ndrel khân may, hên ntăm jêh tơ lah du huê mâu ŭch pah kan lơi ăn păng sông ôh.$b$,true),
('bunong-vn','2TH',3,11,null,$b$Yor lah hên tăng jêh geh bunuyh tâm phung khân may gŭ tâm nau ƀlao, mâu pah kan ôh, ƀiă lah jêng phung gŭ nkoch bri dơm dam.$b$,false),
('bunong-vn','2TH',3,12,null,$b$Tâm Brah Yêsu Krist, hên ntăm jêh ri nchâp phung nây, ăn khân păng pah kan đăp mpăn jêh ri sông sa ndơ khân păng nơm.$b$,false),
('bunong-vn','2TH',3,13,null,$b$Hơi phung oh nâu, lơi khân may jêng rgănh ôh tâm nau ƀư ueh.$b$,false),
('bunong-vn','2TH',3,14,null,$b$Jêh ri tơ lah du huê mâu tông ôh ma nau hên lah tâm sămƀŭt aơ, sek păng, jêh ri lơi tâm rnglăp đah păng ôh, gay ma păng geh nau bêk.$b$,false),
('bunong-vn','2TH',3,15,null,$b$Lơi uănh ma păng nâm bu du huê rlăng ôh, ƀiă lah mbơh ma păng nâm bu du huê oh nâu.$b$,false),
('bunong-vn','2TH',3,16,null,$b$Gay ma Kôranh Brah nau đăp mpăn păng nơm, ăn ma khân may nau đăp mpăn ƀa ƀơ tâm lĕ rngôch nau. Ăn Kôranh Brah gŭ ndrel ma lĕ rngôch khân may.$b$,true),
('bunong-vn','2TH',3,17,null,$b$Gâp jêng, Y-Pôl khâl đah khân may ma ti gâp nơm. Ta aơ gâp nchih amoh gâp tâm lĕ rngôch sămƀŭt gâp njuăl; tâm ban pô nây gâp nchih.$b$,true),
('bunong-vn','2TH',3,18,null,$b$Ăn nau yô̆ bơh Kôranh Brah he, Yêsu Krist, gŭ ndrel ma lĕ rngôch khân may.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','2TH',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','2TH',1,3,1,'heading',$b$Phung Têsalônik Văch Ma Toyh Tâm Nau Chroh Jêh Ri Tâm Nau Rŏng Dôl Geh Nau Ƀư Mhĭk$b$),
('bunong-vn','2TH',2,1,0,'heading',$b$Nau Kôranh Brah Mra Plơ̆ Văch$b$),
('bunong-vn','2TH',3,1,0,'heading',$b$Nau Khâl$b$),
('bunong-vn','2TH',3,6,1,'heading',$b$Nau Nti Êng Êng$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '1TI', $b$I Timôthê$b$, $b$["Sămƀŭt Rơh Nguay Y-Pôl Njuăl Ma Phung", "Y-TIMÔTHÊ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','1TI',1,1,null,$b$Y-Pôl, kôranh oh mon Yêsu Krist tĭng nâm nau ntăm bơh Brah Ndu, Nơm tâm rklaih he, jêh ri Yêsu Krist, nau he kâp gân.$b$,true),
('bunong-vn','1TI',1,2,null,$b$Nchih njuăl ma Y-Timôthê, kon gâp ngăn tâm nau chroh; gay ma Brah Ndu, Mbơ̆ , jêh ri Yêsu Krist, Kôranh Brah he, ăn ma may nau yô̆, nau ueh jêh ri nau đăp mpăn.$b$,true),
('bunong-vn','1TI',1,3,null,$b$Gâp kah gĭt ma may nau gâp nchâp may jêh ri gâp hăn ta n'gor Masêđôn, ăn may gŭ ta ƀon Êphêsô, gay ntăm ma bu lơi nti nau êng ôh.$b$,true),
('bunong-vn','1TI',1,4,null,$b$Jêh ri lơi mĭn ma nau nkoch bri ơm jêh ri ma nau răk mprĭng u che mâu blau lôch. Nau nây ăn geh nau tâm rlăch, ƀiă lah mâu n'hao ôh kan Brah Ndu tâm nau chroh.$b$,false),
('bunong-vn','1TI',1,5,null,$b$Nau hên ŭch bơh nau ntăm nây jêng nau rŏng luh bơh nuih n'hâm kloh, bơh nuih n'hâm sŏng ueh, jêh ri ma nau chroh răp jăp.$b$,false),
('bunong-vn','1TI',1,6,null,$b$Ƀa ƀă cha lơi nau nây jêh ri nkhah du tâm nau nti dơm dam.$b$,false),
('bunong-vn','1TI',1,7,null,$b$Khân păng ŭch jêng kôranh nơm nti nau vay, ƀiă lah khân păng mâu gĭt rbăng ôh nau khân păng lah, mâu lĕ khân păng blau ƀư nanê̆.$b$,false),
('bunong-vn','1TI',1,8,null,$b$He gĭt ma nau vay jêng ueh ma mbu nơm blau dŏng păng.$b$,true),
('bunong-vn','1TI',1,9,null,$b$He gĭt bu njêng nau vay mâu di ma bunuyh sŏng ôh ƀiă lah ma phung ƀai jêh ri phung dăng bôk, phung mâu yơk ma Brah Ndu, jêh ri ma phung tih, ma phung mâu geh nau chroh, ma phung suai rak, ma phung nkhĭt mê̆ mbơ̆ , ma phung nkhĭt bu,$b$,false),
('bunong-vn','1TI',1,10,null,$b$ma phung văng tĭr, bu klâu ndrăng bu klâu, bu ur ndrăng bu ur, ma phung tăch dĭk nă, ma phung mƀruh, ma phung rlăng, jêh ri lĕ nau êng ma nau nti kloh,$b$,false),
('bunong-vn','1TI',1,11,null,$b$tĭng nâm nau mhe mhan ueh chrêk rmah bơh Brah Ndu ueh maak, nau mhe mhan ueh nây jao jêh ma gâp.$b$,false),
('bunong-vn','1TI',1,12,null,$b$Gâp tâm rnê ma nơm ăn jêh nau ktang ma gâp dơi pah kan aơ, Yêsu Krist, Kôranh Brah he, yor lah păng kơp gâp jêng răp jăp jêh ri ăn gâp pah kan ma Păng.$b$,true),
('bunong-vn','1TI',1,13,null,$b$Kăl e ri gâp jêng du huê suai rak, du huê ƀư mhĭk, du huê hăt janh ƀai ƀiă lah gâp geh jêh nau yô̆ yor lah gâp ƀư pô nây ma nau mâu gĭt rbăng, tâm nau mâu chroh,$b$,false),
('bunong-vn','1TI',1,14,null,$b$jêh ri nau Kôranh Brah yô̆ jêng bêng ler jêh ma gâp ma nau chroh jêh ri nau rŏng tâm Yêsu Krist.$b$,false),
('bunong-vn','1TI',1,15,null,$b$Nau ngơi aơ nanê̆ jêh ri khư sŏk dơn lĕ. Yêsu Krist văch jêh tâm neh ntu gay tâm rklaih phung tih. Tâm phung nây gâp jêng tih lơn ma lĕ rngôch,$b$,false),
('bunong-vn','1TI',1,16,null,$b$ƀiă lah gâp sŏk dơn jêh nau yô̆, gay ma Yêsu Krist tâm mpơl tâm gâp, nơm tih lơn, lĕ nau păng srôih rah vah, ăn gâp jêng nau tâm ntĭt ma phung mra chroh tâm păng, gay geh nau rêh n'ho ro.$b$,false),
('bunong-vn','1TI',1,17,null,$b$Ma hađăch gŭ ƀa ƀơ n'ho ro, mâu blau khĭt, bu mâu dơi saơ, knŏng Păng jêng Brah Ndu, ăn nau yơk jêh ri nau chrêk rmah tâm lĕ rngôch rnôk. Amen.$b$,false),
('bunong-vn','1TI',1,18,null,$b$Hơi Y-Timôthê kon gâp ơi nau gâp ntăm ma may jêng tĭng nâm nau mbơh lor njŭn jêh may, gay ma đah khân păng yơh may dơi tâm lơh nau tâm lơh ueh.$b$,true),
('bunong-vn','1TI',1,19,null,$b$Dôl djôt prăp nau chroh jêh ri nuih n'hâm sŏng ueh ƀa ƀă dun jêh nau sŏng nây jêh ri khân păng rklâm lơi nau chroh khân păng.$b$,true),
('bunong-vn','1TI',1,20,null,$b$Tâm phung nây geh Y-Himênê, jêh ri Y-Aleksandrơ. Gâp jao jêh khân păng ma Satan, gay ma khân păng nti, mâu hôm suai rak ôh.$b$,true),
('bunong-vn','1TI',2,1,null,$b$Lor ma lĕ rngôch ndơ gâp ntăm ma may ăn mbơh sơm, vơh vơl, dăn, jêh ri kah gĭt tôr ma Brah Ndu yor lĕ rngôch bunuyh,$b$,true),
('bunong-vn','1TI',2,2,null,$b$ma phung hađăch jêh ri ma lĕ rngôch phung kôranh chiă uănh, gay ma he dơi gŭ đăp mpăn jêh ri mâu geh rŭng tâm lĕ nau blau yơk ma Brah Ndu jêh ri lĕ nau sŏng srăng.$b$,false),
('bunong-vn','1TI',2,3,null,$b$Nau nây ueh jêh ri maak ta năp Brah Ndu, Nơm Tâm Rklaih he.$b$,false),
('bunong-vn','1TI',2,4,null,$b$Păng ŭch ma lĕ rngôch bunuyh dơi klaih,$b$,false),
('bunong-vn','1TI',2,5,null,$b$jêh ri knŏng du huê Brah Ndu jêh ri knŏng du huê Nơm tâm nklang Brah Ndu đah bunuyh, Yêsu Krist, bunuyh.$b$,false),
('bunong-vn','1TI',2,6,null,$b$Nơm jao jêh Păng nơm gay ma tâm chuai lĕ rngôch bunuyh; pô ri jêng nau mbơh jêh tâm rnôk di,$b$,false),
('bunong-vn','1TI',2,7,null,$b$jêh ri ma nơm nây gâp jêng nơm nti jêh ri kôranh oh mon ăn nti ma phung bu năch tâm nau chroh jêh ri nau nanê̆. (Gâp ngơi nau nanê̆, gâp mâu mƀruh ôh).$b$,false),
('bunong-vn','1TI',2,8,null,$b$Gâp ŭch ma phung bu klâu mbơh sơm tâm lĕ ntŭk, yơr ti kloh mâu geh nau ji nuih biănh mâu lah nau mĭn mhĭk ôh.$b$,true),
('bunong-vn','1TI',2,9,null,$b$Gâp ŭch lĕ ma phung bu ur mbăn nah bŭt soh ao ma nau di, ma nau gĭt rbăng, jêh ri ma nau sŏng, mâu păch sŏk, dơm mah, lŭ ang, mâu lah soh ao ƀư mbrưh ôh,$b$,true),
('bunong-vn','1TI',2,10,null,$b$ƀiă lah ăn kan ueh jêng ndơ nkrơ̆ khân păng. Nau nây jêng di ma phung bu ur nkoch khân păng pah kan ma Brah Ndu.$b$,false),
('bunong-vn','1TI',2,11,null,$b$Ăn phung bu ur gŭ rklăk dôl gŭ iăt nau nti ma nau blau tông ngăn.$b$,true),
('bunong-vn','1TI',2,12,null,$b$Gâp mâu ăn ôh phung bu ur nti lah, mâu lah jêng kôranh ma bu klâu, ƀiă lah ăn khân păng gŭ rklăk.$b$,false),
('bunong-vn','1TI',2,13,null,$b$Yor lah Brah Ndu njêng Y-Ađam lor, jêh ri H'Evơ pa kơi,$b$,false),
('bunong-vn','1TI',2,14,null,$b$jêh ri mâu geh ôh Y-Ađam geh nau ndơm, ƀiă lah bu ur geh nau ndơm jêng tih rlau nau vay.$b$,false),
('bunong-vn','1TI',2,15,null,$b$Ƀiă lah phung bu ur mra klaih tâm nau khân păng jêng mê̆, tơ lah khân păng srôih gŭ sŏng tâm nau chroh, tâm nau rŏng, jêh ri tâm nau kloh ueh.$b$,false),
('bunong-vn','1TI',3,1,null,$b$Nau ngơi aơ jêng nanê̆, tơ lah du huê joi kan jêng kôranh chiă uănh, păng ŭch ma kan khlay ngăn,$b$,true),
('bunong-vn','1TI',3,2,null,$b$kôranh chiă uănh nây mâu geh nau bu dơi nduyh, gŭ knŏng du huê ur, blau sông sa di keh, gĭt njrăng, dơi khư, gĭt rom bunuyh, dơi nti lah.$b$,false),
('bunong-vn','1TI',3,3,null,$b$Mâu jêng bunuyh nhŭl ndrănh ôh, mâu jêng bunuyh hăt janh ôh, ƀiă lah rdơ̆ , mâu rŏng nau tâm djrel, mâu rŏng ma prăk âk.$b$,false),
('bunong-vn','1TI',3,4,null,$b$Ăn păng mât uănh ngih păng nơm ăn ueh jêh ri ăn phung kon păng blau tông bâr ma păng jêh ri gŭ sŏng ngăn;$b$,false),
('bunong-vn','1TI',3,5,null,$b$Yor lah tơ lah du huê mâu blau chiă uănh ngih păng nơm, mâm păng mra dơi chiă uănh phung ngih Brah Ndu?$b$,false),
('bunong-vn','1TI',3,6,null,$b$Du huê mhe chroh mâu dơi ôh, klach lah bêng ma nau sưr păng tŭp tâm dâng nau phat dôih brah mhĭk.$b$,false),
('bunong-vn','1TI',3,7,null,$b$Ăn păng geh nau nkoch ueh bơh phung pa dih, gay lơi ăn păng tŭp tâm nau bu nduyh jêh ri tâm dăk brah mhĭk.$b$,false),
('bunong-vn','1TI',3,8,null,$b$Phung kôranh ngih brah tâm ban lĕ mra jêng sŏng srăng, mâu ngơi bar bâr ôh, mâu nhêt âk dak play kriăk ƀâu ôh (ndrănh) mâu jêng bunuyh hay sa ma prăk âk ôh.$b$,true),
('bunong-vn','1TI',3,9,null,$b$Khân păng mra djôt prăp nau khlay ndâp bơh nau chroh tâm nuih n'hâm sŏng kloh.$b$,false),
('bunong-vn','1TI',3,10,null,$b$Ăn bu rlong uănh khân păng lor, tơ lah khân păng mâu geh nau bu dơi nduyh ăn khân păng pah kan ƀư kôranh ngih brah.$b$,false),
('bunong-vn','1TI',3,11,null,$b$Phung bu ur tâm ban lĕ mra jêng sŏng srăng, mâu dơi ngơi mhĭk ma bu ôh, ƀiă lah sông sa di keh, gŭ răp jăp tâm lĕ rngôch ndơ.$b$,false),
('bunong-vn','1TI',3,12,null,$b$Ăn phung kôranh ngih brah gŭ knŏng du huê ur, jêh ri chiă uănh ăn ueh phung kon khân păng, jêh ri ngih khân păng nơm.$b$,false),
('bunong-vn','1TI',3,13,null,$b$Yor lah mbu nơm pah kan ueh mra geh nau yơk ma khân păng nơm, jêh ri nau gĭt nanê̆ tâm nau chroh ma Yêsu Krist.$b$,false),
('bunong-vn','1TI',3,14,null,$b$Gâp nchih nau aơ ma may ma nau kâp gân hăn gơnh ma may, ƀiă lah gay ma may gĭt.$b$,true),
('bunong-vn','1TI',3,15,null,$b$Tơ lah gâp tât nkai mâm ƀư bu gŭ ngao krao sach tâm ndŭl mpôl Brah Ndu, nâm bu ntĭt phung ngih Brah Ndu rêh, jêng nâm bu meh jêh ri ntur ma nau nanê̆.$b$,false),
('bunong-vn','1TI',3,16,null,$b$Nau khlay ndâp tâm nau yơk ma Brah Ndu toyh ngăn jêh ri bu mâu dơi dun ôh: “Nơm tâm mpơl jêh tâm nglay săk, Brah Huêng Ueh kơp păng sŏng. Phung Tông mpăr ueh Brah Ndu saơ păng jêh. Bu mbơh jêh păng ma phung ndŭl mpôl, bu chroh jêh ma păng tâm neh ntu. Jêh ri Brah Ndu chông leo jêh păng tâm nau chrêk rmah.$b$,true),
('bunong-vn','1TI',4,1,null,$b$Ƀiă lah Brah Huêng Ueh mbơh rah vah jêh tâm rnôk lôch dŭt ƀa ƀă mra cha lơi nau chroh, ŭch iăt nau phung brah ndơm, jêh ri nau brah mhĭk nti lah.$b$,true),
('bunong-vn','1TI',4,2,null,$b$Ma nau nuih n'hâm mŭr phung bunuyh ngơi mƀruh jêh ri nuih n'hâm sŏng khân păng kro jêh.$b$,false),
('bunong-vn','1TI',4,3,null,$b$Phung nây buay bu gŭ ur sai, jêh ri ntăm ma bu ver sa ndơ Brah Ndu rhăk jêh, gay ma phung chroh jêh ri phung gĭt rbăng jêh nau nanê̆ dơi sa ma nau kah gĭt tôr.$b$,false),
('bunong-vn','1TI',4,4,null,$b$Yor lah lĕ ndơ Brah Ndu njêng jêh jêng ueh jêh ri mâu geh ndơ bu dơi dun ôh, tơ lah bu sa ma nau gĭt tôr.$b$,false),
('bunong-vn','1TI',4,5,null,$b$Pô ri păng jêng kloh ueh jêh đah Nau Brah Ndu Ngơi jêh ri ma nau mbơh sơm.$b$,false),
('bunong-vn','1TI',4,6,null,$b$Tơ lah may nti lĕ nau aơ ma phung oh nâu, may mra jêng du huê oh mon ktang ueh ma Yêsu Krist, siăm jêh may nơm ma nau ngơi bơh nau chroh, jêh ri ma nau nti ueh may tĭng ndô̆ jêh ma nau di.$b$,true),
('bunong-vn','1TI',4,7,null,$b$Ăn may dun nau bu nkoch bri ƀơ̆ ƀơch, jêh ri rluk mâl. Ăn may nti nau yơk ma Brah Ndu,$b$,false),
('bunong-vn','1TI',4,8,null,$b$yor lah nau nti ƀư ktang săk jăn jêng khlay djê̆ djê̆, ƀiă lah nau yơk ma Brah Ndu jêng khlay lơn ma lĕ rngôch. Păng geh nau ton ma nau rêh aƀaơ nđâp ma nau rêh rnôk kăndơ̆ .$b$,false),
('bunong-vn','1TI',4,9,null,$b$Nau ngơi nây nanê̆ jêh ri khư sŏk dơn lĕ.$b$,false),
('bunong-vn','1TI',4,10,null,$b$Yor nây he pah kan jêh ri tâm lơh yor lah he kâp gân tâm Brah Ndu rêh, jêng nơm tâm rklaih ma lĕ rngôch bunuyh, khlay ngăn ngên ma phung chroh.$b$,false),
('bunong-vn','1TI',4,11,null,$b$Ntăm jêh ri nti nau aơ ma khân may.$b$,true),
('bunong-vn','1TI',4,12,null,$b$Lơi ăn bu rmot ma nau may jêng dôl druh ndăm, ƀiă lah ăn may jêng nau tâm ntĭt ma phung chroh tâm nau ngơi, tâm nau gŭ ngao krao sach tâm nau rŏng, tâm nau chroh, tâm nau kloh.$b$,true),
('bunong-vn','1TI',4,13,null,$b$Ăn may srôih uănh sămƀŭt, sâm n'hao nuih bu, nti lah ma bu kŏ gâp tât.$b$,false),
('bunong-vn','1TI',4,14,null,$b$Lơi ƀư nau mâu chrê ôh ma nau Brah Ndu ăn may geh jêh, jêh ri tât ma may tĭng nâm nau bu mbơh lor jêh ma nau pah ti bơh nau phung bu ranh tâm rƀŭn.$b$,false),
('bunong-vn','1TI',4,15,null,$b$Ăn may mĭn ma nau nây jao lĕ may nơm ma nau nây, gay ma lĕ rngôch mra saơ nau may dơi.$b$,false),
('bunong-vn','1TI',4,16,null,$b$Njrăng ma may nơm jêh ri ma nau may nti lah; srôih tâm nau nây, yor lah dôl may ƀư pô nây may mra tâm rklaih may nơm jêh ri phung gŭ iăt may.$b$,false),
('bunong-vn','1TI',5,1,null,$b$Lơi nduyh ôh ma bu klâu ranh, ƀiă lah tâm n'hao nuih păng tâm ban ma du huê mbơ̆ ; n'hao nuih phung mom ndăm tâm ban ma phung oh nâu.$b$,true),
('bunong-vn','1TI',5,2,null,$b$Phung bu ur tâm ban ma mê̆, phung bu ur druh tâm ban ma oh ruh ma nuih n'hâm kloh ngăn.$b$,false),
('bunong-vn','1TI',5,3,null,$b$Yơk ma bu ur khĭt sai, ma mbu nơm khân păng ngăn khĭt sai.$b$,true),
('bunong-vn','1TI',5,4,null,$b$Tơ lah du huê bu ur khĭt sai geh kon mâu lah sau, ăn khân păng nti lor lơn blau ƀư nau yơk ma ndŭl mpôl khân păng nơm, jêh ri blau kah gĭt tôr ma mê̆ mbơ̆ khân păng; yor lah nau nây ƀư maak ma Brah Ndu.$b$,false),
('bunong-vn','1TI',5,5,null,$b$Mbu nơm jêng bu ur khĭt sai ngăn jêh ri gŭ êng geh nau kâp gân tâm Brah Ndu, jêh ri măng nar srôih vơh vơl jêh ri mbơh sơm ma Brah Ndu,$b$,false),
('bunong-vn','1TI',5,6,null,$b$ƀiă lah mbu nơm jao păng nơm ma nau nglay săk ŭch jêng khĭt jêh nđâp ma dôl păng gŭ rêh kđôi.$b$,false),
('bunong-vn','1TI',5,7,null,$b$Mbơh ma khân păng nau aơ gay ma khân păng mâu mra geh nau bu dơi nduyh ôh.$b$,false),
('bunong-vn','1TI',5,8,null,$b$Tơ lah du huê mâu chrê ma phung ndŭl mpôl păng, khlay ngăn ngên ma phung ur kon păng, păng dun jêh nau chroh jêh ri păng jêng mhĭk lơn ma du huê ê chroh.$b$,false),
('bunong-vn','1TI',5,9,null,$b$Lơi ăn bu nchih amoh du huê bu ur tâm ndrom sămƀŭt phung bu ur khĭt sai tơ lah păng ê tât prao jât năm, tơ lah păng geh knŏng du huê sai,$b$,true),
('bunong-vn','1TI',5,10,null,$b$jêh ri ăn păng geh nau mbơh ueh bơh bu, mâp rong jêh phung kon, blau rom phung bu năch, mâp rao jâng phung kloh ueh, blau kơl phung rêh ni, jêh ri ƀư ăp ntil kan ueh.$b$,false),
('bunong-vn','1TI',5,11,null,$b$Ƀiă lah dun nchih amoh phung bu ur khĭt sai dôl druh; yor lah tơ lah nau rŏng ƀư maak ma nglay săk tâm nkhah khân păng bơh Krist, khân păng plơ̆ ŭch gŭ sai,$b$,false),
('bunong-vn','1TI',5,12,null,$b$jêh ri jêng tih tâm nau khân păng rlau nau khân păng ton jêh.$b$,false),
('bunong-vn','1TI',5,13,null,$b$Ma nau nây khân păng jêng bu ur gŭ dơm dam. Khân păng nti nsong ăp mlâm ngih, jêh ri mâu di knŏng khân păng gŭ dơm ôh, ƀiă lah jêng phung nkoch bri ngơi njĭp jêh ri phung joi tâm rlŭk tâm nau ngơi bu, khân păng ngơi nau bu mâu vay ngơi ôh.$b$,false),
('bunong-vn','1TI',5,14,null,$b$Gâp ŭch ma phung bu ur ndrô druh ueh lơn gŭ sai, ăn geh kon, blau chiă uănh ngih khân păng nơm, jêh ri mâu ăn ma nơm rlăng dơi ngơi mhĭk ma khân păng ôh.$b$,false),
('bunong-vn','1TI',5,15,null,$b$Yor lah ƀa ƀă bu ur ndrô cha lơi jêh gay tĭng ndô̆ Satan.$b$,false),
('bunong-vn','1TI',5,16,null,$b$Tơ lah du huê chroh, bu klâu mâu lah bu ur, geh phung bu ur ndrô ndrel ma păng, ăn păng kơl khân păng, pô ri lơi ƀư jâk ma phung ngih Brah Ndu, gay ma phung ngih Brah Ndu dơi kơl phung bu ur ngăn khĭt sai.$b$,false),
('bunong-vn','1TI',5,17,null,$b$Ăn bu yơk bar tơ̆ âk lơn ma phung bu bŭnh bu ranh chiă uănh ueh, khlay ngăn ngên ma phung nti lah jêh ri ma phung nti bu;$b$,true),
('bunong-vn','1TI',5,18,null,$b$yor lah nau nchih lah: “May mâu mra nkŭm ôh mbung ndrôk tơ lah păng gŭ jot ba”, jêh ri: “Bunuyh pah kan khư geh nau nkhôm ma păng”.$b$,false),
('bunong-vn','1TI',5,19,null,$b$Lơi dơn ôh nau bu phong ma du huê bu bŭnh bu ranh, knŏng tơ lah geh nau mbơh ngăn bơh bar mâu lah pe nuyh.$b$,false),
('bunong-vn','1TI',5,20,null,$b$Mbu nơm ƀư tih ăn may nduyh khân păng ta năp lĕ rngôch, gay ma phung êng geh nau klach tâm ban lĕ.$b$,false),
('bunong-vn','1TI',5,21,null,$b$Ta năp Brah Ndu, ta năp Yêsu Krist, jêh ri ta năp phung Tông mpăr ueh Brah Ndu săch jêh, gâp nchâp may ăn tông lĕ nau aơ jêh ri lơi săch ôh knŏng nau may rŏng.$b$,true),
('bunong-vn','1TI',5,22,null,$b$Lơi ngăch pah ti ta bu ôh. Lơi ƀư tih ndrel ma bu ôh, chiă uănh may nơm ăn kloh.$b$,false),
('bunong-vn','1TI',5,23,null,$b$Lơi ta nhêt knŏng dak, ƀiă lah nhêt djê̆ ndrănh yor khŭng may jêh ri yor may vay ji mro mrăng.$b$,false),
('bunong-vn','1TI',5,24,null,$b$Nau tih bunuyh ƀa ƀă mpơl ro lor ma nau phat dôih tât, bi phung êng, nau tih khân păng tâm mpơl pa kơi ta nây.$b$,true),
('bunong-vn','1TI',5,25,null,$b$Tâm ban lĕ kan ueh tâm mpơl ro, jêh ri tơ lah mâu tâm mpơl ro khân păng mâu dơi gŭ ndâp ƀa ƀơ ôh.$b$,false),
('bunong-vn','1TI',6,1,null,$b$Ăn lĕ rngôch gŭ tâm dâng mâng mbăk jêng oh mon uănh ma phung kôranh khân păng khư ma lĕ nau yơk, gay ma bu mâu suai rak ma amoh Brah Ndu, jêh ri ma nau nti lah.$b$,true),
('bunong-vn','1TI',6,2,null,$b$Jêh ri tơ lah phung chroh jêng kôranh khân păng, lơi ăn oh mon tâm rmot ma kôranh ôh dôl lah khân păng jêng phung oh nâu, ƀiă lah ăn khân păng pah kan ma kôranh khân păng ueh lơn yor lah khân păng jêng phung chroh jêh ri phung bu rŏng, jêh ri joi nau ƀư ueh ma khân păng. Phung Kôranh Nơm Nti tih jêh ri nau rŏng ma nau ndrŏng. Nti jêh ri ntĭm nau nây ma khân păng.$b$,false),
('bunong-vn','1TI',6,3,null,$b$Tơ lah du huê nti nau êng, jêh ri mâu dơn ôh nau ngơi kloh bơh Kôranh Brah he, Yêsu Krist, jêh ri nau nti ăn bu blau yơk ma Brah Ndu.$b$,true),
('bunong-vn','1TI',6,4,null,$b$Păng bêng ma nau sưr jêh ri păng mâu blau jêh ri păng mâu gĭt du ntil ndơ ôh. Păng geh nuih n'hâm ji ma nau ôp dơm dam, jêh ri tâm rlăch tâm nau ngơi. Bơh nau nây luh nau kơnh, nau tâm djrel, nau nchơt, nau đing tih,$b$,false),
('bunong-vn','1TI',6,5,null,$b$jêh ri nau tâm rlăch bơh bunuyh geh nau mĭn tih mhĭk, mâu geh nau ngăn ôh, jêh ri mĭn ma nau yơk ma Brah Ndu ndrel jêng trong bu dơi sa prăk.$b$,false),
('bunong-vn','1TI',6,6,null,$b$N'hêl nanê̆ geh nau ndrŏng ngăn tâm nau yơk ma Brah Ndu ndrel ma nuih n'hâm maak.$b$,true),
('bunong-vn','1TI',6,7,null,$b$Yor lah he mâu geh djôt leo du ntil ndơ ôh ma neh ntu, jêh ri mâu lĕ he dơi sŏk.$b$,false),
('bunong-vn','1TI',6,8,null,$b$Tơ lah he geh ndơ sông sa jêh ri bok ao, ma dŭm nây tŏng jêh ma he.$b$,false),
('bunong-vn','1TI',6,9,null,$b$Ƀiă lah phung ŭch jêng ndrŏng tŭp tâm nau ndơm tâm dăk jêh ri tâm âk nau ŭch rluk jêh ri mhĭk. Nau nây nchâp bunuyh ma nau ƀư rai jêh ri ma nau roh.$b$,false),
('bunong-vn','1TI',6,10,null,$b$Yor lah nau rŏng ma prăk jêng reh ma lĕ rngôch nau mhĭk, jêh ri yor nau rŏng pô nây ƀa ƀă nkhah du jêh bơh nau chroh jêh ri jao khân păng nơm ma âk nau rêh ni.$b$,false),
('bunong-vn','1TI',6,11,null,$b$Bi may hơi bunuyh bơh Brah Ndu, dun lĕ nau nây, jêh ri tĭng joi nau sŏng, nau yơk ma Brah Ndu, nau chroh, nau rŏng, nau srôih, nau rah rơch.$b$,true),
('bunong-vn','1TI',6,12,null,$b$Tâm lơh hom nau tâm lơh ueh ma nau chroh, djôt nâp nau rêh n'ho ro. Ma nau nây Brah Ndu kuăl jêh may, jêh ri may mbơh ueh jêh ma nau may chroh ta năp bunuyh âk tăng.$b$,false),
('bunong-vn','1TI',6,13,null,$b$Gâp ntăm ma may ta năp Brah Ndu, nơm ăn nau rêh ma lĕ rngôch ndơ jêh ri ta năp Yêsu Krist, nơm mbơh ueh ta năp Pôns Pilat.$b$,false),
('bunong-vn','1TI',6,14,null,$b$Ăn may djôt prăp nau ntăm kloh ueh, jêh ri mâu geh nau bu dơi nduyh, kŏ tât nar Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','1TI',6,15,null,$b$Păng mra tâm mpơl di rnôk păng, nơm ueh uĭn jêh ri knŏng păng Nơm Chiă Uănh, hađăch ma phung hađăch, jêh ri Kôranh Brah ma lĕ Kôranh Brah.$b$,false),
('bunong-vn','1TI',6,16,null,$b$Knŏng êng Păng yơh geh nau mâu blau khĭt, jêh ri gŭ tâm nau ang bu mâu dơi hăn êp, Nơm bunuyh mâu mâp saơ, mâu lĕ dơi saơ, ma Păng yơh nau yơk jêh ri nau brah n'ho ro. Amen.$b$,false),
('bunong-vn','1TI',6,17,null,$b$Ntăm hom ma phung ndrŏng rnôk aơ, lơi ăn khân păng jêng sưr jêh ri rnơm ma nau ndrŏng mâu nanê̆, ƀiă lah rnơm ma Brah Ndu, Nơm ăn ma he ma nau rmeh ler ăp ntil ndơ dơi ƀư maak ma he.$b$,true),
('bunong-vn','1TI',6,18,null,$b$Ntăm ma khân păng ƀư nau ueh, jêng ndrŏng tâm kan ueh, geh nau lŏng jêh ri ŭch tâm pă ma bu.$b$,false),
('bunong-vn','1TI',6,19,null,$b$Pô ri khân păng bun ma khân păng nơm ntur ueh prăp ma rnôk kăndơ̆ , gay dơi sŏk nau rêh ngăn.$b$,false),
('bunong-vn','1TI',6,20,null,$b$Hơi Y-Timôthê, prăp hom nau bu jao jêh ma may. Dun ma nau nti dơm dam, ƀơ̆ ƀơch, jêh ri nau tâm rlăch bơh nau tih bu rnha nau gĭt rbăng.$b$,true),
('bunong-vn','1TI',6,21,null,$b$Geh ƀa ƀă dơn jêh nau gĭt rbăng nây, ƀiă lah cha lơi jêh nau chroh. Ăn nau yô̆ gŭ ndrel ma may.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','1TI',1,1,0,'heading',$b$Nơm Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','1TI',1,3,1,'heading',$b$Nau Nti Tih Jêh Ri Nau Mhe Mhan Ueh Nau Yô̆$b$),
('bunong-vn','1TI',1,18,2,'heading',$b$Tâm Lơh Nau Tâm Lơh Ueh$b$),
('bunong-vn','1TI',2,1,0,'heading',$b$Nau Mbơh Sơm Ma Lĕ Rngôch$b$),
('bunong-vn','1TI',2,8,1,'heading',$b$Kan Phung Bu Ur$b$),
('bunong-vn','1TI',3,1,0,'heading',$b$Kan Phung Kôranh Chiă Uănh Jêh Ri Phung Kôranh Ngih Brah$b$),
('bunong-vn','1TI',4,1,0,'heading',$b$Nau Ntăm Ma Y-Timôthê Yor Phung Kôranh Nơm Nti Tih$b$),
('bunong-vn','1TI',4,6,1,'heading',$b$Nau Ntăm Ma Kan Y-Timôthê$b$),
('bunong-vn','1TI',5,1,0,'heading',$b$Nau Nkra Ndrăng Phung Chroh$b$),
('bunong-vn','1TI',5,3,1,'heading',$b$Phung Bu Ur Khĭt Sai$b$),
('bunong-vn','1TI',5,17,2,'heading',$b$Nau Ntăm Ma Phung Bu Ranh$b$),
('bunong-vn','1TI',6,1,0,'heading',$b$Nau Ntăm Ma Phung Oh Mon$b$),
('bunong-vn','1TI',6,11,1,'heading',$b$Nau Ntăm, Ma Y-Timôthê$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '2TI', $b$II Timôthê$b$, $b$["Sămƀŭt Rơh Bar Y-Pôl Njuăl Ma Phung", "Y-TIMÔTHÊ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','2TI',1,1,null,$b$Y-Pôl, kôranh oh mon Yêsu Krist, tĭng nâm nau Brah Ndu ŭch, ăn mbơh nau ton ma nau rêh tâm Yêsu Krist,$b$,true),
('bunong-vn','2TI',1,2,null,$b$Njuăl sămƀŭt ma Y-Timôthê, kon gâp rŏng ngăn ngên: Gâp ŭch ma Brah Ndu, Mbơ̆ , jêh ri Yêsu Krist, Kôranh Brah he, ăn ma may nau yô̆, nau ueh, jêh ri nau đăp mpăn.$b$,false),
('bunong-vn','2TI',1,3,null,$b$Gâp tâm rnê ma Brah Ndu, Nơm u che gâp yơk, jêh ri nơm gâp yơk ma nuih n'hâm sŏng kloh jêh ri gâp kah gĭt ma may ƀa ƀơ dôl gâp mbơh sơm.$b$,true),
('bunong-vn','2TI',1,4,null,$b$Tơ lah gâp kah gĭt ma dak măt may, jêh ri nar măng ŭch ngăn saơ may, pô ri gâp mra bêng ma nau răm maak.$b$,false),
('bunong-vn','2TI',1,5,null,$b$Gâp kah gĭt lĕ ma nau may chroh răp jăp. Nau chroh nây gŭ jêh lor tâm u may H'Lôis jêh ri tâm mê̆ may H'Ônis, jêh ri gâp gĭt ngăn jêh ma nau chroh nây gŭ lĕ tâm may.$b$,true),
('bunong-vn','2TI',1,6,null,$b$Pô ri gâp nkah may ăn ntrôt tay nau Brah Ndu ăn jêh ma may ma nau gâp pah ti ta may.$b$,true),
('bunong-vn','2TI',1,7,null,$b$Yor lah Brah Ndu mâu ăn ôh ma he huêng nau klach, ƀiă lah huêng nau brah, blau rŏng jêh ri blau njrăng.$b$,false),
('bunong-vn','2TI',1,8,null,$b$Lơi prêng ôh mbơh nau Kôranh Brah he, mâu lah ma gâp, nơm jêng bu nă yor păng, ƀiă lah dơn nau rêh ni ndrel ma gâp yor nau mhe mhan ueh ma nau brah Brah Ndu,$b$,false),
('bunong-vn','2TI',1,9,null,$b$Nơm tâm rklaih jêh he, jêh ri kuăl jêh he ma nau kuăl kloh ueh, mâu di yor kan he ôh, ƀiă lah tĭng nâm nau păng săch, jêh ri tĭng nâm nau yô̆ păng ăn jêh ma he tâm Yêsu Krist lor ma lĕ rngôch rnôk n'ho ro.$b$,false),
('bunong-vn','2TI',1,10,null,$b$Jêh ri tâm mpơl aƀaơ aơ ma nau Nơm tâm rklaih he, Yêsu Krist văch jêh, Nơm ƀư rai jêh nau khĭt jêh ri tâm mpơl jêh nau rêh jêh ri nau mâu blau khĭt ma nau mhe mhan ueh.$b$,false),
('bunong-vn','2TI',1,11,null,$b$Ma nau mhe mhan ueh aơ yơh gâp jêng nơm nti jêh ri kôranh oh mon, geh nau ntăm sâm nti phung bu năch.$b$,true),
('bunong-vn','2TI',1,12,null,$b$Yor nau nây yơh gâp dơn nau rêh ni aơ; ƀiă lah gâp mâu prêng ôh, yor lah gâp gĭt ma mbu Nơm gâp chroh jêh ri gâp gĭt ngăn ma păng geh nau brah dơi chiă uănh ndơ gâp jao jêh ma păng tât nar nây.$b$,false),
('bunong-vn','2TI',1,13,null,$b$Ăn may djôt prăp tâm nau chroh jêh ri nau rŏng tâm Yêsu Krist nau tâm ntĭt tâm nau ngơi kloh may sŏk dơn jêh bơh gâp.$b$,true),
('bunong-vn','2TI',1,14,null,$b$Djôt prăp ndơ ueh jao jêh ma may ma Brah Huêng Ueh gŭ tâm he.$b$,true),
('bunong-vn','2TI',1,15,null,$b$May gĭt jêh lĕ phung tâm n'gor Asi cha lơi jêh gâp. Tâm phung khân păng geh Y-Phigel jêh ri Y-Hêrmôgen.$b$,true),
('bunong-vn','2TI',1,16,null,$b$Ăn Kôranh Brah yô̆ ma ngih Y-Ônêsiphor yor lah păng bonh jêh gâp ƀa ƀơ, jêh ri păng mâu prêng ôh ma rse rvăk gâp,$b$,false),
('bunong-vn','2TI',1,17,null,$b$ƀiă lah tơ lah păng tât jêh ta ƀon Rôm, păng joi gâp hâu ngăn, jêh ri păng saơ gâp.$b$,false),
('bunong-vn','2TI',1,18,null,$b$Gay ma Kôranh Brah tâm nar nây jêh ri may gĭt ngăn jêh lĕ nau păng kơl ta ƀon Êphêsô.$b$,false),
('bunong-vn','2TI',2,1,null,$b$Pô ri, hơi kon gâp ơi, ƀư ktang hom may nơm ma nau yô̆ tâm Yêsu Krist.$b$,true),
('bunong-vn','2TI',2,2,null,$b$Moh nau may tăng jêh bơh gâp ta năp âk bunuyh, ăn may jao nau nây ma phung bunuyh răp jăp dơi nti tâm ban lĕ ma phung êng.$b$,true),
('bunong-vn','2TI',2,3,null,$b$Dơn nau rêh ni ndrel ma gâp tâm ban ma du huê ta han ueh ma Brah Yêsu Krist.$b$,false),
('bunong-vn','2TI',2,4,null,$b$Mâu geh du huê ta han ôh dôl păng jêng ta han tâm rlŭk kan păng đah kan ƀon lan tơ lah păng ŭch ƀư maak ma nơm kuăl păng jêng ta han.$b$,false),
('bunong-vn','2TI',2,5,null,$b$Jêh ri du huê tâm rlong knŏng geh nau nkhôm tơ lah păng rlong tĭng nâm nau vay.$b$,false),
('bunong-vn','2TI',2,6,null,$b$Nơm ƀư mir hŏt mra pĕ play lor lơn.$b$,false),
('bunong-vn','2TI',2,7,null,$b$Ăn may mĭn ma nau gâp lah jêh ma may, yor lah Kôranh Brah mra ăn ma may nau gĭt rbăng tâm lĕ rngôch ndơ.$b$,false),
('bunong-vn','2TI',2,8,null,$b$Ăn may kah gĭt ma Yêsu Krist luh tă bơh ndŭl mpôl Y-Đavit, dâk rêh jêh bơh phung khĭt tĭng nâm nau mhe mhan ueh gâp nti.$b$,true),
('bunong-vn','2TI',2,9,null,$b$Ma nau nây gâp dơn nau rêh ni kŏ tât bu chăp gâp nâm bu bunuyh ƀai, ƀiă lah bu mâu chăp ôh Nau Brah Ndu Ngơi.$b$,false),
('bunong-vn','2TI',2,10,null,$b$Pô ri gâp srôih dơn lĕ yor phung Brah Ndu săch jêh, gay ma khân păng tâm ban lĕ, dơi geh nau tâm rklaih tâm Yêsu Krist ma nau chrêk rmah n'ho ro.$b$,true),
('bunong-vn','2TI',2,11,null,$b$Nau ngơi aơ jêng ngăn: Tơ lah he khĭt ndrel ma Păng, he mra dâk rêh lĕ ndrel ma Păng.$b$,false),
('bunong-vn','2TI',2,12,null,$b$Tơ lah he srôih, he mra chiă uănh ndrel ma Păng lĕ, tơ lah he dun Păng, Păng mra dun lĕ he.$b$,true),
('bunong-vn','2TI',2,13,null,$b$Tơ lah he mâu gŭ răp jăp đah Păng ôh, Păng ăt gŭ răp jăp lĕ. Yor lah Păng mâu dơi dun ma Păng nơm ôh.$b$,true),
('bunong-vn','2TI',2,14,null,$b$Ăn nkah tay ma khân păng nau aơ, jêh ri ntăm ma khân păng ta năp Brah Ndu, ăn khân păng dun nau tâm rlăch ma rplay ngơi, nau nây mâu khlay ôh, knŏng ƀư rai mbu nơm gŭ iăt.$b$,true),
('bunong-vn','2TI',2,15,null,$b$Srôih pah kan kŏ tât dơi gŭ ta năp Brah Ndu jêng du huê bunuyh păng dơn, du huê pah kan mâu mra geh nau prêng ôh, blau tâm pă nau ngơi ngăn ma nau sŏng.$b$,false),
('bunong-vn','2TI',2,16,null,$b$Ƀiă lah dun ma nau ngơi mâu khlay jêh ri ƀơ̆ ƀơch, yor lah mbu nơm djôt prăp nau nây mra jêng jru lơn tâm nau mâu blau yơk ma Brah Ndu.$b$,false),
('bunong-vn','2TI',2,17,null,$b$Jêh ri nau khân păng ngơi mra sa nâm bu nau ôm. Tâm phung khân păng geh Y-Himênê jêh ri Y-Philêt.$b$,false),
('bunong-vn','2TI',2,18,null,$b$Khân păng cha lơi jêh nau nanê̆, lah ma nar dâk rêh tât jêh, jêh ri khân păng ƀư tŭp âk nau chroh bu.$b$,false),
('bunong-vn','2TI',2,19,null,$b$Ƀiă lah ntur nâp Brah Ndu ăt gŭ râng, geh nau tâp pŏng aơ: “Kôranh Brah gĭt năl mbu nơm jêng ndơ Păng”, jêh ri: “Ăn lĕ rngôch mbu nơm kuăl amoh Kôranh Brah du ngai đah nau tih”.$b$,false),
('bunong-vn','2TI',2,20,null,$b$Tâm du mlâm ngih toyh mâu geh ôh knŏng khăl ngan mah jêh ri prăk, ƀiă lah geh lĕ khăl ngan si jêh ri neh, ƀă bu dŏng ma kan khlay, ƀă bu dŏng ma kan mâu khlay.$b$,false),
('bunong-vn','2TI',2,21,null,$b$Pô ri tơ lah bu ƀư kloh păng nơm bơh nau nây, păng mra jêng khăl ngan bu yơk, kloh ueh, khlay ma kôranh păng, khư ma lĕ kan ueh.$b$,false),
('bunong-vn','2TI',2,22,null,$b$Ăn may dun ma nau nglay săk phung druh ndăm ŭch jêh ri tĭng joi nau sŏng, nau chroh, nau rŏng, nau đăp mpăn ndrel ma phung kuăl mbơh sơm ma amoh Kôranh Brah ma nuih n'hâm kloh.$b$,true),
('bunong-vn','2TI',2,23,null,$b$Dun ma nau tâm rlăch rluk jêh ri mâu khlay, yor lah may gĭt nau nây dơi tât ma nau tâm djrel.$b$,false),
('bunong-vn','2TI',2,24,null,$b$Jêh ri oh mon Kôranh Brah mâu mra geh nau tâm djrel ôh, ƀiă lah jêng rah rơch đah lĕ rngôch, dơi nti lah ma bu jêh ri blau srôih.$b$,false),
('bunong-vn','2TI',2,25,null,$b$Păng mra nkra phung tâm rdâng đah păng ma nau rdơ̆ , tâm nau kâp gân ma Brah Ndu mra ăn khân păng rmal nau tih, gay ma khân păng tât ma nau gĭt rbăng nau ngăn.$b$,true),
('bunong-vn','2TI',2,26,null,$b$Jêh ri gay ma khân păng mra klaih bơh dăk brah mhĭk, phung păng sŏk jêh, ŭch nchâp khân păng ƀư nau păng ŭch.$b$,false),
('bunong-vn','2TI',3,1,null,$b$Ăn may gĭt rbăng nau aơ, tâm rnôk nglĕ dŭt mra tât nar jêr.$b$,true),
('bunong-vn','2TI',3,2,null,$b$Yor lah bunuyh mra jêng nkrêp mbeh, rŏng ma prăk, blau khư êng, sưr rlau, ngơi djơh, dăng bôk đah mê̆ mbơ̆ , mâu kah gĭt tôr, mâu geh nau yơk ma Brah Ndu,$b$,false),
('bunong-vn','2TI',3,3,null,$b$mâu chrê ma bu, mâu gĭt yô̆, nchơt, rlau keh, djơh mhĭk, rlăng đah bunuyh ueh.$b$,false),
('bunong-vn','2TI',3,4,null,$b$Ƀlăch ƀlêr, gơnh nuih, bêng ma nau sưr, rŏng ma nau pâl âk lơn ma Brah Ndu,$b$,false),
('bunong-vn','2TI',3,5,null,$b$tâm mpơl nau yơk ma Brah Ndu pa dih ƀiă lah dun lơi nau brah dơi geh bơh nau nây. Ăn may du ngai bơh phung nây.$b$,false),
('bunong-vn','2TI',3,6,null,$b$Yor lah tâm phung khân păng geh ƀa ƀă lăp tâm ngih bu jêh ri ndơm phung bu ur geh nau mĭn rdja, jâk ma nau tih, geh nau nchâp jêh bơh nau nglay săk ŭch.$b$,false),
('bunong-vn','2TI',3,7,null,$b$Khân păng nti ƀa ƀơ, ƀiă lah mâu mâp tât ma nau gĭt rbăng nau ngăn.$b$,true),
('bunong-vn','2TI',3,8,null,$b$Jêh ri tâm ban ma Y-Janes jêh ri Y-Jambrê tâm rdâng đah Y-Môis, tâm ban lĕ phung bunuyh aơ tâm rdâng đah nau ngăn. Nau mĭn khân păng ôm jêh, jêh ri khân păng dun jêh ma nau chroh.$b$,false),
('bunong-vn','2TI',3,9,null,$b$Ƀiă lah kan khân păng mâu mra jêng ôh, yor lah nau rluk khân păng mra tâm mpơl ma lĕ rngôch nâm bu tât jêh ma bar hê nây.$b$,true),
('bunong-vn','2TI',3,10,null,$b$Ƀiă lah may tĭng ndô̆ jêh nau gâp nti lah, nau gâp gŭ ngao krao sach, nau gâp tĭng joi, nau gâp chroh, nau gâp srôih, nau gâp rŏng, nau gâp gŭ nâp.$b$,true),
('bunong-vn','2TI',3,11,null,$b$Nau bu ƀư mhĭk ma gâp, nau rêh ni gâp, nau tât jêh ma gâp ta ƀon Antiôs, ta ƀon Ikôni, jêh ri ta ƀon Listrơ, moh nau bu ƀư mhĭk gâp dơn jêh, ƀiă lah Kôranh Brah tâm rklaih jêh gâp bơh lĕ nau nây.$b$,false),
('bunong-vn','2TI',3,12,null,$b$Nanê̆ mbu nơm ŭch gŭ sŏng srăng tâm Yêsu Krist mra dơn nau bu ƀư mhĭk.$b$,false),
('bunong-vn','2TI',3,13,null,$b$Ƀiă lah phung ƀai jêh ri phung mƀruh mra jêng mhĭk lơn đŏng ndơm bu jêh ri ndơm jêh păng nơm.$b$,false),
('bunong-vn','2TI',3,14,null,$b$Ƀiă lah ăn may gŭ nâp tâm nau may nti jêh, jêh ri chroh rjăp jêh, yor lah may gĭt tă bơh mbu nơm may nti jêh nau nây.$b$,true),
('bunong-vn','2TI',3,15,null,$b$Bơh may hôm jêng kon se may gĭt jêh sămƀŭt kloh ueh dơi ăn may gĭt rbăng nau tâm rklaih ma nau chroh tâm Yêsu Krist.$b$,false),
('bunong-vn','2TI',3,16,null,$b$Lĕ rngôch nau nchih luh bơh Brah Ndu nơm nsŭk nsôr jêng khlay prăp nti lah, nduyh, nkra, sâm nti bu tâm nau sŏng,$b$,false),
('bunong-vn','2TI',3,17,null,$b$gay ma bunuyh Brah Ndu dơi jêng rah vah, jêh ri khư ma lĕ kan ueh.$b$,false),
('bunong-vn','2TI',4,1,null,$b$Yor Păng mra tâm mpơl, jêh ri yor ƀon bri hađăch Păng gâp ntăm ma may ta năp Brah Ndu, jêh ri ta năp Yêsu Krist, Nơm mra phat dôih phung rêh jêh ri phung khĭt,$b$,true),
('bunong-vn','2TI',4,2,null,$b$ăn may nti Nau Brah Ndu Ngơi srôih tơ lah mông găl mâu lah mâu găl ôh, rblang ăn nanê̆, nduyh, ăn tâm n'hao nuih ma nau rdơ̆ jêh ri nau tâm nti.$b$,false),
('bunong-vn','2TI',4,3,null,$b$Yor lah mra tât du rnôk phung bunuyh mâu hôm ŭch iăt nau nti kloh, ƀiă lah geh nau chiăt ŭch iăt nau maak, khân păng mra tâm rƀŭn phung kôranh nơm nti tĭng nâm nau khân păng ŭch.$b$,false),
('bunong-vn','2TI',4,4,null,$b$Khân păng mra dun iăt nau ngăn, jêh ri rle n'gĭl ma nau nkoch bri ơm.$b$,false),
('bunong-vn','2TI',4,5,null,$b$Ƀiă lah may, ăn may jêng di keh tâm lĕ rngôch ndơ, srôih dơn nau rêh ni pah kan du huê nsong nti lah, ƀư kan may ăn ueh.$b$,false),
('bunong-vn','2TI',4,6,null,$b$Yor lah gâp jêng jêh mpa ƀư brah bu tŏ, jêh ri nar gâp hăn dăch jêh.$b$,true),
('bunong-vn','2TI',4,7,null,$b$Gâp tâm lơh jêh nau tâm lơh ueh, ntŭk gâp nchuăt lôch jêh, gâp djôt prăp nau chroh.$b$,false),
('bunong-vn','2TI',4,8,null,$b$Bơh aơ rlet pa năp gâp geh đon hađăch nau sŏng prăp jêh ma gâp, Kôranh Brah, Nơm phat dôih sŏng, mra ăn đon nây ma gâp tâm nar nây, jêh ri mâu di knŏng ma gâp ôh ƀiă lah nđâp ma phung rŏng ma nau Păng mra văch.$b$,false),
('bunong-vn','2TI',4,9,null,$b$Văch hom ta gâp ăn gơnh.$b$,true),
('bunong-vn','2TI',4,10,null,$b$Y-Đêmas cha lơi jêh gâp, yor păng rŏng ma neh ntu aơ jêh ri păng hăn jêh ta ƀon Têsalônik; Y-Kresen hăn jêh ta ƀon Galati, Y-Tit ta n'gor Đalmati.$b$,false),
('bunong-vn','2TI',4,11,null,$b$Knŏng du huê Y-Luk gŭ ndrel ma gâp. Sŏk Y-Markôs jêh ri njŭn păng ndrel ma may, yor lah păng jêng khlay ma gâp tâm nau nti lah.$b$,false),
('bunong-vn','2TI',4,12,null,$b$Gâp njuăl Y-Tisik hăn ta ƀon Êphêsô.$b$,false),
('bunong-vn','2TI',4,13,null,$b$Tơ lah may mra văch djôt leo aơ mbâl gâp cha lơi ta ƀon Trôas tâm ngih Y-Karpus, jêh ri ndrom sămƀŭt, khlay ngăn ngên ndrom sămƀŭt ntâu,$b$,false),
('bunong-vn','2TI',4,14,null,$b$Y-Aleksandrơ, bunuyh chiăr kông, ƀư jêh âk nau mhĭk ma gâp. Kôranh Brah mra mplơ̆ sĭt ma păng tĭng nâm kan păng pah.$b$,false),
('bunong-vn','2TI',4,15,null,$b$May nơm njrăng lĕ ma păng, yor lah păng tâm rdâng ktang ngăn ma nau hên nti lah.$b$,false),
('bunong-vn','2TI',4,16,null,$b$Tâm nau gâp n'gang gâp nơm lor lơn, mâu geh nơm kơl gâp ôh, ƀiă lah lĕ rngôch cha lơi jêh gâp. Lơi ăn Kôranh Brah kơp nau nây ma khân păng ôh.$b$,true),
('bunong-vn','2TI',4,17,null,$b$Ƀiă lah Kôranh Brah kơl gâp jêh ri ƀư ktang jêh gâp, gay gâp dơi nti lah ăp Nau Brah Ndu Ngơi, jêh ri gay ma lĕ rngôch phung bu năch dơi tăng. Pô ri gâp klaih jêh bơh trôm mbung yau mŭr.$b$,false),
('bunong-vn','2TI',4,18,null,$b$Kôranh Brah mra ăn kon me ma gâp bơh lĕ kan mhĭk, jêh ri Păng mra tâm rklaih gâp gay ăn gâp lăp tâm ƀon bri hađăch Păng tâm trôk. Ma Păng geh nau chrêk rmah tâm lĕ rngôch rnôk. Amen.$b$,false),
('bunong-vn','2TI',4,19,null,$b$Khâl hom đah H'Prisil jêh ri Y-Akilas jêh ri ndŭl mpôl Y-Ônêsiphor.$b$,true),
('bunong-vn','2TI',4,20,null,$b$Y-Êrast gŭ ta ƀon Kôrintô, jêh ri gâp lơi Y-Trôphim gŭ bêch kuet ta ƀon Milê.$b$,false),
('bunong-vn','2TI',4,21,null,$b$Ăn may rlong joi trong văch lor ta yan puh Y-Ôbulus, Y-Puden, Y-Linus, Y-Klôdia jêh ri lĕ rngôch phung oh nâu khâl đah may.$b$,false),
('bunong-vn','2TI',4,22,null,$b$Ăn Kôranh Brah gŭ ndrel ma huêng may. Ăn nau yô̆ gŭ ndrel ma may.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','2TI',1,1,0,'heading',$b$Nơm Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','2TI',1,3,1,'heading',$b$Nau Y-Pôl Rŏng Ma Y-Timôthê$b$),
('bunong-vn','2TI',1,6,2,'heading',$b$Nau N'hao Nuih Ma Nau Gŭ Nâp Tâm Nau Chroh Jêh Ri Srôih Tâm Kan Kôranh Brah$b$),
('bunong-vn','2TI',2,1,0,'heading',$b$Nau Hŏt Rgănh Phung Pah Kan Ma Kôranh Brah$b$),
('bunong-vn','2TI',2,14,1,'heading',$b$Nau Gŭ Ngao Krau Sach Đah Phung Cha lơi Jêh Nau Nti Kloh$b$),
('bunong-vn','2TI',3,1,0,'heading',$b$Nau Mbơh Lor Nau djơh Mhĭk Ta Neh Ntu$b$),
('bunong-vn','2TI',4,6,0,'heading',$b$Nau Y-Pôl Mĭn Ma Nau Nar Păng Mra Khĭt Dăch Jêh$b$),
('bunong-vn','2TI',4,9,1,'heading',$b$Nau Nti Êng Êng$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'TIT', $b$Y-Tit$b$, $b$["Sămƀŭt Y-Pôl Njuăl Ma", "Y-TIT"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','TIT',1,1,null,$b$Y-Pôl, oh mon Brah Ndu, jêh ri kôranh oh mon Yêsu Krist, gay ma tâm n'hao nau chroh phung Brah Ndu săch jêh, jêh ri nau khân păng gĭt rbăng ma nau ngăn tĭng nâm nau blau yơk ma Brah Ndu,$b$,true),
('bunong-vn','TIT',1,2,null,$b$tâm nau kâp gân ma nau rêh n'ho ro Brah Ndu ton jêh bơh âk rnôk, jêh ri păng mâu mâp mƀruh ôh,$b$,false),
('bunong-vn','TIT',1,3,null,$b$jêh ri tâm rnôk di păng tâm mpơl jêh nau păng ngơi tâm nau nti lah păng jao jêh ma gâp tĭng nâm Brah Ndu, Nơm Tâm Rklaih he, ntăm jêh.$b$,false),
('bunong-vn','TIT',1,4,null,$b$Njuăl sămƀŭt ma Y-Tit, kon gâp ngăn tâm nau he chroh tâm ban: Ăn nau yô̆ jêh ri nau đăp mpăn bơh Brah Ndu, Mbơ̆ , jêh ri Yêsu Krist, Nơm Tâm Rklaih he.$b$,false),
('bunong-vn','TIT',1,5,null,$b$Gâp cha lơi jêh may tâm n'gor Kret, gay ma may nkra nau ê hŏ ueh ôh, jêh ri tĭng nâm nau gâp ntăm, ăn may săch phung bu ranh tâm ăp ƀon,$b$,true),
('bunong-vn','TIT',1,6,null,$b$tơ lah geh bunuyh bu mâu dơi nduyh, gŭ knŏng du huê ur, geh kon gŭ răp jăp bu mâu geh nau phong ma nau tih mâu lah ma nau dăng bôk ôh.$b$,false),
('bunong-vn','TIT',1,7,null,$b$Yor lah ăn phung kôranh chiă uănh jêng bunuyh bu mâu dơi nduyh, nâm bu du huê oh mon Brah Ndu; păng mâu jêng sưr, gơnh nuih hay nhêt dak play kriăk ƀâu, janh ƀai, mâu lah hay ma prăk âk ôh,$b$,true),
('bunong-vn','TIT',1,8,null,$b$ƀiă lah ăn păng jêng bunuyh rom bu, mĭt jiăng đah phung ueh, blau njrăng, sŏng, kloh ueh, di keh;$b$,false),
('bunong-vn','TIT',1,9,null,$b$djôt prăp Nau Brah Ndu Ngơi ngăn tâm ban ma bu hŏ nti jêh, gay ma păng dơi tâm n'hao nuih tĭng nâm nau nti kloh, jêh ri dơi đah phung tâm rlăch ma nau nây.$b$,false),
('bunong-vn','TIT',1,10,null,$b$Geh âk ngăn phung bunuyh dăng bôk, hâu ngăn ngên tâm phung koh ntâu, phung ngơi nau mâu khlay, jêh ri phung ndơm.$b$,true),
('bunong-vn','TIT',1,11,null,$b$Ăn khân păng gŭ rklăk yor lah khân păng ƀư rŭng lĕ ndŭl mpôl tâm du mlâm ngih dôl nti nau bu mâu vay nti yor khân păng rŏng ma prăk lă lêng.$b$,true),
('bunong-vn','TIT',1,12,null,$b$Du huê tâm phung khân păng, kôranh nơm mbơh lor khân păng nơm lah jêh: “Phung Kret mƀruh ƀa ƀơ, jêng phung mpa janh, ndŭl ƀlao”.$b$,false),
('bunong-vn','TIT',1,13,null,$b$Nau mbơh aơ ngăn. Yor nây ăn may nduyh khân păng ma nau ktang gay ma khân păng geh nau chroh kloh.$b$,false),
('bunong-vn','TIT',1,14,null,$b$Jêh ri lơi khân păng dơn ôh nau phung Yuđa nkoch bri mƀruh, jêh ri ma nau bunuyh ntăm, ăn cha lơi nau nanê̆.$b$,false),
('bunong-vn','TIT',1,15,null,$b$Lĕ rngôch mpa jêng kloh da dê ma phung kloh, ƀiă lah ma phung ƀơ̆ jêh ri ma phung mâu chroh mâu geh du ntil ndơ kloh ôh, ƀiă lah nau mĭn jêh ri nuih n'hâm sŏng khân păng nơm ôm jêh.$b$,false),
('bunong-vn','TIT',1,16,null,$b$Khân păng nkoch khân păng nơm gĭt năl Brah Ndu, ƀiă lah khân păng dun nau nây đah kan khân păng ƀư. Khân păng jêng phung bu tâm rmot, dăng bôk, jêh ri mâu dơi ƀư du ntil kan ueh ôh.$b$,false),
('bunong-vn','TIT',2,1,null,$b$Ƀiă lah ăn may ngơi nau di ma nau nti kloh.$b$,true),
('bunong-vn','TIT',2,2,null,$b$Ntăm ma phung bu ranh mra di keh, sŏng srăng, blau njrăng nâp tâm nau chroh, nau rŏng, jêh ri nau srôih.$b$,false),
('bunong-vn','TIT',2,3,null,$b$Ntăm ma bu ranh bu ur gŭ ngao krao sach ma nau kloh ueh, mâu jêng bunuyh ngơi mhĭk ma bu ôh, mâu lĕ jêng hay ma dak play kriăk ƀâu, dơi nti moh nau jêng ueh.$b$,true),
('bunong-vn','TIT',2,4,null,$b$Blau sâm nti ma phung bu ur druh rŏng ma sai jêh ri kon khân păng,$b$,true),
('bunong-vn','TIT',2,5,null,$b$blau njrăng gŭ kloh ueh, blau pah kan tâm ngih, jêng ueh, blau tông ma sai khân păng, gay lơi ăn bu mưch ma Nau Brah Ndu Ngơi.$b$,false),
('bunong-vn','TIT',2,6,null,$b$Ntăm lĕ ma phung bu klâu ndăm ăn gŭ di keh.$b$,true),
('bunong-vn','TIT',2,7,null,$b$Tâm mpơl may nơm tâm lĕ rngôch nau jêng nau tâm ntĭt tâm kan ueh, jêh ri tâm nau may nti lah, tâm mpơl nau kloh, nau khư,$b$,false),
('bunong-vn','TIT',2,8,null,$b$nau ngơi di mâu geh nau bu dơi nduyh, gay ma nơm rlăng mra bêk, mâu geh du ntil nau dơi ngơi mhĭk ma he.$b$,false),
('bunong-vn','TIT',2,9,null,$b$Ntăm ma phung oh mon ăn tông ma kôranh khân păng, ƀư maak ma khân păng tâm lĕ rngôch ndơ, mâu ngơi tâm rdâng ôh.$b$,true),
('bunong-vn','TIT',2,10,null,$b$Mâu ntŭng ôh, ƀiă lah tâm mpơl ƀa ƀơ nau răp jăp rah vah, gay ma tâm lĕ rngôch nau khân păng dơi yơk ma nau nti bơh Brah Ndu, Nơm Tâm Rklaih he.$b$,true),
('bunong-vn','TIT',2,11,null,$b$Yor lah nau Brah Ndu yô̆ tâm mpơl jêh, dơi tâm rklaih lĕ rngôch bunuyh.$b$,true),
('bunong-vn','TIT',2,12,null,$b$Nau yô̆ nây nti ma he ăn dun nau mâu blau yơk ma Brah Ndu, jêh ri nau kơnh ma neh ntu, jêh ri gŭ rêh tâm rnôk aơ tĭng nâm nau blau mĭn, nau sŏng,$b$,false),
('bunong-vn','TIT',2,13,null,$b$jêh ri nau blau kâp gân răm maak jêh ri nau tâm mpơl ma nau chrêk rmah Brah Ndu toyh he, jêh ri Nơm Tâm Rklaih he, Yêsu Krist.$b$,false),
('bunong-vn','TIT',2,14,null,$b$Păng jao jêh păng nơm ma he, gay ma tâm chuai he bơh lĕ nau tih, jêh ri ƀư kloh păng nơm du phung ndŭl mpôl geh nau duh nđơr ma kan ueh.$b$,false),
('bunong-vn','TIT',2,15,null,$b$Nti nau nây; tâm n'hao nuih jêh ri nduyh ma lĕ nau dơi. Lơi ăn bu tâm rmot ma may ôh.$b$,true),
('bunong-vn','TIT',3,1,null,$b$Ăn nkah ma khân păng blau tông phung kôranh chiă uănh jêh ri phung geh nau dơi, ăn tông bâr, kâp ƀư lĕ kan ueh,$b$,true),
('bunong-vn','TIT',3,2,null,$b$mâu ngơi mhĭk ma bu ôh, gŭ đăp mpăn, blau njrăng, jêh ri bêng ma nau rdơ̆ rbăn ma lĕ rngôch bunuyh.$b$,false),
('bunong-vn','TIT',3,3,null,$b$Yor lah sa ơm ri he tâm ban lĕ jêng rluk, mâu blau tông bâr, nkhah du, jêng dĭk ma ăp ntil nau kơnh jêh ri ma nau nglay săk ŭch, gŭ rêh tâm nau djơh mhĭk jêh ri tâm nau kơnh, bu tâm rmot jêh ri he tâm rmot ndrăng he.$b$,false),
('bunong-vn','TIT',3,4,null,$b$Ƀiă lah tơ lah nau ueh Brah Ndu, Nơm Tâm Rklaih he, jêh ri nau păng rŏng ma bunuyh tâm mpơl jêh,$b$,false),
('bunong-vn','TIT',3,5,null,$b$Păng tâm rklaih jêh he mâu di yor kan bơh nau sŏng he ƀư jêh ôh, ƀiă lah tĭng nâm nau păng yô̆ ma he, ma nau ƀư kloh bơh nau deh mhe, jêh ri nau ƀư mhe tay bơh Brah Huêng Ueh,$b$,false),
('bunong-vn','TIT',3,6,null,$b$Păng nkhŭt jêh ma he rmeh ler ma Yêsu Krist, Nơm Tâm Rklaih he,$b$,false),
('bunong-vn','TIT',3,7,null,$b$gay ma he mra geh nau kơp sŏng ma nau Păng yô̆, jêh ri jêng phung dơn tâm nau kâp gân ma nau rêh n'ho ro.$b$,false),
('bunong-vn','TIT',3,8,null,$b$Nau ngơi aơ jêng ngăn. Gâp ŭch ma may ƀư ngăn nau aơ, gay ma phung chroh jêh ma Brah Ndu mra blau njrăng ƀư kan ueh, nau nây ueh jêh ri khlay ma bunuyh.$b$,true),
('bunong-vn','TIT',3,9,null,$b$Ƀiă lah dun nau tâm rlăch rluk, nau ƀoi yau u che, nau tâm djrel, jêh ri nau tâm rlăch ma nau vay, yor lah nau nây mâu khlay ôh jêh ri dơm dam.$b$,false),
('bunong-vn','TIT',3,10,null,$b$Bi ma bunuyh joi nau tâm nkhah, jêh nduyh păng nguay mâu lah bar tơ̆ lơi geh nau đah păng ôh.$b$,false),
('bunong-vn','TIT',3,11,null,$b$Yor lah may gĭt jêh bunuyh tâm ban pô nây jêng nkhah du jêh, jêh ri ƀư tih; dôl ƀư pô nây păng phat dôih păng nơm yơh.$b$,false),
('bunong-vn','TIT',3,12,null,$b$Tơ lah gâp njuăl ma may Y-Artêmas mâu lah Y-Tisik, ăn may ndal văch tâm mâp đah gâp ta ƀon Nikôpôlis, yor lah gâp mĭn ŭch gŭ ta nây dôl yan puh.$b$,true),
('bunong-vn','TIT',3,13,null,$b$Njrăng ma nau kơl Y-Sênas, kôranh nơm nti nau vay, jêh ri Y-Apôlôs, dôl khân păng sak nsong lơi ăn khân păng pưt kƀah du ntil ndơ ôh.$b$,false),
('bunong-vn','TIT',3,14,null,$b$Ăn nđâp phung he lĕ nti ƀư kan ueh gay dơi kơl tơ lah geh kan ndal, pô ri lơi he pưt play blau kơl.$b$,true),
('bunong-vn','TIT',3,15,null,$b$Lĕ rngôch phung gŭ ndrel gâp njuăl nau khâl đah may. Ăn may khâl đah phung rŏng ma hên tâm nau chroh. Ăn nau yô̆ gŭ ndrel ma lĕ rngôch khân may.$b$,false);
