('bunong-vn','TIT',1,5,1,'heading',$b$Ntăm Ma Y-Tit Rdâk Phung Ngih Brah Ndu Ta N'gor Kơrêt$b$),
('bunong-vn','TIT',1,10,2,'heading',$b$Ăn Păng Dơi Đah Phung Nti Tih$b$),
('bunong-vn','TIT',2,1,0,'heading',$b$Nau Tâm N'hao Nuih Ma Phung Bu Ranh Jêh Ri Phung Druh Ndăm$b$),
('bunong-vn','TIT',2,11,1,'heading',$b$Nau Yô̆ Brah Ndu Tâm Mpơl Jêh$b$),
('bunong-vn','TIT',3,1,0,'heading',$b$Nau Ntăm Ma Y-Tit Mra Nti$b$),
('bunong-vn','TIT',3,12,1,'heading',$b$Nau Ntăm Êng Êng Nau Khâl$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'PHM', $b$Y-Philêmôn$b$, $b$["Sămƀŭt Y-Pôl Njuăl Ma", "Y-PHILÊMÔN"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PHM',1,1,null,$b$Y-Pôl, bu nă Yêsu Krist, jêh ri oh he Y-Timôthê, njuăl sămƀŭt ma Y-Philêmôn, nơm hên rŏng jêh ri nơm pah kan ndrel ma hên,$b$,true),
('bunong-vn','PHM',1,2,null,$b$ma ruh hên H'Apia jêh ri ma Y-Archip, bunuyh tâm lơh ndrel ma hên jêh ri ma phung ngih Brah Ndu tâm ngih may.$b$,false),
('bunong-vn','PHM',1,3,null,$b$Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn bơh Brah Ndu, Mbơ̆ he, jêh ri bơh Brah Yêsu Krist.$b$,false),
('bunong-vn','PHM',1,4,null,$b$Gâp tâm rnê ma Brah Ndu gâp ƀa ƀơ, kah gĭt ma may dôl gâp mbơh sơm,$b$,true),
('bunong-vn','PHM',1,5,null,$b$yor lah gâp tăng jêh ma nau may chroh ma Brah Yêsu, jêh ri ma nau may rŏng ma lĕ rngôch phung kloh ueh.$b$,false),
('bunong-vn','PHM',1,6,null,$b$Gâp dăn ma nau tâm rnglăp ma nau may chroh dơi tâm n'hao nau gĭt rbăng ma lĕ nau ueh he geh jêh tâm Brah Krist.$b$,false),
('bunong-vn','PHM',1,7,null,$b$Yor lah, hơi oh gâp ơi, gâp geh âk nau maak jêh ri nau bonh leng bơh nau may rŏng, yor lah nuih n'hâm phung kloh ueh geh nau đăp mpăn yor may.$b$,false),
('bunong-vn','PHM',1,8,null,$b$Yor lah tâm Brah Krist gâp geh lĕ nau janh ntăm ma may ƀư nau di,$b$,true),
('bunong-vn','PHM',1,9,null,$b$ƀiă lah yor nau rŏng ma may, gâp vơh vơl pô aơ, gâp nơm, Y-Pôl, du huê bu ranh, jêh ri aƀaơ jêng bu nă yor Yêsu Krist.$b$,false),
('bunong-vn','PHM',1,10,null,$b$Gâp vơh vơl ma may yor kon gâp, nơm gâp deh jêh tâm rse rvăk, Y-Ônêsim.$b$,false),
('bunong-vn','PHM',1,11,null,$b$Kăl e ri păng mâu jêng khlay ma may ôh, ƀiă lah aƀaơ păng jêng khlay jêh ma may jêh ri ma gâp.$b$,false),
('bunong-vn','PHM',1,12,null,$b$Gâp mplơ̆ păng ma may, păng jêng ndŭl proch gâp nơm.$b$,false),
('bunong-vn','PHM',1,13,null,$b$Gâp ŭch ngăn ma păng ndrel ma gâp, gay ma păng pah kan ma gâp tâm tang ma may dôl gâp gŭ tâm rse rvăk yor nau mhe mhan ueh,$b$,false),
('bunong-vn','PHM',1,14,null,$b$ƀiă lah gâp mâu ŭch ƀư ôh nau nây tơ lah may mâu dơn, gay ma lơi ăn gâp nchâp may ƀư ueh ôh, ƀiă lah tĭng nâm nau may ŭch.$b$,false),
('bunong-vn','PHM',1,15,null,$b$Klăp lah yor nau aơ păng tâm nkhah đah may ƀât lât, gay ma may dơi geh păng n'ho ro,$b$,false),
('bunong-vn','PHM',1,16,null,$b$mâu di nâm bu du huê dĭk rlau lơn ma dĭk, păng jêng du huê oh he rŏng ngăn ngên, nanê̆ ma gâp, ƀiă lah rlau lơn ma may, tâm nglay săk jêh ri tâm Kôranh Brah.$b$,false),
('bunong-vn','PHM',1,17,null,$b$Pô ri, tơ lah may kơp gâp jêng mĭt jiăng may, rom păng nâm bu gâp nơm.$b$,true),
('bunong-vn','PHM',1,18,null,$b$Tơ lah păng ƀư tih ma may, mâu lah tơ lah păng iang rnon may, gâp mra trok an.$b$,false),
('bunong-vn','PHM',1,19,null,$b$Gâp nơm, Y-Pôl, nchih nau aơ ma ti gâp nơm. Gâp mra trok rnon nây, ƀiă lah gâp mâu lah ôh ma may iang may nơm ma gâp.$b$,false),
('bunong-vn','PHM',1,20,null,$b$Hơi oh ơi, gâp ŭch geh nau ueh uĭn aơ bơh may tâm Kôranh Brah. Ăn mpăn nuih n'hâm gâp tâm Brah Krist.$b$,false),
('bunong-vn','PHM',1,21,null,$b$Gâp nchih ma may yor lah gâp rnơm ma nau may tông bâr, jêh ri gâp gĭt may mra ƀư rlau lơn ma nau gâp lah.$b$,true),
('bunong-vn','PHM',1,22,null,$b$Tâm ban lĕ nkra hom ntŭk gŭ ma gâp, yor lah gâp kâp gân mra tât ta may yor nau may mbơh sơm.$b$,false),
('bunong-vn','PHM',1,23,null,$b$Y-Êpapras, nơm jêng bu nă ndrel ma gâp tâm Yêsu Krist, njuăl nau khâl đah may,$b$,true),
('bunong-vn','PHM',1,24,null,$b$jêh ri Y-Markôs, Y-Aristar, Y-Đêmas, jêh ri Y-Luk, phung pah kan ndrel ma gâp.$b$,false),
('bunong-vn','PHM',1,25,null,$b$Ăn nau yô̆ bơh Kôranh Brah he, Yêsu Krist, gŭ ndrel ma huêng may.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','PHM',1,1,0,'heading',$b$Nơm Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','PHM',1,4,1,'heading',$b$Nau Y-Pôl Tâm Rnê Yor Nau Chroh Jêh Ri Nau Rŏng Y-Philêmôn$b$),
('bunong-vn','PHM',1,8,2,'heading',$b$Y-Pôl Kơl N'gang Y-Ônêsim$b$),
('bunong-vn','PHM',1,21,3,'heading',$b$Nau Khâl$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'HEB', $b$Hêbrơ$b$, $b$["Sămƀŭt Njuăl Ma Phung", "HÊBRƠ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','HEB',1,1,null,$b$Tâm âk nau jêh ri tâm âk trong Brah Ndu ngơi jêh kăl e ma phung che he ma phung kôranh nơm mbơh lor;$b$,true),
('bunong-vn','HEB',1,2,null,$b$Ƀiă lah tâm nar dăch lôch aơ Păng ngơi jêh ma he đah Kon Păng Nơm, Brah Ndu ăn Păng jêng Nơm dơn lĕ rngôch drăp ndơ, jêh ri Păng đŏng rhăk njêng neh ntu.$b$,false),
('bunong-vn','HEB',1,3,null,$b$Kon Păng aơ jêng nau nchrat ral bơh nau chrêk rmah Păng, jêh ri jêng rup ma Brah Ndu. Păng kuăn rdâng lĕ rngôch ndơ ma nau Păng ngơi geh brah. Jêh Păng ƀư kloh nau tih, Păng gŭ mpeh pa ma nau chrêk rmah ta klơ.$b$,false),
('bunong-vn','HEB',1,4,null,$b$Păng jêng toyh lơn ma phung Tông mpăr ueh Brah Ndu nâm bu amoh Păng jêng khlay lơn ma amoh khân păng.$b$,true),
('bunong-vn','HEB',1,5,null,$b$Yor lah ma mbu nơm Brah Ndu mâp lah jêh ma Tông mpăr ueh pô aơ: “May jêng Kon bu klâu gâp, gâp deh jêh ma may tâm nar aơ.” Jêh ri: “Gâp jêng Mbơ̆ Păng, jêh ri Păng mra jêng Kon bu klâu gâp?”$b$,false),
('bunong-vn','HEB',1,6,null,$b$Jêh ri tơ lah Păng ăn du huê mhe deh tal lor lăp tâm neh ntu, Păng lah: “Ăn lĕ rngôch phung Tông mpăr ueh Brah Ndu yơk mbah ma Păng.”$b$,true),
('bunong-vn','HEB',1,7,null,$b$Păng lah ma phung Tông mpăr ueh Brah Ndu: “Păng ăn phung Tông mpăr ueh Păng jêng sial, jêh ri ma phung pah kan ma Păng jêng mpiăt ŭnh.”$b$,true),
('bunong-vn','HEB',1,8,null,$b$Ƀiă lah, Păng lah ma Kon bu klâu Păng: “Ơ Brah Ndu, sưng hađăch may gŭ ƀa ƀơ n'ho ro. Jêh ri mâng hađăch may, jêng mâng hađăch sŏng srăng.$b$,true),
('bunong-vn','HEB',1,9,null,$b$May rŏng jêh ma nau sŏng, jêh ri may tâm rmot jêh ma nau tih. Yor nây ơ Brah Ndu, Brah Ndu may, troch jêh ta may dak ngi nau răm maak, ăn may jêng toyh lơn ma phung băl may.”$b$,true),
('bunong-vn','HEB',1,10,null,$b$Jêh ri: “May, ơ Kôranh Brah, kăl e ri rhăk njêng neh ntu, jêh ri trôk jêng kan bơh ti may.$b$,true),
('bunong-vn','HEB',1,11,null,$b$Khân păng mra rai lôch, ƀiă lah may ăt hôm; khân păng mra mŭnh nâm bu bok ao,$b$,true),
('bunong-vn','HEB',1,12,null,$b$May mra klôt khân păng nâm bu du blah ao mbâl; jêh ri khân păng mra tâm rgâl. Ƀiă lah may ăt hôm, jêh ri năm may mâu mra blau lôch ôh.”$b$,false),
('bunong-vn','HEB',1,13,null,$b$Jêh ri ma mbu phung Tông mpăr ueh Brah Ndu mâp lah jêh nâm pô aơ: “Gŭ hom may pa ma Gâp, kŏ tât Gâp ăn phung rlăng đah may jêng rnơl may chrong jâng.”$b$,true),
('bunong-vn','HEB',1,14,null,$b$Mâu di hĕ, lĕ rngôch khân păng jêng huêng brah, Brah Ndu njuăl hăn pah kan ma phung mra dơn nau tâm rklaih.$b$,true),
('bunong-vn','HEB',2,1,null,$b$Yor nây, ăn he rkêng tôr ueh lơn ma nau he tăng jêh, klach lah he mra roh nau nây.$b$,true),
('bunong-vn','HEB',2,2,null,$b$Yor lah tơ lah nau ngơi phung Tông mpăr ueh Brah Ndu mbơh jêh geh nau ƀư nanê̆, jêh ri tơ lah lĕ nau tih jêh ri lĕ nau mâu tông bâr geh jêh nau nkhôm di.$b$,false),
('bunong-vn','HEB',2,3,null,$b$Mâm ƀư he mra klaih lĕ tơ lah he mâu chrê ma nau tâm rklaih toyh ngăn? Nau nây Kôranh Brah mbơh jêh lor, jêh ri phung tăng jêh mbơh nau nây jêng ngăn.$b$,false),
('bunong-vn','HEB',2,4,null,$b$Brah Ndu nơm lĕ ăn, ngăn nau khân păng mbơh ma nau tâm mbên, kan brah, jêh ri âk ntil nau khlay, jêh ri ma nau ăn bơh Brah Huêng Ueh, pă jêh tĭng nâm Păng ŭch.$b$,true),
('bunong-vn','HEB',2,5,null,$b$Mâu di ma phung Tông mpăr ueh ôh Brah Ndu rnglăp jêh neh ntu mra tât, ma nau nây he gŭ ngơi aƀaơ aơ.$b$,true),
('bunong-vn','HEB',2,6,null,$b$Pô ri bu mbơh jêh nau aơ tâm du ntŭk: “Mâm bunuyh jêng, kŏ may ŭch kah gĭt ma păng, mâu lah kon bunuyh, kŏ may mât mơh păng$b$,false),
('bunong-vn','HEB',2,7,null,$b$May tông jêh Păng knŏng ƀât lât tâm dâng phung Tông mpăr ueh Brah Ndu. May ndô jêh Păng ma đon hađăch nau chrêk rmah jêh ri nau yơk. May ăn Păng chiă uănh kan ti may ƀư.$b$,false),
('bunong-vn','HEB',2,8,null,$b$May dơm jêh lĕ rngôch mpa tâm dâng jâng Păng.” Pô ri jêh Păng nglăp lĕ rngôch mpô mpa ma bunuyh, Brah Ndu mâu lơi du ntil ndơ ôh ê lăp Păng. Ƀiă lah aƀaơ aơ he ê saơ ôh lĕ rngôch mpa lăp jêh Păng.$b$,true),
('bunong-vn','HEB',2,9,null,$b$Ƀiă lah he saơ Brah Yêsu nây, Nơm tông bâr ntrŭnh ƀât lât tâm dâng phung Tông mpăr ueh Brah Ndu, ndô jêh đon hađăch nau chrêk rmah jêh ri nau yơk yor nau khĭt, Păng dơn jêh, gay ma nau yô̆ bơh Brah Ndu, Păng dơi dơn nau khĭt ma lĕ rngôch.$b$,false),
('bunong-vn','HEB',2,10,null,$b$Yor lah di jêh nơm njêng lĕ rngôch mpa jêh ri lĕ rngôch ndơ jêng ndơ Păng, tâm nau Păng ŭch njŭn leo Kon ma nau chrêk rmah, mra ăn Kôranh nau tâm rklaih khân păng jêng rah vah ma nau rêh ni Păng dơn.$b$,true),
('bunong-vn','HEB',2,11,null,$b$Yor lah nơm ƀư kloh ueh jêh ri phung jêng kloh ueh jêh luh tă bơh du huê. Yor nây păng mâu prêng ôh kuăl ma phung nây ôh.$b$,true),
('bunong-vn','HEB',2,12,null,$b$Tơ lah, Păng lah: “Gâp mra mbơh amoh may ma phung oh gâp. Gâp mra tâm rnê ma may ta nklang nau tâm rƀŭn.”$b$,false),
('bunong-vn','HEB',2,13,null,$b$Păng lah đŏng: “Gâp mra rnơm ma Păng”, Păng lah đŏng: “Ta aơ gâp, jêh ri phung kon Brah Ndu ăn jêh ma gâp.”$b$,true),
('bunong-vn','HEB',2,14,null,$b$Pô ri, yor lah phung kon geh mham, jêh ri nglay săk nđâp ma Păng nơm lĕ jêng pô nây gay ma, đah nau khĭt Păng dơi ƀư rai, nơm geh nau brah nau khĭt, nâm bu ntĭt brah mhĭk,$b$,true),
('bunong-vn','HEB',2,15,null,$b$jêh ri Păng tâm rklaih lĕ rngôch phung jêng dĭk, lĕ nau rêh khân păng yor klach ma khĭt.$b$,false),
('bunong-vn','HEB',2,16,null,$b$Yor lah nanê̆ mâu di ma phung Tông mpăr ueh Brah Ndu păng văch kơl, ƀiă lah ma phung kon sau Y-Abraham.$b$,false),
('bunong-vn','HEB',2,17,null,$b$Pô ri Păng geh nau ăn jêng nâm bu phung jêng oh Păng tâm lĕ rngôch ndơ, gay ma Păng dơi jêng du huê kôranh ƀư brah toyh, blau yô̆ jêh ri răp jăp tâm kan Păng pah ma Brah Ndu, gay tâm chuai lĕ rngôch nau tih bunuyh.$b$,false),
('bunong-vn','HEB',2,18,null,$b$Yor lah Păng nơm dơn jêh nau rêh ni, jêh ri mâp jêh đah nau ndơm, pô ri Păng dơi kơl phung geh nau ndơm.$b$,false),
('bunong-vn','HEB',3,1,null,$b$Hơi phung oh nâu kloh ueh, khân may geh jêh nau kuăl tă bơh trôk, ăn khân may mĭn ma Brah Yêsu, jêng kôranh oh mon jêh ri Kôranh ƀư brah toyh ma nau chroh he mbơh.$b$,true),
('bunong-vn','HEB',3,2,null,$b$Păng gŭ răp jăp jêh đah Nơm săch Păng, nâm bu Y-Môis răp jăp tâm ngih Brah Ndu.$b$,false),
('bunong-vn','HEB',3,3,null,$b$Yor lah Păng khư geh nau chrêk rmah âk lơn ma Y Môis, nâm bu nơm ƀư ngih geh âk lơn nau yơk ma ngih păng ƀư.$b$,false),
('bunong-vn','HEB',3,4,null,$b$Yor lah ăp ngih geh nơm ƀư păng, ƀiă lah Nơm ƀư ăp ntil ndơ jêng Brah Ndu?$b$,false),
('bunong-vn','HEB',3,5,null,$b$Bi Y-Môis gŭ răp jăp tâm ngih Brah Ndu, nâm bu du huê oh mon, ŭch mbơh ma nau bu mra ngơi kăndơ̆ .$b$,true),
('bunong-vn','HEB',3,6,null,$b$Ƀiă lah Krist gŭ răp jăp tâm ngih Brah Ndu nâm bu du huê kon. Jêh ri he jêng ngih ma Păng, tơ lah he gŭ nâp tâm nau rnơm jêh ri tâm rnê tâm nau kâp gân tât dăch lôch. Lơi kơt nau dăng jêh ri nau mâu chroh phung Israel kăl e$b$,false),
('bunong-vn','HEB',3,7,null,$b$Yor nây, nâm bu Brah Huêng Ueh lah: “Nar aơ tơ lah khân may tăng bâr Păng,$b$,false),
('bunong-vn','HEB',3,8,null,$b$Lơi ăn dăng ôh nuih n'hâm khân may, nâm bu nar bu tâm rdâng, nar geh nau rlong uănh tâm ntŭk rdah,$b$,false),
('bunong-vn','HEB',3,9,null,$b$Ta nây phung mbơ̆ khân may rlong uănh Gâp, gay năl Gâp, jêh ri khân păng saơ jêh kan Gâp dôl tâm puăn jât năm.$b$,false),
('bunong-vn','HEB',3,10,null,$b$Pô ri Gâp nuih jêh ma phung rnôk nĕ, jêh ri lah: ‘Khân păng nkhah du mro tâm nuih n'hâm khân păng, jêh ri khân păng mâu gĭt trong Gâp ôh.’$b$,true),
('bunong-vn','HEB',3,11,null,$b$Tĭng nâm nau Gâp sân săk jêh tâm nau Gâp ji nuih, ‘Khân păng mâu mra lăp tâm nau Gâp rlu ôh.’ ”$b$,false),
('bunong-vn','HEB',3,12,null,$b$Hơi phung oh nâu, njrăng hom, lơi ăn du huê tâm phung khân may geh nuih n'hâm mhĭk jêh ri mâu chroh, tât păng cha lơi Brah Ndu rêh.$b$,true),
('bunong-vn','HEB',3,13,null,$b$Ƀiă lah tâm n'hao nuih ndrăng khân may ăp nar dôl bu dơi lah, “Nar aơ,” mâu ŭch ma du huê tâm phung khân may jêng dăng, yor nau ndơm bơh nau tih.$b$,false),
('bunong-vn','HEB',3,14,null,$b$Yor lah he geh du kô̆ ndrel ma Krist tơ lah he gŭ nâp tâm nau rnơm kŏ tât lôch nâm bu kăl e,$b$,false),
('bunong-vn','HEB',3,15,null,$b$dôl geh nau lah pô aơ: “Nar aơ tơ lah may tăng bâr Păng, lơi ăn dăng nuih n'hâm khân may ôh, nâm bu tâm nar bu tâm rdâng.”$b$,false),
('bunong-vn','HEB',3,16,null,$b$Ma mbu nơm, jêh khân păng tăng, ƀư nau tâm rdâng? Mâu di hĕ, lĕ rngôch phung luh bơh n'gor Êjipt Y Môis njŭn leo?$b$,true),
('bunong-vn','HEB',3,17,null,$b$Jêh ri ma mbu phung Brah Ndu ji nuih dôl tâm puăn jât năm? Mâu di hĕ ma phung ƀư tih jêh, jêh ri săk jăn khân păng prah rai tâm ntŭk rdah?$b$,false),
('bunong-vn','HEB',3,18,null,$b$Jêh ri ma phung păng sân săk mâu ăn lăp ôh tâm nau păng rlu? Mâu di hĕ ma phung mâu tông bâr?$b$,false),
('bunong-vn','HEB',3,19,null,$b$Pô ri he saơ khân păng mâu dơi lăp ôh yor nau khân păng mâu chroh.$b$,false),
('bunong-vn','HEB',4,1,null,$b$Pô ri, Dôl geh nau ton, ăn lăp tâm nau Păng rlu, ăn he klach, lơi ăn du huê tâm phung khân may tât nkai.$b$,true),
('bunong-vn','HEB',4,2,null,$b$Yor lah nau mhe mhan ueh aơ tât ma he jêh, tâm ban ma tât ma khân păng lĕ; Ƀiă lah nau ngơi khân păng tăng jêh mâu jêng khlay ma khân păng ôh, yor lah phung gŭ iăt nau nây mâu geh nau chroh ôh.$b$,false),
('bunong-vn','HEB',4,3,null,$b$Ƀiă lah ma he phung chroh jêh, he lăp tâm nau rlu nây, nâm bu păng hŏ lah jêh: “Tĭng nâm nau gâp sân săk jêh tâm nau gâp ji nuih, ‘Khân păng mâu mra lăp tâm nau rlu gâp ôh.’ ” Nđâp tơ lah kan Păng lĕ jêh ntơm bơh rhăk njêng neh ntu.$b$,false),
('bunong-vn','HEB',4,4,null,$b$Yor lah tâm du ntŭk Păng ngơi jêh ma nar pơh pô aơ: “Jêh ri Brah Ndu rlu bơh lĕ kan Păng ƀư jêh pơh nar.”$b$,false),
('bunong-vn','HEB',4,5,null,$b$Jêh ri Păng lah đŏng: “Khân păng mâu mra mâp lăp tâm nau Gâp rlu ôh.”$b$,true),
('bunong-vn','HEB',4,6,null,$b$Yor lah ăt prăp ma ƀa ƀă dơi lăp rlu; jêh ri phung geh jêh nau mhe mhan ueh bơh lor, mâu lăp ôh yor nau khân păng mâu tông bâr,$b$,true),
('bunong-vn','HEB',4,7,null,$b$Brah Ndu tâm nal du nar đŏng, “Nar aơ,” lah Păng ngơi ma bâr mbung Y Đavit jŏ năm kăndơ̆ , nâm bu nau nchih lor jêh: “Nar aơ, tơ lah khân may tăng bâr Păng, lơi khân may ƀư dăng nuih n'hâm ôh.”$b$,false),
('bunong-vn','HEB',4,8,null,$b$Yor lah, tơ lah Y-Yôsuê ăn jêh ma khân păng nau rlu, Brah Ndu mâu hôm mra ngơi ôh ma nar êng.$b$,true),
('bunong-vn','HEB',4,9,null,$b$Pô ri geh nau rlu nar Saƀat prăp ma phung mpôl băl Brah Ndu.$b$,false),
('bunong-vn','HEB',4,10,null,$b$Yor lah mbu nơm lăp tâm nau Brah Ndu rlu, păng rlu bơh kan păng lĕ, nâm bu Brah Ndu rlu jêh bơh kan Păng.$b$,false),
('bunong-vn','HEB',4,11,null,$b$Pô ri ăn he nsrôih nsram lăp tâm nau rlu aơ, gay lơi ăn geh du huê tŭp tâm nau mâu tông bâr tâm ban lĕ.$b$,true),
('bunong-vn','HEB',4,12,null,$b$Yor lah Nau Brah Ndu Ngơi rêh jêh ri brah, hơr lơn ma đao gưm bar măt, lăp băm, kŏ tâm pă nuih n'hâm nau mĭn đah huêng, ntŭk nting tâm ntrŭp đah glo. Păng phat dôih nau ŭch jêh ri nau mĭn tâm nuih n'hâm.$b$,false),
('bunong-vn','HEB',4,13,null,$b$Jêh ri ta năp Păng mâu geh du ntil ndơ rhăk njêng jêh dơi gŭ ndâp, ƀiă lah lĕ rngôch ndơ pơk, jêh ri tâm mpơl jêh ta năp măt Nơm he mra mbơh kan he ƀư.$b$,false),
('bunong-vn','HEB',4,14,null,$b$Yor lah he geh du huê kôranh ƀư brah toyh, Brah Yêsu, Kon Brah Ndu, Nơm rgăn jêh trôk, pô ri ăn he gŭ nâp tâm nau chroh he nkoch mbơh.$b$,true),
('bunong-vn','HEB',4,15,null,$b$Yor lah he mâu geh du huê kôranh ƀư brah toyh mâu dơi yô̆ ma nau rdja he, ƀiă lah Păng Nơm geh jêh nau ndơm nâm bu he tâm lĕ rngôch mpa, ƀiă lah Păng mâu ƀư tih ôh.$b$,false),
('bunong-vn','HEB',4,16,null,$b$Pô ri ăn he hăn dăch ta sưng hađăch nau yô̆ ma nau rnơm, gay ma dơi sŏk dơn nau ueh jêh ri saơ nau yô̆ kơl he dôl he geh nau pưt.$b$,false),
('bunong-vn','HEB',5,1,null,$b$Yor lah ăp nơm kôranh ƀư brah toyh săch jêh bơh phung bunuyh geh kan ma bunuyh ta năp Brah Ndu, gay nhhơ ndơ bu nhhơr jêh ri ndơ bu ƀư brah yor nau tih.$b$,true),
('bunong-vn','HEB',5,2,null,$b$Păng blau yô̆ ma phung rluk jêh ri ma phung nkhah du yor lah Păng Nơm jêng rdja tâm ban lĕ.$b$,false),
('bunong-vn','HEB',5,3,null,$b$Yor nau rdja nây Păng mra nhhơr ndơ ƀư brah ma nau tih Păng nơm nâm bu yor nau tih ƀon lan lĕ.$b$,false),
('bunong-vn','HEB',5,4,null,$b$Jêh ri bu mâu săch ma păng nơm kan khlay nây ôh, tơ lah Brah Ndu mâu kuăl Păng, nâm bu Y-Arôn jêng jêh.$b$,true),
('bunong-vn','HEB',5,5,null,$b$Pô nây lĕ Brah Krist mâu n'hao Păng nơm ôh, gay jêng kôranh ƀư brah toyh, ƀiă lah Păng geh nau săch bơh Nơm lah ma Păng pô aơ: “May jêng Kon bu klâu gâp, gâp deh jêh ma may nar aơ.”$b$,false),
('bunong-vn','HEB',5,6,null,$b$Nâm bu Păng hŏ lah tâm ntŭk êng, “May jêng du huê Kôranh ƀư brah n'ho ro tĭng nâm Mêlkisadek.”$b$,true),
('bunong-vn','HEB',5,7,null,$b$Dôl Păng gŭ rêh tâm nglay săk, Brah Yêsu mbơh sơm jêh ri vơh vơl ma nau nter ktang jêh ri ma dak măt, ma nơm dơi tâm nklaih Păng bơh nau khĭt, jêh ri Păng geh nau bu dơn, yor nau Păng blau yơk klach ma Brah Ndu.$b$,true),
('bunong-vn','HEB',5,8,null,$b$Nđâp tơ lah Păng jêng Kon Brah Ndu, păng nti jêh nau tông bâr, ma nau rêh ni Păng dơn jêh;$b$,false),
('bunong-vn','HEB',5,9,null,$b$jêh ri jêh Păng jêng rah vah, Păng jêng bôk nau tâm rklaih n'ho ro, ma mbu nơm tông bâr ma Păng.$b$,false),
('bunong-vn','HEB',5,10,null,$b$Brah Ndu mbơh jêh ma Păng jêng Kôranh ƀư brah toyh tĭng nâm Mêlkisadek.$b$,false),
('bunong-vn','HEB',5,11,null,$b$Hên geh âk nau ŭch lah tâm nau nây, jêh ri geh nau jêr rblang, yor lah khân may jêng phung băt gĭt rbăng.$b$,true),
('bunong-vn','HEB',5,12,null,$b$Yor lah bơh jŏ jêh khân may dơi jêng phung kôranh nơm nti, ƀiă lah ăt khân may ŭch bu nti ma khân may nau nơih tâm Nau Brah Ndu Ngơi. Khân may ŭch ma dak toh, mâu di ma ndơ sông sa dăng ôh.$b$,false),
('bunong-vn','HEB',5,13,null,$b$Yor lah mbu nơm ăt hôm rŏng ma dak toh mâu blau dŏng nau ngơi ma nau sŏng ôh. Păng ăt hôm jêng kon se.$b$,false),
('bunong-vn','HEB',5,14,null,$b$Ƀiă lah ndơ sông sa dăng prăp ma phung bu ranh jêh ri ma phung blau dŏng nau mĭn khân păng dơi gĭt rbăng nau ueh đah nau mhĭk.$b$,false),
('bunong-vn','HEB',6,1,null,$b$Yor nây ăn he lơi nau nti nơih bơh Brah Krist, ăn he nsrôih lơn ma nau rah vah, lơi hôm dơm ntur nau tâm rmal ma kan khĭt, jêh ri nau chroh ma Brah Ndu,$b$,true),
('bunong-vn','HEB',6,2,null,$b$ma nau nti ma nau ƀư ƀaptem, nau pah ti, nau dâk rêh bơh phung khĭt, jêh ri nau phat dôih n'ho ro.$b$,false),
('bunong-vn','HEB',6,3,null,$b$Nau nây yơh he mra ƀư, tơ lah Brah Ndu ăn.$b$,false),
('bunong-vn','HEB',6,4,null,$b$Yor lah mâu hôm dơi ôh njŭn nau tâm rmal ma nau tih phung geh jêh nau ang du tơ̆ , mâp chiăm jêh bơh Brah Ndu he, mâp sŏk dơn jêh Brah Huêng Ueh,$b$,true),
('bunong-vn','HEB',6,5,null,$b$mâp chiăm jêh nau ngơi ueh bơh Brah Ndu, jêh ri nau brah ma du nar kăndơ̆ ,$b$,false),
('bunong-vn','HEB',6,6,null,$b$tơ lah khân păng tŭp jêh, mâu hôm dơi plơ̆ tay ma nau rmal ma khân păng nơm, yor lah khân păng pâng tay kon Brah Ndu ta si tâm rkăng, jêh ri ƀư bêk prêng Păng.$b$,false),
('bunong-vn','HEB',6,7,null,$b$Yor lah neh bĕ jêh ma dak mih, tŭp ta păng ƀa ƀơ jêh ri ăn hon gơ̆ khlay ma phung tăm păng, sŏk dơn du ntil nau ueh uĭn bơh Brah Ndu.$b$,false),
('bunong-vn','HEB',6,8,null,$b$Ƀiă lah tơ lah păng ăn hon lok jêh ri gơ̆ mhĭk păng mâu khlay ôh, jêh ri bơi ma bu ŭch rtăp rak; nau dăch lôch păng jêng ŭnh mra sa.$b$,false),
('bunong-vn','HEB',6,9,null,$b$Hơi phung gâp rŏng ơi, nđâp tơ lah hên ngơi pô nây, ma nau di ma khân may, hên kâp nau ueh lơn jêng ndơ ma nau tâm rklaih.$b$,true),
('bunong-vn','HEB',6,10,null,$b$Yor lah Brah Ndu mâu jêng kue ôh, gay ƀư chuêl kan khân may jêh ri nau rŏng khân may tâm mpơl jêh ma amoh Păng, tâm nau khân may kơl jêh phung kloh ueh, jêh ri ăt kơl ƀa ƀơ.$b$,false),
('bunong-vn','HEB',6,11,null,$b$Jêh ri hên ŭch ngăn ma ăp nơm khân may tâm mpơl nau nsrôih nsram tâm ban, gay prăp nau kâp gân rah vah tât nglĕ dŭt.$b$,false),
('bunong-vn','HEB',6,12,null,$b$Pô ri, lơi khân may jêng ƀlao ôh, ƀiă lah ăn khân may kơt phung dơn nau ton ma nau chroh jêh ri ma nau srôih.$b$,false),
('bunong-vn','HEB',6,13,null,$b$Tơ lah Brah Ndu ton ma Y-Abraham, Păng mâu dơi sân săk ôh ma du huê toyh lơn ma Păng, pô ri Păng sân săk đah Păng nơm,$b$,true),
('bunong-vn','HEB',6,14,null,$b$jêh ri Păng lah: “Nanê̆, gâp mra ăn nau ueh uĭn ma may, jêh ri gâp mra ăn bĭk phung kon sau may.”$b$,false),
('bunong-vn','HEB',6,15,null,$b$Pô ri Y-Abraham, jêh păng srôih, saơ nau Brah Ndu ton tât.$b$,false),
('bunong-vn','HEB',6,16,null,$b$Ƀiă lah phung bunuyh sân săk đah nơm toyh lơn ma khân păng nơm, jêh ri nau sân săk jêng nau ton gay ma ƀư lôch nau khân păng tâm rlăch.$b$,true),
('bunong-vn','HEB',6,17,null,$b$Yor nây Brah Ndu ŭch tâm mpơl ma nau nanê̆ lơn, ma phung dơn nau Păng ton ma păng, mâu geh rgâl ôh nau Păng ŭch ƀư, pô ri Păng sân săk,$b$,false),
('bunong-vn','HEB',6,18,null,$b$gay ma bar nau mâu blau rgâl, jêh ri tâm nau nây Brah Ndu mâu dơi mƀruh ôh, ma phung he du krap jêh dơi geh nau tâm n'hao nuih, nau brah, gay djôt nau kâp gân Brah Ndu ton jêh ma he.$b$,false),
('bunong-vn','HEB',6,19,null,$b$Nau kâp gân nây he geh nâm bu loih jâk, nkân huêng he, nanê̆ jêh ri nâp, lăp gao đah ri bok.$b$,false),
('bunong-vn','HEB',6,20,null,$b$Ta nây Brah Yêsu lăp jêh tâm tang ma he nâm bu nơm nkra trong, jêh ri Păng jêng kôranh ƀư brah toyh n'ho ro, tĭng nâm Mêlkisadek.$b$,false),
('bunong-vn','HEB',7,1,null,$b$Yor lah Y-Mêlkisadek jêng, hađăch ƀon Salem, kôranh ƀư brah ma Brah Ndu, Nơm Klơ Lơn, tâm mâp đah Y-Abraham, tơ lah păng sĭt tă bơh nau dơi tâm lơh đah phung hađăch, jêh ri păng ăn nau ueh lăng.$b$,true),
('bunong-vn','HEB',7,2,null,$b$Y-Abraham ăn ma păng du kô̆ tâm jât bơh lĕ rngôch ndơ. Tĭng nâm nau rblang ma amoh păng, păng jêng lor lơn: “Hađăch nau sŏng srăng,” jêh ri păng jêng hađăch ma ƀon Salem, nâm bu ntĭt, “Hađăch nau đăp mpăn.”$b$,false),
('bunong-vn','HEB',7,3,null,$b$Păng mâu geh mbơ̆ , mâu geh mê̆, mâu lĕ geh phung u che. Păng mâu geh tơm, mâu lĕ geh nau blau lôch, ƀiă lah păng jêng nâm bu kon Brah Ndu, du huê kôranh ƀư brah gŭ n'ho ro.$b$,false),
('bunong-vn','HEB',7,4,null,$b$Uănh hom nau păng jêng toyh! Y-Abraham, bu ranh, nhhơr ma păng du kô̆ tâm jât ndơ păng sŏk pit tă bơh phung rlăng.$b$,true),
('bunong-vn','HEB',7,5,null,$b$Jêh ri phung kon bu klâu Y-Lêvi jêng phung kôranh ƀư brah tĭng nau vay, dơi sŏk du kô̆ tâm jât bơh phung ƀon lan, nâm bu ntĭt bơh phung oh nâu khân păng, nđâp tơ lah lĕ rngôch lah tă bơh Y Abraham da dê.$b$,false),
('bunong-vn','HEB',7,6,null,$b$Ƀiă lah Y-Mêlkisadek mâu luh bơh ndŭl mpôl Y-Abraham ôh, sŏk dơn du kô̆ tâm jât bơh Y-Abraham, jêh ri păng ăn nau ueh uĭn ma nơm geh jêh nau Brah Ndu ton.$b$,false),
('bunong-vn','HEB',7,7,null,$b$Pô ri mâu hôm geh nau tâm rlăch ôh. Nơm toyh lơn ăn nau ueh uĭn ma nơm jê̆.$b$,false),
('bunong-vn','HEB',7,8,null,$b$Ta aơ bunuyh blau khĭt dơn sŏk du kô̆ tâm jât; ƀiă lah ta nây nơm dơn, bu mbơh păng hôm rêh.$b$,true),
('bunong-vn','HEB',7,9,null,$b$Bu dơi lah ma Y-Lêvi, nơm sŏk dơn du kô̆ tâm jât, nhhơr jêh du kô̆ tâm jât tâm Y-Abraham,$b$,false),
('bunong-vn','HEB',7,10,null,$b$Yor lah păng ăt hôm gŭ tâm nuih n'hâm mbơ̆ păng tơ lah Y-Mêlkisadek hăn tâm mâp đah Y-Abraham.$b$,false),
('bunong-vn','HEB',7,11,null,$b$Tơ lah dơi geh nau rah vah ma nau ƀư brah phung Lêvi yor lah bơh nau nây phung ƀon lan sŏk dơn jêh nau vay moh khlay hôm geh du huê kôranh ƀư brah êng tĭng nâm Mêlkisadek, mâu di tĭng nâm Y-Arôn ôh?$b$,true),
('bunong-vn','HEB',7,12,null,$b$Yor lah, tơ lah geh nau tâm rgâl tâm nau ƀư brah, pô ri khlay lĕ geh nau tâm rgâl tâm nau vay.$b$,false),
('bunong-vn','HEB',7,13,null,$b$Nanê̆ ma mbu nơm bu nkoch bri nau nây jêng bơh mpôl băl êng, bơh ndŭl mpôl nây mâu geh du huê ôh pah kan ma nơng ƀư brah.$b$,false),
('bunong-vn','HEB',7,14,null,$b$Yor lah, nanê̆ Kôranh Brah he luh tă bơh mpôl băl Yuđa, mpôl băl nây, Y-Môis mâu mâp ngơi ma kan nau ƀư brah ôh.$b$,false),
('bunong-vn','HEB',7,15,null,$b$Nau nây jêng rah vah lơn, tơ lah geh kôranh ƀư brah êng tĭng nâm Mêlkisadek,$b$,false),
('bunong-vn','HEB',7,16,null,$b$Jêng kôranh ƀư brah mâu di tĭng nâm nau vay bơh nglay săk ôh, ƀiă lah tĭng nâm nau brah bơh nau rêh mâu blau rai.$b$,false),
('bunong-vn','HEB',7,17,null,$b$Yor lah bu mbơh jêh ma păng pô aơ: “May jêng kôranh ƀư brah n'ho ro, tĭng nâm Mêlkisadek.”$b$,false),
('bunong-vn','HEB',7,18,null,$b$Pô ri, nau lôch jêh ma nau ntăm lor kôranh păng jêng rdja jêh ri mâu khlay ôh.$b$,true),
('bunong-vn','HEB',7,19,null,$b$(Yor lah nau vay mâu dơi njŭn leo tâm nau rah vah ôh). Jêh ri geh nau vay kâp gân ueh lơn, ma nau nây he dơi hăn dăch Brah Ndu.$b$,false),
('bunong-vn','HEB',7,20,null,$b$Jêh ri nau nây mâu tât ôh tơ lah mâu geh nau sân săk.$b$,true),
('bunong-vn','HEB',7,21,null,$b$Yor lah tơ lah phung Lêvi jêng kôranh ƀư brah mâu di ma nau sân săk ôh, ƀiă lah Brah Yêsu jêng kôranh ƀư brah ma nau sân săk, yor Nơm lah jêh ma Păng nâm pô aơ: “Kôranh Brah sân săk jêh, jêh ri Păng mâu mra nduyh tôr ôh. May jêng kôranh ƀư brah n'ho ro tĭng nâm Y-Mêlkisadek.”$b$,false),
('bunong-vn','HEB',7,22,null,$b$Nau nây njêng Brah Yêsu nau ton ma nau tâm rnglăp ueh lơn.$b$,true),
('bunong-vn','HEB',7,23,null,$b$Jêh ri phung kôranh ƀư brah jêng âk yor nau khĭt, buay khân păng gŭ pah kan mro;$b$,true),
('bunong-vn','HEB',7,24,null,$b$ƀiă lah Păng jêng kôranh ƀư brah bu mâu hôm rgâl ôh, yor lah Păng gŭ rêh n'ho ro.$b$,false),
('bunong-vn','HEB',7,25,null,$b$Yor nây lĕ Păng dơi tâm rklaih ma nau rah vah phung hăn dăch Brah Ndu tâm Păng, yor lah Păng gŭ rêh ƀa ƀơ, gay kơl mbơh sơm an ma khân păng.$b$,false),
('bunong-vn','HEB',7,26,null,$b$Yor lah di jêh ma he geh du huê kôranh ƀư brah toyh nâm bu Păng, kloh ueh, mâu mâp tih, mâu geh nau ƀơ̆ , tâm nkhah jêh đah phung tih, jêh ri gŭ klơ lơn ma trôk.$b$,true),
('bunong-vn','HEB',7,27,null,$b$Păng mâu ŭch ôh tâm ban ma phung ƀư brah toyh nây, ăp nar nhhơr nau ƀư brah lor lơn ma nau tih khân păng nơm, jêh ri ma nau tih phung ƀon lan. Păng ƀư nau nây knŏng du tơ̆ dŭm nây tơ lah Păng nhhơr Păng nơm.$b$,true),
('bunong-vn','HEB',7,28,null,$b$Nanê̆ nau vay njêng phung kôranh ƀư brah toyh bơh phung bunuyh rdja, ƀiă lah nau ngơi sân săk geh jêh pa kơi ma nau vay njêng kon, Nơm jêng rah vah jêh n'ho ro.$b$,false),
('bunong-vn','HEB',8,1,null,$b$Tâm nau hên mhe lah jêh, nau khlay jêng nau he geh du huê Nơm ƀư brah toyh pô nây. Păng gŭ jêh mpeh pa ma sưng hađăch nau chrêk rmah tâm trôk.$b$,true),
('bunong-vn','HEB',8,2,null,$b$Păng jêng oh mon ktang tâm ntŭk kloh ueh jêh ri tâm ngih bok ngăn, ngih Kôranh Brah Nơm rdâk, mâu di bunuyh ôh.$b$,false),
('bunong-vn','HEB',8,3,null,$b$Lĕ rngôch kôranh ƀư brah toyh geh kan nhhơr ndơ bu ăn, jêh ri ndơ bu ƀư brah; yor nây khlay đŏng ma kôranh ƀư brah aơ geh ndơ nhhơr.$b$,false),
('bunong-vn','HEB',8,4,null,$b$Tơ lah Păng gŭ ta neh ntu aơ Păng mâu jêng kôranh ƀư brah ôh, yor lah geh jêh kôranh ƀư brah nhhơr ndơ ăn tĭng nâm nau vay.$b$,true),
('bunong-vn','HEB',8,5,null,$b$Khân păng jêng nâm bu rup jêh ri gui ma ntŭk kloh ueh tâm trôk, yor lah, tơ lah Y-Môis ntơm ƀư ngih bok, păng geh nau mbơh bơh Brah Ndu pô aơ: “Njrăng hom, ăn may ƀư lĕ tĭng nâm rup gâp nhhơ jêh ma may ta yôk.”$b$,false),
('bunong-vn','HEB',8,6,null,$b$Ƀiă lah aƀaơ Brah Krist geh jêh kan khlay lơn tâm nau Păng jêng Nơm tâm nklang ma nau tâm rnglăp ueh lơn, rdâk jêh ta klơ nau ton ueh lơn.$b$,true),
('bunong-vn','HEB',8,7,null,$b$Yor lah tơ lah nau tâm rnglăp lor mâu geh nau tih ôh, mâu hôm geh khlay ôh geh nau tâm rnglăp tal bar.$b$,false),
('bunong-vn','HEB',8,8,null,$b$Yor lah ma nau ngơi nduyh yơh Kôranh Brah lah ma phung Israel! “Aơ nar mra tât, Kôranh Brah lah, Gâp mra ƀư nau tâm rnglăp mhe đah ngih Israel jêh ri đah ngih Yuđa.$b$,false),
('bunong-vn','HEB',8,9,null,$b$Mâu di nâm bu nau tâm rnglăp Gâp ƀư jêh ma phung che khân păng ôh, nar Gâp têk khân păng ta ti gay ăn khân păng luh bơh n'gor Êjipt. Yor lah khân păng mâu srôih tâm nau Gâp rnglăp. Jêh ri Gâp tâm ban lĕ,” mâu hôm chrê ma khân păng ôh Kôranh Brah lah:$b$,true),
('bunong-vn','HEB',8,10,null,$b$“Aơ, nau tâm rnglăp Gâp mra ƀư ma ngih Israel. Jêh nar nây Kôranh Brah lah, Gâp mra dơm nau vay Gâp tâm nau mĭn khân păng. Jêh ri Gâp mra nchih tâm nuih n'hâm khân păng. Gâp mra jêng Brah Ndu khân păng, jêh ri khân păng mra jêng phung ƀon lan Gâp.$b$,false),
('bunong-vn','HEB',8,11,null,$b$Mâu mra hôm geh ôh du huê sâm nti phung băl păng mâu lah oh păng ma nau lah pô aơ: ‘Ăn may gĭt năl Kôranh Brah.’ Yor lah lĕ rngôch mra gĭt năl Gâp, ntơm bơh phung jê̆ tât phung toyh tâm khân păng.$b$,true),
('bunong-vn','HEB',8,12,null,$b$Yor lah Gâp mra yô̆ an nau tih khân păng. Jêh ri Gâp mâu mra kah gĭt ôh ma nau kue khân păng.”$b$,true),
('bunong-vn','HEB',8,13,null,$b$Dôl ngơi ma nau tâm rnglăp mhe, păng mbơh ma nau lor jêng ơm. Jêh ri moh ndơ jêng ơm jêh, ranh jêh mra rai yot yơh.$b$,true),
('bunong-vn','HEB',9,1,null,$b$Nau tâm rnglăp lor, geh lĕ nau vay ma nau yơk jêh ri ntŭk kloh ta neh ntu.$b$,true),
('bunong-vn','HEB',9,2,null,$b$Geh du mlâm ngih bok ƀư jêh. Tâm ntŭk lor, bu rnha Ntŭk Kloh, ta nây geh jâng jrêng, du mlâm sưng jêh ri kapŭng nau ton.$b$,false),
('bunong-vn','HEB',9,3,null,$b$Pa kơi bok nthăng tal bar, geh ntŭk bu rnha ntŭk Kloh Ngăn.$b$,false),
('bunong-vn','HEB',9,4,null,$b$Ta nây geh du mlâm nơng mah gay su ndơ ƀâu kah jêh ri hip nau tâm rnglăp, ndop mah da dê. Tâm hip nây geh du mlâm yăng mah bu dơ kapŭng mana, geh mâng Y-Arôn luh kao, jêh ri geh bar mpơng lŭ bu nchih nau tâm rnglăp.$b$,false),
('bunong-vn','HEB',9,5,null,$b$Ta klơ hip nây geh rup bar hê Tông mpăr ueh, nau chrêk rmah nkŭm ma gui n'hâm khân păng ntŭk nau yô̆ gŭ. Ma nau nây hên mâu hôm dơi ngơi ăp aƀaơ aơ.$b$,false),
('bunong-vn','HEB',9,6,null,$b$Jêh nkra lĕ nau nây, phung kôranh ƀư brah lăp mro tâm ntŭk tal lor, ƀư kan khân păng vay ƀư;$b$,true),
('bunong-vn','HEB',9,7,null,$b$ƀiă lah tâm jrô tal bar, knŏng kôranh ƀư brah toyh lăp du tơ̆ du năm, jêh ri mâu dơi ôh tơ lah păng mâu leo mham, gay nhhơr yor păng nơm, jêh ri ma nau tih phung ƀon lan.$b$,false),
('bunong-vn','HEB',9,8,null,$b$Ma nau nây Brah Huêng Ueh tâm mpơl ma trong hăn ta ntŭk kloh ueh ngăn, ê pơk ôh tơ lah ngih bok ơm hôm e.$b$,false),
('bunong-vn','HEB',9,9,null,$b$(Nau nây jêng nau tâm ntĭt ma rnôk aƀaơ). Tĭng nâm nau nkra nây mâu dơi rah vah ôh, nuih n'hâm sŏng nơm nhhơr ndơ ăn, jêh ri ndơ ƀư brah,$b$,false),
('bunong-vn','HEB',9,10,null,$b$ƀiă lah jêng knŏng (ma ndơ sông sa, ndơ nhêt, jêh ri lĕ ntil nau rao) nau vay tĭng nâm nglay săk ntăm jêh, kŏ tât rnôk nau tâm rgâl.$b$,false),
('bunong-vn','HEB',9,11,null,$b$Ƀiă lah Brah Krist tât jêh jêng nâm bu du huê kôranh ƀư brah toyh, ma nau ueh mra tât. Păng rgăn jêh ngih bok toyh lơn, jêh ri rah vah lơn, mâu di ti bunuyh ƀư ôh, nâm bu ntĭt, mâu jêng ndơ rhăk njêng ta aơ ôh.$b$,true),
('bunong-vn','HEB',9,12,null,$b$Jêh ri Păng lăp jêh knŏng du tơ̆ dŭm nây tâm ntŭk kloh, mâu di ma mham be nkuăng jêh ri kon ndrôk ôh, Ƀiă lah ma mham Păng Nơm, Păng sŏk dơn ma he jêh, nau tâm chuai n'ho ro.$b$,false),
('bunong-vn','HEB',9,13,null,$b$Yor lah tơ lah mham ndrôk nkuăng jêh ri be nkuăng, ndrôk me nkhŭt ta klơ phung ƀơ̆ , dơi prăp an ma nau ƀư kloh nglay săk,$b$,false),
('bunong-vn','HEB',9,14,null,$b$rlau lơn ma nây mham Brah Krist, Nơm nhhơr Păng nơm ma Brah Ndu, mâu geh nau ƀơ̆ , ma Brah Huêng Ueh n'ho ro, dơi ƀư kloh nuih n'hâm sŏng khân may ma kan khĭt, gay ma khân may pah kan ma Brah Ndu rêh.$b$,false),
('bunong-vn','HEB',9,15,null,$b$Pô ri Păng jêng Nơm tâm nklang ma nau tâm rnglăp mhe, gay ma phung geh jêh nau kuăl dơi sŏk dơn nau ndơn drăp n'ho ro, ton jêh ma khân păng, yor lah nau khĭt tât jêh dơi tâm chuai khân păng bơh nau tih tâm dâng nau tâm rnglăp ơm.$b$,true),
('bunong-vn','HEB',9,16,null,$b$Yor lah ta ntŭk geh nau tâm rnglăp, khlay ma bu ăn gĭt nau khĭt tât ngăn ma Nơm ƀư nau tâm rnglăp nây.$b$,false),
('bunong-vn','HEB',9,17,null,$b$Nau tâm rnglăp jêng ngăn tơ lah tât nau khĭt, yor lah Păng mâu geh nau ktang ôh tơ lah Păng ƀư nau tâm rnglăp ăt hôm rêh.$b$,false),
('bunong-vn','HEB',9,18,null,$b$Pô ri, nđâp ma nau tâm rnglăp lor, mâu jêng khlay ôh tơ lah mâu geh mham nkhŭt.$b$,false),
('bunong-vn','HEB',9,19,null,$b$Jêh Y-Môis mbơh lĕ nau ntăm tâm nau vay, păng sŏk mham kon ndrôk jêh ri be nkuăng ndrel ma dak, jêh ri rse brai chăng, jêh ri n'ha hisôp, păng mbrih mham ta ndrom sămƀŭt jêh ri ta lĕ rngôch ƀon lan, dôl lah:$b$,false),
('bunong-vn','HEB',9,20,null,$b$“Aơ jêng mham nau tâm rnglăp Brah Ndu ntăm jêh ma khân may.”$b$,false),
('bunong-vn','HEB',9,21,null,$b$Păng mbrih mham ta ngih bok tâm ban lĕ, jêh ri ta lĕ ndơ bu dŏng ma nau ƀư brah.$b$,false),
('bunong-vn','HEB',9,22,null,$b$Tĭng nâm nau vay, bơi ma lĕ ndơ ƀư kloh jêh ma mham, jêh ri tơ lah mâu geh mham nkhŭt, mâu geh nau yô̆ an ôh.$b$,false),
('bunong-vn','HEB',9,23,null,$b$Pô ri khlay yơh ma rup mpa gŭ tâm trôk mra ƀư kloh tĭng nâm nau vay nây, ƀiă lah mpa tâm trôk, ngăn ma nau ƀư brah ueh lơn ma nây.$b$,true),
('bunong-vn','HEB',9,24,null,$b$Yor lah Brah Krist mâu lăp ôh tâm ntŭk kloh ti bunuyh ƀư, jêng rup ma nau ngăn, ƀiă lah Păng lăp jêh tâm trôk gay ma mpơl Păng nơm tâm tang he ta năp Brah Ndu.$b$,false),
('bunong-vn','HEB',9,25,null,$b$Păng lăp jêh, mâu lĕ ŭch nhhơr Păng nơm âk tơ̆ , nâm bu kôranh ƀư brah toyh lăp ăp năm tâm ntŭk kloh ngăn ma mham mpa êng;$b$,false),
('bunong-vn','HEB',9,26,null,$b$tơ lah pô nây di jêh păng mra dơn nau rêh ni âk lơn bơh ntơm rhăk njêng neh ntu. Ƀiă lah aƀaơ nglĕ dŭt rnôk Păng tâm mpơl jêh knŏng du tơ̆ gay ƀư rai nau tih ma nau ƀư brah Păng nơm.$b$,false),
('bunong-vn','HEB',9,27,null,$b$Jêh ri nâm bu hŏ nal jêh kon bunuyh mra khĭt du tơ̆ , jêh nây dơn nau phat dôih,$b$,false),
('bunong-vn','HEB',9,28,null,$b$tâm ban lĕ Brah Krist nhhơr jêh Păng nơm knŏng du tơ̆ , gay tuy nau tih âk bunuyh, mra tâm mpơl tal bar mâu geh nau tih ôh, gay ma tâm rklaih phung gŭ kâp Păng.$b$,false),
('bunong-vn','HEB',10,1,null,$b$Yor lah nau vay geh knŏng n'hâm gui ma nau ueh mra tât, jêh ri mâu geh tâm mpơl nau ngăn ôh, ma ndơ ƀư brah tâm ban bu nhhơr ƀa ƀơ ăp năm mâu dơi ôh njŭn leo ma nau rah vah phung ŭch hăn dăch.$b$,true),
('bunong-vn','HEB',10,2,null,$b$Tơ lah mâu di pô nây, mâm ƀư bu mâu rlu nhhơr ndơ ƀư brah nây? Tơ lah phung ƀư brah ƀư kloh lơi du tơ̆ , khân păng mâu hôm kah gĭt ma nau tih khân păng ôh.$b$,false),
('bunong-vn','HEB',10,3,null,$b$Ƀiă lah nau ƀư brah nây ăn bu kah gĭt ăp năm ma nau tih.$b$,false),
('bunong-vn','HEB',10,4,null,$b$Yor lah mâu dơi ôh mham ndrôk nkuăng jêh ri be nkuăng dơi sŏk lơi nau tih.$b$,false),
('bunong-vn','HEB',10,5,null,$b$Yor nây tơ lah Brah Krist lăp tâm neh ntu, Păng lah pô aơ: “May mâu ŭch ôh ndơ ƀư brah mâu lah ndơ nhhơr. Ƀiă lah may njêng du mlâm săk jăn ma Gâp.$b$,true),
('bunong-vn','HEB',10,6,null,$b$May mâu maak ôh ma ndơ nhhơr gŭch mâu lah mpa ƀư brah ma nau tih.$b$,true),
('bunong-vn','HEB',10,7,null,$b$Pô ri gâp lah: ‘Ơ Brah Ndu, aơ gâp văch ŭch ƀư nau may ŭch, tâm ndrom sămƀŭt bu klôn geh nau mbơh jêh ma gâp.’ ”$b$,true),
('bunong-vn','HEB',10,8,null,$b$Tơ lah păng lah jêh lor: “May mâu ŭch jêh ri mâu maak ôh ma mpa ƀư brah, mpa nhhơr, mpa nhhơr gŭch, mâu lah mpa ƀư brah ma nau tih” (bu nhhơr tĭng nâm nau vay mpa aơ).$b$,true),
('bunong-vn','HEB',10,9,null,$b$Pô ri Păng lah: “Aơ, gâp văch ƀư nau may ŭch.” Pô ri Păng ƀư rai lơi mpa lor gay ma njêng mpa tal bar.$b$,false),
('bunong-vn','HEB',10,10,null,$b$Yor nau ŭch nây he jêng kloh ueh jêh ma nau nhhơr săk jăn Yêsu Krist du tơ̆ nây dơm rĭng jêh.$b$,false),
('bunong-vn','HEB',10,11,null,$b$Jêh ri ăp kôranh ƀư brah gŭ ăp nar pah kan jêh ri nhhơr ƀa ƀơ mpa ƀư brah tâm ban, nau nây mâu dơi sŏk lơi nau tih ôh.$b$,true),
('bunong-vn','HEB',10,12,null,$b$Ƀiă lah tơ lah Brah Krist nhhơr jêh knŏng du tơ̆ mpa ƀư brah ma nau tih, Păng gŭ jêh mpeh pa ma Brah Ndu,$b$,false),
('bunong-vn','HEB',10,13,null,$b$dôl gŭ kâp phung rlăng đah Păng mra jêng rnơl Păng chrong jâng.$b$,false),
('bunong-vn','HEB',10,14,null,$b$Yor lah knŏng ma du mpa nhhơr Păng njŭn jêh ma nau rah vah ƀa ƀơ phung Păng prăp an jêh.$b$,false),
('bunong-vn','HEB',10,15,null,$b$Jêh ri Brah Huêng Ueh mbơh lĕ ma he; Yor lah jêh păng lah:$b$,true),
('bunong-vn','HEB',10,16,null,$b$“Aơ nau tâm rnglăp gâp mra ƀư ma khân păng, jêh nar nây Kôranh Brah lah: Gâp mra dơm nau vay gâp tâm nuih n'hâm khân păng. Jêh ri Gâp mra nchih nau nây tâm nau mĭn khân păng.”$b$,false),
('bunong-vn','HEB',10,17,null,$b$Jêh ri Păng lah tay: “Jêh ri Gâp mâu mra hôm kah gĭt ma nau tih mâu lah nau kue khân păng ôh.”$b$,true),
('bunong-vn','HEB',10,18,null,$b$Pô nây, ta ntŭk geh nau yô̆ ma nau tih, mâu hôm geh ndơ nhhơr yor nau tih ôh.$b$,true),
('bunong-vn','HEB',10,19,null,$b$Pô ri, hơi phung oh nâu, yor lah ma mham Brah Yêsu he janh lăp tâm ntŭk kloh,$b$,true),
('bunong-vn','HEB',10,20,null,$b$ma trong mhe jêh ri rêh Păng pơk jêh ma he rgăn bok mphiar, nâm bu ntĭt nglay săk Păng nơm,$b$,false),
('bunong-vn','HEB',10,21,null,$b$jêh ri yor lah he geh du huê kôranh ƀư brah toyh tâm ngih Brah Ndu,$b$,false),
('bunong-vn','HEB',10,22,null,$b$ăn he sŏk nuih n'hâm răp jăp, bêng ma nau chroh ngăn, nuih n'hâm dơi kloh jêh tă bơh nau mhĭk, săk jăn rao kloh ma dak rsang hăn tât dăch Brah Ndu.$b$,false),
('bunong-vn','HEB',10,23,null,$b$Ăn he djôt prăp ăn nâp nau mbơh ma he kâp gân, yor lah nơm ton jêh ma he nau răp jăp.$b$,false),
('bunong-vn','HEB',10,24,null,$b$Ăn he mĭn ma bu êng gay tâm nchâp ma nau rŏng jêh ri ma nau ƀư kan ueh.$b$,false),
('bunong-vn','HEB',10,25,null,$b$Lơi ta cha lơi ôh nau vay tâm rƀŭn, nâm bu phung ƀa ƀă, ƀiă lah ăn he nsŭk nsôr ndrăng nơm jêh ri ƀư nau nây lơ hâu âk lơn đŏng, khân may saơ nar dăch tât.$b$,false),
('bunong-vn','HEB',10,26,null,$b$Yor lah tơ lah he ƀư tih ma nau ŭch jêh he gĭt rbăng jêh nau nanê̆, mâu hôm geh nau ƀư brah yor nau tih ôh.$b$,true),
('bunong-vn','HEB',10,27,null,$b$Ƀiă lah gŭ kâp ma nau klach ma nau phat dôih, jêh ri ŭnh duh ngăn mra sa phung tâm rdâng.$b$,false),
('bunong-vn','HEB',10,28,null,$b$Mbu nơm rlau nau vay Y-Môis khĭt mâu dơi geh nau yô̆ ôh, tơ lah geh bar pe nuyh nơm mbơh.$b$,true),
('bunong-vn','HEB',10,29,null,$b$Moh nau phat dôih mhĭk lơn mra khư tât ma phung jot kon Brah Ndu tâm dâng jâng khân păng, kơp ƀơ̆ mham nau tâm rnglăp, ƀư kloh jêh khân păng, jêh ri suai rak ma Brah Huêng Ueh nau yô̆ ?$b$,false),
('bunong-vn','HEB',10,30,null,$b$Yor lah he gĭt năl jêh nơm lah pô aơ: “Gâp mra plơng bôk. Gâp mra nkhôm.” Jêh ri lah đŏng: “Kôranh Brah mra phat dôih ƀon lan păng.”$b$,true),
('bunong-vn','HEB',10,31,null,$b$Jêng nau klach ngăn tŭp tâm ti Brah Ndu rêh.$b$,false),
('bunong-vn','HEB',10,32,null,$b$Ăn khân may kah gĭt ma nar lor, tơ lah jêh khân may geh nau ang, khân may dơn jêh nau tâm lơh tâm nklang nau rêh ni,$b$,true),
('bunong-vn','HEB',10,33,null,$b$geh tơ̆ khân may dơn nau bêk jêh ri nau rêh ni, jêh ri geh tơ̆ khân may jêng băl đah phung geh nau rêh ni pô aơ.$b$,false),
('bunong-vn','HEB',10,34,null,$b$Yor lah khân may geh jêh nau yô̆ ma phung bu nă, jêh ri khân may dơn jêh nau răm maak nau bu pit in drăp ndơ khân may, yor lah khân may gĭt, drăp ndơ ueh lơn jêh ri gŭ n'ho ro.$b$,false),
('bunong-vn','HEB',10,35,null,$b$Pô ri, lơi cha lơi ôh nau khân may rnơm, yor lah mra geh nau nkhôm toyh.$b$,true),
('bunong-vn','HEB',10,36,null,$b$Yor lah khlay ma khân may geh nau srôih, gay ma jêh ăn nanê̆ nau Brah Ndu ŭch, khân may mra geh nau Păng ton jêh ma khân may.$b$,false),
('bunong-vn','HEB',10,37,null,$b$“Hôm knŏng ƀât lât, nơm văch mra văch, jêh ri mâu mbrĕ mbrơi ôh.$b$,true),
('bunong-vn','HEB',10,38,null,$b$Jêh ri Nơm sŏng gâp mra gŭ rêh ma nau chroh. Ƀiă lah tơ lah Păng rŭch, huêng gâp mâu hôm maak ndrel Păng ôh.”$b$,true),
('bunong-vn','HEB',10,39,null,$b$Ƀiă lah he mâu jêng phung plơ̆ rŭch hăn tâm nau roh hêt ôh, ƀiă lah phung geh nau chroh gay tâm rklaih huêng khân păng.$b$,true),
('bunong-vn','HEB',11,1,null,$b$Nau chroh jêng nau rnơm nâp rjăp ma ndơ bu kâp gân jêh, nau gĭt nanê̆ ma nau bu mâu blau saơ ôh.$b$,true),
('bunong-vn','HEB',11,2,null,$b$Ma nau chroh phung u che he kăl e geh nau Brah Ndu dơn.$b$,false),
('bunong-vn','HEB',11,3,null,$b$Ma nau chroh he gĭt rbăng Brah Ndu rhăk njêng neh ntu aơ ma nau Păng ngơi, yor lah ndơ bu saơ mâu jêng ôh bơh ndơ bu mâu saơ.$b$,true),
('bunong-vn','HEB',11,4,null,$b$Yor nau păng rnơm nây Y-Abel nhhơr mpa ƀư brah ueh lơn ma Y-Kain. Dĭng geh Brah Ndu dơn jêh ri kơp păng jêng sŏng, yor nau păng rnơm nây lĕ păng ăt hôm ngơi nđâp tơ lah păng khĭt.$b$,true),
('bunong-vn','HEB',11,5,null,$b$Ma nau păng rnơm Brah Ndu chông Y-Hênok hao klơ, mâu ăn păng mâp nau khĭt. Bu mâu hôm saơ păng ôh, yor lah Brah Ndu sŏk păng. Tĭng nâm nau bu hŏ nchih, ê lor Y-Hênok hao klơ, hŏ ueh jêh măt Brah Ndu uănh păng.$b$,false),
('bunong-vn','HEB',11,6,null,$b$Knŏng mbu nơm rnơm ma Brah Ndu, nơm nây ueh măt Brah Ndu uănh. Pô ri mbu nơm ŭch hăn dăch ta Brah Ndu, ăn păng gĭt geh Brah Ndu ngăn, jêh ri ăn gĭt nau Brah Ndu nkhôm ma mbu nơm joi Păng.$b$,false),
('bunong-vn','HEB',11,7,null,$b$Ma nau păng rnơm yơh, Y-Nôê klach yơk, jêh Brah Ndu mbơh ma Păng ndơ bu ê mâp saơ ôh, păng iăt nau Brah Ndu jêh ri ndâk du mlâm kŭmpăn gay ma tâm rklaih rnăk vâl păng. Nau păng ƀư pô nây păng tâm mpơl nau tih phung neh ntu, jêh ri Brah Ndu kơp păng jêng sŏng, yor nau păng rnơm.$b$,false),
('bunong-vn','HEB',11,8,null,$b$Ma nau păng rnơm, Y-Abraham tông bâr Brah Ndu, kuăl ăn păng du tât ta n'gor êng, jêng n'gor Brah Ndu ton, ăn ma păng jêh ri ma kon sau păng. Păng dâk tă bơh bri nơm, păng mâu gĭt ôh mbah ntŭk păng mra hăn.$b$,true),
('bunong-vn','HEB',11,9,null,$b$Ma nau păng rnơm păng jêng tâm ban ma bu năch, dôl păng gŭ tâm n'gor Brah Ndu hŏ ton ăn jêh ma păng. Păng gŭ tâm ngih bok ndrel ma Y-Isăk, Y-Yakôp, jêng phung dơn ndrel nau Brah Ndu ton.$b$,true),
('bunong-vn','HEB',11,10,null,$b$Păng gŭ tâm ngih bok nây, păng ăt kâp gân lĕ, gay ma dơi geh du ƀon toyh ngih mbâl, jêng ƀon Brah Ndu nơm hŏ nkra jêh ri rdâk njêng.$b$,false),
('bunong-vn','HEB',11,11,null,$b$Ma nau păng rnơm lĕ, H'Sara dơi deh kon, nđâp tơ lah săk păng hŏ ranh kđôi lĕ. Yor lah păng rnơm ma Nơm ton ma păng, kơp nau nây jêng nau nanê̆ ngăn.$b$,true),
('bunong-vn','HEB',11,12,null,$b$Yor ri tă bơh du huê aơ, jêng bunuyh ranh bơi ma khĭt dŭt, ƀiă lah dơi geh kon geh sau bĭk âk nâm bu mănh klơ trôk mâu lah choih rgŏ kơh dak mƀŭt, mâu blau kơp.$b$,false),
('bunong-vn','HEB',11,13,null,$b$Lĕ rngôch khân păng khĭt da dê jêh tâm nau chroh, khân păng mâu yŏng dơn ôh nau Brah Ndu ton, ƀiă lah khân păng n'gơr uănh jêh ri mbah nau nây ntơm bơh ngai, khân păng kơp săk khân păng nơm jêng bunuyh hăn nkơi gŭ jăng jai ta neh ntu.$b$,true),
('bunong-vn','HEB',11,14,null,$b$Phung lah pô nây jêng tâm mpơl nau khân păng ŭch hăn joi bri khân păng nơm.$b$,false),
('bunong-vn','HEB',11,15,null,$b$Khân păng mâu hôm kah gĭt ôh ma n'gor khân păng tă luh du nây dơh, lah kah gĭt ma n'gor nây khân păng dơi plơ̆ sĭt yơh.$b$,true),
('bunong-vn','HEB',11,16,null,$b$Ƀiă lah khân păng rvê ŭch gŭ n'gor ueh lơn jêng n'gor tâm trôk. Yor ri Brah Ndu mâu geh bêk ôh bu kuăl păng jêng Brah Ndu khân păng, yor lah păng yơh rdâk njêng ƀon toyh nây ma khân păng.$b$,true),
('bunong-vn','HEB',11,17,null,$b$Ma nau chroh Y-Abraham nhhơr jêh Y-Isăk, lah Brah Ndu rlong uănh păng, jêh ri nơm geh jêh nau ton nhhơr kon păng geh knŏng du huê.$b$,true),
('bunong-vn','HEB',11,18,null,$b$Jêh ri ma nơm aơ geh jêh nau lah pô aơ: “Tâm Y-Isăk yơh phung kon sau may mra geh amoh săk?”$b$,false),
('bunong-vn','HEB',11,19,null,$b$Păng mĭn ma Brah Ndu jêng brah dơi ăn rêh phung amoh săk hŏ khĭt jêh, nâm bu păng geh Y-Isăk tâm nau hôr ma nau dâk rêh.$b$,false),
('bunong-vn','HEB',11,20,null,$b$Ma nau chroh yơh Y-Isăk dăn nau ueh lăng mra tât nar kăndơ̆ ma Y-Yakôp, jêh ri ma Y-Êsau.$b$,true),
('bunong-vn','HEB',11,21,null,$b$Ma nau chroh Y-Yakôp, dôl păng dăch khĭt, dăn nau ueh uĭn mra tât ma ăp nơm kon bu klâu Y-Yôsep, jêh ri mbah yơk ma Brah Ndu dôl păng kuăn rdâng ta mâng jra păng.$b$,false),
('bunong-vn','HEB',11,22,null,$b$Ma nau chroh yơh Y-Yôsep, dôl păng dăch khĭt, mbơh nau phung Israel mra luh, jêh ri ntăm ma phung nây yor nting păng.$b$,false),
('bunong-vn','HEB',11,23,null,$b$Ma nau chroh yơh, jêh bu deh ma Y-Môis, mê̆ mbơ̆ păng pôn păng pe khay, yor lah khân păng saơ kon nây ueh jêh ri khân păng mâu klach ôh ma nau hađăch ntăm jêh.$b$,true),
('bunong-vn','HEB',11,24,null,$b$Ma nau chroh yơh, Y-Môis, jêh văch ma toyh, dun jêng kon bu klâu ma kon bu ur Pharaôn,$b$,false),
('bunong-vn','HEB',11,25,null,$b$rŏng âk lơn dơn nau rêh ni đah phung mpôl băl Brah Ndu, ma nau gŭ maak ƀât lât tâm nau tih.$b$,false),
('bunong-vn','HEB',11,26,null,$b$Păng kơp nau rêh ni dơn yor Brah Krist, nâm bu nau ndrŏng lơn ma drăp n'gor Êjipt, yor lah păng uănh ma nau nkhôm.$b$,false),
('bunong-vn','HEB',11,27,null,$b$Ma nau chroh yơh păng du tă bơh n'gor Êjipt mâu klach ma nau hađăch ji nuih ôh, yor lah păng gŭ nâp rjăp, nâm bu păng hŏ saơ jêh nơm bu mâu blau saơ.$b$,false),
('bunong-vn','HEB',11,28,null,$b$Ma nau chroh yơh păng nkra Nau Găn jêh ri mhĭng mham, gay ma nơm ƀư rai mâu brot ôh phung kon Israel.$b$,false),
('bunong-vn','HEB',11,29,null,$b$Ma nau chroh yơh khân păng rgăn Dak Mƀŭt Chăng nâm bu ta ntŭk sơh ƀiă lah phung Êjipt rmok lĕ, tơ lah khân păng ŭch ƀư tâm ban.$b$,true),
('bunong-vn','HEB',11,30,null,$b$Ma nau chroh yơh mpêr ƀon Yêrikô rlâm jêh bu hăn, dôl tâm pơh nar jŭm ƀon nây.$b$,false),
('bunong-vn','HEB',11,31,null,$b$Ma nau chroh yơh H'Rahap, bu ur tăch săk, mâu khĭt ôh ndrel phung tâm rdâng, yor lah păng rom jêh phung n'hut uănh ma nau ueh.$b$,false),
('bunong-vn','HEB',11,32,null,$b$Jêh ri moh gâp mra lah? Yor lah gâp mâu geh ru ôh gay ngơi ma Y-Gêđêôn, ma Y-Barak, ma Y-Samsôn, ma Y-Jêptê, ma Y-Đavit, ma Y-Samuel jêh ri ma phung kôranh nơm mbơh lor.$b$,true),
('bunong-vn','HEB',11,33,null,$b$Ma nau chroh yơh khân păng dơi jêh đah ƀon bri hađăch, phat dôih ma nau sŏng, sŏk dơn jêh nau ton, rdôp jêh trôm mbung yau mŭr,$b$,false),
('bunong-vn','HEB',11,34,null,$b$nkhĭt lơi jêh nau duh ŭnh, klaih đah măt đao gưm, dôl huơi khân păng jêng ktang, dơi tâm nau tâm lơh, mprơh phung ta han rlăng.$b$,false),
('bunong-vn','HEB',11,35,null,$b$Phung bu ur sŏk dơn tay phung khĭt, khân păng dâk rêh, ƀa ƀă dơn nau bu ƀư rêh ni jêh ri dun nau bu mƀơk, gay dơi geh nau dâk rêh ueh lơn.$b$,false),
('bunong-vn','HEB',11,36,null,$b$Ƀa ƀă êng dơn nau bu mưch jêh ri nau bu dŏng, nau bu chăp ma rse rvăk jêh ri nau bu krŭng.$b$,false),
('bunong-vn','HEB',11,37,null,$b$Khân păng dơn nau bu klŭp lŭ, nau bu ot ma ndruih, nau bu rlong uănh, nau bu tâm nkhĭt ma đao gưm; khân păng nsŏng lam ntŭk soh ntâu biăp, ntâu be, pưt ăp ntil ndơ, bu ƀư mhĭk, ƀư ƀai ma khân păng,$b$,true),
('bunong-vn','HEB',11,38,null,$b$neh ntu mâu khư ma khân păng ôh, khân păng nsong mblêng tâm bri rdah, tâm yôk, tâm trôm yôk jêh ri trôm neh.$b$,false),
('bunong-vn','HEB',11,39,null,$b$Jêh ri lĕ rngôch phung nây geh nau mbơh ueh, yor nau chroh khân păng, mâu mâp sŏk dơn ôh nau Brah Ndu ton jêh ma khân păng.$b$,false),
('bunong-vn','HEB',11,40,null,$b$Yor lah Brah Ndu geh jêh nau ueh lơn ma he, gay ma khân păng mâu dơi tât ma nau ueh rah vah ôh lor ma he.$b$,true),
('bunong-vn','HEB',12,1,null,$b$Pô ri, yor lah he geh âk phung mbơh gŭ jŭm he nâm bu ndâr tơm mih, ăn he dun lơi lĕ ndơ ƀư jâk jêh ri nau tih nkŭm he nơih pơih, jêh ri ăn he nchuăt ma nau srôih tâm ntŭk nchuăt bu pơk jêh ma he,$b$,true),
('bunong-vn','HEB',12,2,null,$b$dôl uănh ma Brah Yêsu jêng tơm reh tâm nau chroh, Kôranh jêh ri Nơm ăn rah vah nau chroh he, jêh ri yor nau maak prăp jêh ma Păng, Păng dơn nau rêh ni ta si tâm rkăng, tâm rmot ma nau prêng, jêh ri gŭ jêh mpeh pa ma sưng hađăch Brah Ndu.$b$,false),
('bunong-vn','HEB',12,3,null,$b$Ăn khân may mĭn ma Nơm dơn jêh nau mhĭk phung tih ƀư ma Păng, gay lơi ăn khân may jêng rgănh jêh ri rdja nuih n'hâm ôh.$b$,false),
('bunong-vn','HEB',12,4,null,$b$Khân may ê mâp tâm rdâng tâm lơh đah nau tih, kŏ mham khân may rung ôh.$b$,true),
('bunong-vn','HEB',12,5,null,$b$Jêh ri khân may, chuêl jêh nau tâm n'hao nuih ma khân may nâm bu ma phung kon: “Hơi nâu, lơi tâm rmot ôh nau Kôranh Brah nkra may, jêh ri lơi rdja nuih n'hâm ôh tơ lah păng nduyh may.$b$,true),
('bunong-vn','HEB',12,6,null,$b$Yor lah Kôranh Brah Ndu mbu nơm Păng rŏng. Jêh ri Păng dong ma mâng phung Păng gĭt năl jêng Kon Păng.”$b$,true),
('bunong-vn','HEB',12,7,null,$b$Ăn khân may dơn nau nkra yor lah Brah Ndu ƀư ma khân may nâm bu kon; yor lah mbu kon mbơ̆ păng mâu nkra ôh?$b$,true),
('bunong-vn','HEB',12,8,null,$b$Tơ lah khân may klaih bơh nau nkra nâm bu lĕ rngôch phung êng dơn jêh, khân may jêng kon bu bă kon êng yơh, mâu di kon tơm ngăn ôh.$b$,false),
('bunong-vn','HEB',12,9,null,$b$Rlau lơn ma nau nây he geh jêh, mbơ̆ tâm nglay săk nkra he, jêh ri ăt he yơk ma khân păng lĕ. Mâu di hĕ he mra tông rlau lơn, ma nây ma Mbơ̆ phung huêng, gay geh nau rêh?$b$,false),
('bunong-vn','HEB',12,10,null,$b$Phung mbơ̆ he nkra jêh he, knŏng ƀât lât tĭng nâm nau khân păng mĭn ueh, ƀiă lah Brah Ndu nkra he gay ma ueh ma he, pô ri he dơi geh du kô̆ tâm nau kloh ueh Păng.$b$,false),
('bunong-vn','HEB',12,11,null,$b$Ntơm lor, nanê̆ lĕ rngôch nau nkra jêng nau rngot jêh ri mâu maak ôh, ƀiă lah ma nar kăndơ̆ Păng njêng play nau đăp mpăn bơh nau sŏng ma phung geh jêh nau nkra nây.$b$,false),
('bunong-vn','HEB',12,12,null,$b$Yơr hom ti rdja khân may jêh ri ƀư ktang hom kômâk rbăn khân may.$b$,true),
('bunong-vn','HEB',12,13,null,$b$Ăn jâng khân may tĭng trong sŏng, gay ma jâng kue mâu teng trong ôh, ƀiă lah păng mra bah.$b$,false),
('bunong-vn','HEB',12,14,null,$b$Joi hom nau đăp mpăn ma lĕ rngôch bunuyh, jêh ri nau kloh ueh, tơ lah pưt nau nây, mâu geh du huê mra saơ Kôranh Brah ôh.$b$,true),
('bunong-vn','HEB',12,15,null,$b$Ăn khân may njrăng, lơi ăn du huê pưt nau Brah Ndu yô̆ ôh, jêh ri lơi ăn geh reh tăng hon, jêh ri ƀư nau uh ah, mplum nau tih ma bu êng.$b$,false),
('bunong-vn','HEB',12,16,null,$b$Lơi ăn du huê jêng ka n'hong mâu lah ƀơ̆ nâm bu Y-Êsau, nơm tăch nau păng jêng nâu ranh, ma du tơ̆ ndơ sông sa.$b$,false),
('bunong-vn','HEB',12,17,null,$b$Khân may gĭt kăndơ̆ păng ŭch tay geh nau ueh uĭn, ƀiă lah bu dun păng, nđâp tơ lah păng joi ma dak măt kđôi lĕ. Păng mâu dơi saơ nau tâm rgâl ôh.$b$,false),
('bunong-vn','HEB',12,18,null,$b$Yor lah khân may mâu hăn dăch ôh ta yôk bu dơi brot, geh ŭnh sa, geh nau ngo, nau rngot, nau sial phŭt,$b$,true),
('bunong-vn','HEB',12,19,null,$b$geh bâr nŭng jêh ri bâr ngơi kŏ phung tăng dăn, lơi hôm ngơi du ntil ma khân păng ôh.$b$,false),
('bunong-vn','HEB',12,20,null,$b$Yor lah khân păng mâu dơi dơn ôh nau nti ăn jêh ma khân păng nâm pô aơ: “Nđâp tơ lah du mlâm jun prot dăch yôk nây bu mra klŭp ma lŭ ro.”$b$,false),
('bunong-vn','HEB',12,21,null,$b$Jêh ri nau tâm mpơl bêng ma nau klach, kŏ Y-Môis lah: “Gâp klach ngăn, sâr săk jăn.”$b$,false),
('bunong-vn','HEB',12,22,null,$b$Ƀiă lah khân may hăn dăch jêh ta yôk Siôn, ma ƀon Brah Ndu rêh, ƀon Yêrusalem tâm trôk, jêh ri ma rmưn rsen Tông mpăr ueh tâm rƀŭn ma nau maak,$b$,false),
('bunong-vn','HEB',12,23,null,$b$ma nau tâm rƀŭn jêh ri ma phung ngih Brah Ndu phung deh lor, amoh khân păng mra nchih jêh tâm trôk, ma kôranh phat dôih jêng Brah Ndu ma lĕ rngôch, ma phung huêng phung sŏng tât jêh ma nau ueh rah vah,$b$,false),
('bunong-vn','HEB',12,24,null,$b$ma Brah Yêsu, jêng Nơm tâm nklang ma nau tâm rnglăp mhe, jêh ri ma mham nkhŭt jêh, mham nây ngơi ueh lơn ma mham Y-Abel.$b$,false),
('bunong-vn','HEB',12,25,null,$b$Njrăng hom, lơi khân may dun ma nơm gŭ ngơi ôh. Yor lah tơ lah phung nây mâu klaih ôh, tơ lah khân păng dun iăt nơm mbơh ma khân păng ta neh ntu, nanê̆ he mâu mra klaih ôh, tơ lah he dun ma Nơm ngơi bơh trôk.$b$,true),
('bunong-vn','HEB',12,26,null,$b$Dôl nây bâr Păng ngơi n'gơ neh ntu, ƀiă lah aƀaơ Păng ton jêh pô aơ: “Du tơ̆ đŏng gâp mra rgu ăn n'gơ, mâu di knŏng neh ntu ôh, ƀiă lah nđâp ma trôk tâm ban lĕ.”$b$,false),
('bunong-vn','HEB',12,27,null,$b$Jêh ri rplay ngơi aơ: “Du tơ̆ đŏng” tâm mpơl nau tâm rgâl ndơ rgu jêh, nâm bu ndơ păng rhăk jêh, gay ma ndơ mâu dơi rgu mra hôm.$b$,false),
('bunong-vn','HEB',12,28,null,$b$Yor ri ăn he kah gĭt tôr, yor he sŏk dơn ƀon bri hađăch mâu dơi rgu ôh. Jêh ri ăn he nhhơr ma Brah Ndu nau yơk ƀư maak ma Păng ma nau mbah jêh ri nau klach.$b$,true),
('bunong-vn','HEB',12,29,null,$b$Yor lah Brah Ndu he jêng ŭnh hit lĕ.$b$,false),
('bunong-vn','HEB',13,1,null,$b$Ăn khân may ăt geh nau rŏng ndrăng oh nâu.$b$,true),
('bunong-vn','HEB',13,2,null,$b$Lơi chuêl nau blau rom bu ôh, yor lah dôl ƀư nau nây, geh ƀa ƀă rom jêh Tông mpăr ueh Brah Ndu, mâu gĭt năl khân păng ôh,$b$,false),
('bunong-vn','HEB',13,3,null,$b$kah gĭt hom ma phung bu krŭng, tâm ban ma bu krŭng khân may nơm lĕ, bu krŭng jêh, jêh ri ma phung bu ƀư mhĭk; yor lah khân may tâm ban lĕ gŭ tâm du săk jăn.$b$,false),
('bunong-vn','HEB',13,4,null,$b$Ăn lĕ rngôch bunuyh yơk ma nau tâm gŭ ur sai, jêh ri lơi kơp sưng bêch ƀơ̆ ôh; yor lah Brah Ndu mra phat dôih phung tâm lâm jêh ri phung văng tĭr.$b$,true),
('bunong-vn','HEB',13,5,null,$b$Lơi ta jao khân may nơm ma nau rŏng ma prăk ôh, ăn khân may răm maak ma ndơ khân may geh jêh, yor lah Brah Ndu nơm lah jêh: “Gâp mâu mra lơi ôh, mâu lah dun may ôh.”$b$,true),
('bunong-vn','HEB',13,6,null,$b$Pô ri he dơi lah ma nau rnơm: “Kôranh Brah jêng nơm kơl gâp, gâp mâu mra klach ôh. Moh bunuyh dơi ƀư ma gâp.”$b$,false),
('bunong-vn','HEB',13,7,null,$b$Kah gĭt hom ma phung gai khân may, phung mbơh jêh nau Brah Ndu ngơi ma khân may. Sek uănh nau tât ma nau rêh khân păng, jêh ri kơt nau chroh khân păng.$b$,true),
('bunong-vn','HEB',13,8,null,$b$Yêsu Krist ăt jêng nâm pô nây, nđaơ, nar aơ jêh ri n'ho ro. Mâu blau rgâl ôh.$b$,true),
('bunong-vn','HEB',13,9,null,$b$Lơi ta khân may kơt nau nti êng êng, jêh ri bu năch ôh, yor lah ueh ma nuih n'hâm jêng nâp ma nau yô̆, mâu di ma ndơ sông sa ôh; nau nây mâu jêng khlay ôh ma phung ƀư nau nây.$b$,true),
('bunong-vn','HEB',13,10,null,$b$He geh du nơng ƀư brah, phung pah kan tâm ngih bok mâu dơi sa ta nây ôh.$b$,false),
('bunong-vn','HEB',13,11,null,$b$Săk jăn mpô mpa bu gŭch pa dih, ƀiă lah mham păng kôranh ƀư brah toyh djôt leo ta ntŭk kloh ueh, yor nau tih.$b$,false),
('bunong-vn','HEB',13,12,null,$b$Yor nây lĕ Brah Yêsu dơn nau rêh ni pa dih mpông pêr, gay ƀư kloh ƀon lan ma mham Păng Nơm.$b$,false),
('bunong-vn','HEB',13,13,null,$b$Ăn he luh du ta Păng pa dih ntŭk gŭ, dôl djôt nau bêk Păng.$b$,false),
('bunong-vn','HEB',13,14,null,$b$Yor lah tâm dâng aơ he mâu geh ƀon gŭ ƀa ƀơ n'ho ro ôh, ƀiă lah he joi ƀon ma nar kăndơ̆ .$b$,true),
('bunong-vn','HEB',13,15,null,$b$Ma păng ăn he nhhơr, mâu rlu ôh, nau ƀư brah tâm rnê ma Brah Ndu, nâm bu ntĭt play bơh trôm mbung he, mbơh amoh păng.$b$,false),
('bunong-vn','HEB',13,16,null,$b$Jêh ri lơi chuêl ôh nau ƀư ueh jêh ri nau lŏng, yor lah nau ƀư brah tâm ban pô nây ƀư maak ma Brah Ndu.$b$,false),
('bunong-vn','HEB',13,17,null,$b$Tông hom ma phung gai khân may, jêh ri yơk ma khân păng, yor lah khân păng mât mray huêng khân may, nâm bu phung nkoch mbơh ma Brah Ndu, gay ma khân păng dơi nkoch mbơh ma nau maak jêh ri lơi geh nau njang bâr, yor lah nau nây mâu mâu ueh ôh ma khân may.$b$,true),
('bunong-vn','HEB',13,18,null,$b$Mbơh sơm ăn ma hên ƀă: Yor lah hên mĭn geh nuih n'hâm sŏng ueh, gay hăn ma nau ueh tâm lĕ rngôch mpa.$b$,true),
('bunong-vn','HEB',13,19,null,$b$Gâp vơh vơl ma khân may, ƀư nau nây gay ma gâp dơi hăn gơnh ma khân may.$b$,false),
('bunong-vn','HEB',13,20,null,$b$Ăn Brah Ndu nau đăp mpăn, nơm hŏ ndâk rêh jêh kôranh Brah he, Brah Yêsu, bơh phung khĭt, rmăk Kôranh ma phung biăp, ma mham nau tâm rnglăp n'ho ro,$b$,true),
('bunong-vn','HEB',13,21,null,$b$ăn khân may dơi ƀư ăp ntil kan ueh, gay ma nanê̆ nau Păng ŭch, jêh ri ƀư tâm khân may nau ƀư maak ma Păng, ma Yêsu Krist; ma Nơm aơ yơh nau chrêk rmah tâm lĕ rngôch rnôk. Amen.$b$,false),
('bunong-vn','HEB',13,22,null,$b$Hơi phung oh nâu, gâp vơh vơl ma khân may, dơn lĕ nau ngơi tâm n'hao nuih aơ, yor gâp nchih ma khân may knŏng ngơi trăch.$b$,true),
('bunong-vn','HEB',13,23,null,$b$Ăn khân may gĭt ma oh he, Y-Timôthê, bu mƀơk jêh. Tơ lah păng văch gơnh, gâp mra hăn khâl khân may ndrel ma păng.$b$,false),
('bunong-vn','HEB',13,24,null,$b$Ăn khân may njuăl nau khâl ma lĕ rngôch phung gai khân may jêh ri đah lĕ rngôch phung kloh ueh. Phung bơh n'gor Italy njuăl nau khâl ma khân may lĕ.$b$,true),
('bunong-vn','HEB',13,25,null,$b$Ăn nau yô̆ gŭ ndrel ma lĕ rngôch khân may. Amen.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','HEB',1,1,0,'heading',$b$Brah Ndu Tâm Mpơl Păng Nơm Tâm Kon Păng$b$),
('bunong-vn','HEB',1,4,1,'heading',$b$Kon Brah Ndu Jêng Toyh Lơn Ma Phung Tông mpăr Ueh$b$),
('bunong-vn','HEB',2,5,0,'heading',$b$Brah Yêsu Krist Dơn Nau Tông Bâr Gay Ma Tâm Rklaih Bunuyh$b$),
('bunong-vn','HEB',3,1,0,'heading',$b$Brah Yêsu Jêng Toyh Lơn Ma Y-Môis$b$),
('bunong-vn','HEB',4,1,0,'heading',$b$Ăn He Lăp Tâm Nau Brah Ndu Rlu$b$),
('bunong-vn','HEB',4,14,1,'heading',$b$Yêsu Krist Jêng Kôranh Ƀư Brah Toyh Lơn Ma Phung Kôranh Ƀư Brah Tâm Nau Tâm Rnglăp mhe$b$),
('bunong-vn','HEB',5,4,0,'heading',$b$Krist Jêng Kôranh Ƀư Brah Toyh Tâm Ban Ma Mêlkisadek$b$),
('bunong-vn','HEB',6,1,0,'heading',$b$Rêh Ni Ngăn Cha Lơi Nau Chroh$b$),
('bunong-vn','HEB',7,1,0,'heading',$b$Brah Yêsu Đah Mêlkisadek$b$),
('bunong-vn','HEB',7,11,1,'heading',$b$Nau Yêsu Krist Jêng Kôranh Ƀư Brah N'ho Ro Ăn Lôch Jêh Nau Ƀư Brah Phung Lêvi$b$),
('bunong-vn','HEB',8,1,0,'heading',$b$Brah Yêsu Jêng Kôranh Ƀư Brah Toyh Lơn$b$),
('bunong-vn','HEB',9,1,0,'heading',$b$Nau Yơk Mbah Tâm Neh Ntu Jêh Ri Nau Yơk Mbah Ta Klơ Trôk$b$),
('bunong-vn','HEB',9,11,1,'heading',$b$Knŏng Nau Brah Yêsu Ƀư Brah Jêng Rah Vah$b$),
('bunong-vn','HEB',10,1,0,'heading',$b$Kranh Brah Yêsu Jêng Tơm Nau Tâm Rklaih$b$),
('bunong-vn','HEB',10,19,1,'heading',$b$Nau Nti Ăn Blau Rnơm Jêh Ri Gŭ Nâp Tâm Nau Chroh$b$),
('bunong-vn','HEB',11,1,0,'heading',$b$Nau Chroh Nau Păng Jêng Nau Khlay Jêh Ri Geh Ndrel Ma Nau Tâm Ntĭt Bơh Nau Tâm Rnglăp Ơm$b$),
('bunong-vn','HEB',12,1,0,'heading',$b$Nau Srôih Dôl Geh Nau Rlong Uănh Nâm Bu Brah Krist$b$),
('bunong-vn','HEB',12,12,1,'heading',$b$Nau Ăn Kloh Ueh Nau Nti Êng Êng$b$),
('bunong-vn','HEB',13,1,0,'heading',$b$Nau Rêh Ueh Măt Brah Ndu Uănh$b$),
('bunong-vn','HEB',13,18,1,'heading',$b$Nau Khâl$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'JAS', $b$Y-Yakơ$b$, $b$["Sămƀŭt Tĭng Nâm", "Y-YAKƠ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JAS',1,1,null,$b$Y-Yakơ jêng oh mon Brah Ndu jêh ri Brah Yêsu Krist nchih khâl ma phung jât ma bar nuyh mpôl băl nchah du êng êng.$b$,true),
('bunong-vn','JAS',1,2,null,$b$Hơi phung oh nâu, tơ lah khân may mâp ma nau rlong uănh âk ntil, ăn kơp nau nĕ jêng nau răm maak da dê,$b$,true),
('bunong-vn','JAS',1,3,null,$b$yor lah khân may gĭt jêh nau rlong uănh ma nau khân may chroh njêng nau srôih.$b$,false),
('bunong-vn','JAS',1,4,null,$b$Ƀiă lah ăn nau srôih ăn jêh nanê̆ kan păng, gay ma khân may jêng ueh rah vah, mâu geh nau pưt ôh.$b$,false),
('bunong-vn','JAS',1,5,null,$b$Tơ lah mbu nơm tâm phung khân may, pưt nau blau mĭn, dăn hom ma Brah Ndu, nơm ăn ma lĕ rngôch bunuyh ma nau lŏng jêh ri mâu nuih janh ôh, jêh ri păng mra geh.$b$,true),
('bunong-vn','JAS',1,6,null,$b$Ƀiă lah ăn păng dăn ma nau chroh lơi đing ôh, yor lah mbu nơm đing, nơm nĕ jêng tâm ban ma dak mƀŭt njach, sial đô̆ jêh ri rdu păng.$b$,false),
('bunong-vn','JAS',1,7,null,$b$Bunuyh nĕ lơi păng mĭn mra sŏk dơn du ntil ndơ bơh Kôranh Brah ôh.$b$,false),
('bunong-vn','JAS',1,8,null,$b$Nau mĭn bunuyh nĕ tâm pă, mâu geh du ai ôh tâm lĕ kan păng ƀư.$b$,false),
('bunong-vn','JAS',1,9,null,$b$Ăn bunuyh gŭ ntŭk tâm dâng tâm rnê ma nau n'hao păng.$b$,true),
('bunong-vn','JAS',1,10,null,$b$Ƀiă lah ăn bunuyh ndrŏng tâm rnê ma nau păng dêh rhêt ma bu; yor lah păng mra rlau lôch nâm bu kao si.$b$,false),
('bunong-vn','JAS',1,11,null,$b$Yor lah nar luh, geh duh ktang. Gơ̆ păng kro, kao păng rŭng, jêh ri nau ueh păng roh. Nâm nđĕ lĕ, bunuyh ndrŏng mra hoănh kro tâm kan păng ƀư. Nau Rlong Uănh Jêh Ri Nau Yô̆$b$,false),
('bunong-vn','JAS',1,12,null,$b$Ueh maak yơh mbu nơm srôih dơn nau rlong uănh, yor lah jêh păng dơi, păng mra geh đon hađăch nau rêh, Brah Ndu ton jêh ma phung rŏng ma păng.$b$,false),
('bunong-vn','JAS',1,13,null,$b$Dôl du huê bunuyh geh nau ndơm, lơi ăn păng lah: “Brah Ndu yơh ndơm gâp.” Yor lah nau mhĭk mâu dơi ndơm Brah Ndu ôh, jêh ri Brah Ndu nơm mâu mâp ndơm bunuyh ôh.$b$,false),
('bunong-vn','JAS',1,14,null,$b$Ƀiă lah ăp nơm bunuyh geh nau ndơm tơ lah nau păng kơnh têk jêh ri nchâp păng.$b$,true),
('bunong-vn','JAS',1,15,null,$b$Nau kơnh jêh păng ntreo, păng deh nau tih, jêh nau tih văch ma toyh, păng njêng nau khĭt.$b$,true),
('bunong-vn','JAS',1,16,null,$b$Hơi phung oh nâu gâp rŏng, lơi ta khân may vĭ ôh.$b$,true),
('bunong-vn','JAS',1,17,null,$b$Lĕ nau yô̆ ueh jêh ri lĕ nau ăn yô̆ di tât bơh klơ, bơh Mbơ̆ nau ang. Tâm păng mâu geh nau rgâl ôh, mâu lĕ geh gui nau rgâl.$b$,false),
('bunong-vn','JAS',1,18,null,$b$Ma nau păng ngơi ngăn păng deh ma he tĭng nâm păng ŭch. Nâm nđĕ yơh he jêng phung lor lơn tâm lĕ rngôch ndơ păng njêng.$b$,false),
('bunong-vn','JAS',1,19,null,$b$Hơi phung oh nâu gâp rŏng, khân may gĭt jêh nau aơ. Pô ri ăn lĕ rngôch bunuyh gơnh tâm iăt, ƀât ngăch ngơi, ngăch ji nuih ôh.$b$,true),
('bunong-vn','JAS',1,20,null,$b$Yor lah nau bunuyh nuih mâu tâm di nau sŏng bơh Brah Ndu ôh.$b$,false),
('bunong-vn','JAS',1,21,null,$b$Yor nây yơh, cha lơi hom nau ƀơ̆ ƀơch jêh ri lĕ nau ƀai ăn khân may dơn Nau Ngơi tăm jêh tâm phung khân may ma nuih n'hâm rdơ̆ nau ngơi nĕ dơi tâm rklaih huêng khân may.$b$,false),
('bunong-vn','JAS',1,22,null,$b$Ăn khân may ƀư tĭng nâm Nau Ngơi, lơi knŏng iăt jêh ri ndơm khân may nơm.$b$,true),
('bunong-vn','JAS',1,23,null,$b$Yor lah tơ lah du huê bunuyh knŏng iăt jêh ri mâu ƀư tĭng nâm Nau Ngơi ôh, păng jêng nâm bu du huê bunuyh uănh muh măt păng tâm măt rachŏk;$b$,true),
('bunong-vn','JAS',1,24,null,$b$jêh saơ muh măt păng nơm, păng du ta ntŭk êng jêh ri chuêl ro nau păng jêng.$b$,false),
('bunong-vn','JAS',1,25,null,$b$Ƀiă lah mbu nơm sek uănh jêh ri srôih uănh tâm nau vay ueh bơh nau kon me, mâu di păng jêng bunuyh knŏng tăng jêh ri chuêl lơi, ƀiă lah păng ƀư tĭng nâm nau ntăm, bunuyh nĕ mra geh nau ueh maak tâm kan păng.$b$,false),
('bunong-vn','JAS',1,26,null,$b$Tơ lah du huê mĭn păng jêng bunuyh chroh jêh ri păng mâu njrăng mpiăt păng, ƀiă lah păng ndơm nuih n'hâm păng nơm, nau chroh bunuyh nĕ jêng dơm dam.$b$,true),
('bunong-vn','JAS',1,27,null,$b$Pô aơ ntil nau chroh kloh ngăn jêh ri mâu ƀơ̆ ôh ta năp Brah Ndu Mbơ̆ he, jô̆ khâl phung kon đơi jêh ri phung bu ur ndrô, dôl khân păng gŭ rêh ni, jêh ri mât mray khân may nơm ma nau ƀơ̆ tă bơh neh ntu.$b$,false),
('bunong-vn','JAS',2,1,null,$b$Hơi phung oh nâu, khân may geh nau chroh ma Kôranh Brah he Yêsu Krist Kôranh chrêk rmah. Lơi uănh ma bunuyh êng êng ôh.$b$,true),
('bunong-vn','JAS',2,2,null,$b$Nâm bu ntĭt du huê bunuyh dok rgên mah jêh ri nsoh ao ueh ngăn lăp tâm ntŭk khân may tâm rƀŭn jêh ri geh tay du huê bunuyh o ach nsoh ao sat lăp lĕ,$b$,false),
('bunong-vn','JAS',2,3,null,$b$khân may uănh ma bunuyh nsoh ao ueh jêh ri lah ma păng: “Gŭ hom ta ntŭk ueh aơ,” jêh ri khân may lah ma du huê o ach: “May gŭ râng ta nĕ.” Mâu lah: “Gŭ hom tâm dâng rnơl ntŭk gâp chrong jâng,”$b$,false),
('bunong-vn','JAS',2,4,null,$b$di lĕ khân may uănh jêng êng êng tâm phung khân may jêh ri phat dôih ma nau mĭn mhĭk nâm bu pô nây?$b$,false),
('bunong-vn','JAS',2,5,null,$b$Khân may iăt hom, hơi phung oh nâu gâp rŏng, Brah Ndu mâu mâp săch hĕ phung o ach ta neh ntu aơ gay ma khân păng jêng ndrŏng tâm nau chroh jêh ri jêng phung dơi dơn ƀon bri hađăch păng ton jêh ma phung rŏng ma păng?$b$,false),
('bunong-vn','JAS',2,6,null,$b$Ƀiă lah khân may tâm rmot ma phung o ach. Mâu di phung ndrŏng hĕ tŭn jot khân may jêh ri têk khân may leo hăn ta ntŭk phat dôih?$b$,false),
('bunong-vn','JAS',2,7,null,$b$Mâu di khân păng hĕ ngơi sưr ma amoh ueh bu kuăl ma khân may?$b$,false),
('bunong-vn','JAS',2,8,null,$b$Tơ lah khân may tông ma nau vay hađăch tĭng nâm nau nchih: “Khân may mra rŏng ma phung chiau meng khân may nâm bu khân may nơm lĕ,” khân may ƀư ueh yơh.$b$,true),
('bunong-vn','JAS',2,9,null,$b$Ƀiă lah tơ lah khân may uănh bunuyh êng êng, khân may ƀư tih, jêh ri nau vay kơp khân may jêng phung tih.$b$,false),
('bunong-vn','JAS',2,10,null,$b$Yor lah mbu nơm tông lĕ nau vay, ƀiă lah rlau du ntil nau ntăm, jêng bunuyh rlau lĕ rngôch yơh.$b$,true),
('bunong-vn','JAS',2,11,null,$b$Pô nây yơh, nơm lah: “Lơi văng tĭr ôh.” Păng lah đŏng: “Lơi nkhĭt bunuyh ôh.” Pô ri tơ lah may mâu văng tĭr ôh, ƀiă lah may nkhĭt bunuyh, ăt may jêng bunuyh rlau nau vay lĕ.$b$,false),
('bunong-vn','JAS',2,12,null,$b$Ngơi jêh ri ƀư hom nâm bu phung bunuyh bu mra phat dôih ma nau vay kon me.$b$,false),
('bunong-vn','JAS',2,13,null,$b$Yor lah nau phat dôih mâu yô̆ ôh ma mbu nơm mâu blau yô̆. Ƀiă lah nau yô̆ dơi đah nau phat dôih.$b$,false),
('bunong-vn','JAS',2,14,null,$b$Hơi phung oh nâu, moh khlay ma du huê lah păng geh nau chroh tơ lah păng mâu geh kan tâm mpơl? Nau chroh nĕ dơi tâm rklaih păng đŏng?$b$,true),
('bunong-vn','JAS',2,15,null,$b$Tơ lah geh nâu mâu lah oh ruh gŭ săk lưn, jêh ri mâu geh ndơ sông sa ma ăp nar,$b$,false),
('bunong-vn','JAS',2,16,null,$b$jêh ri du huê tâm phung khân may lah ma ô băl: “Hăn hom đăp mpăn, gŭ hơm răm, sa ăn hơm,” jêh ri khân may mâu ăn ndơ sŏk dơn ma nglay săk jăn ô băl, moh khlay nau nĕ?$b$,false),
('bunong-vn','JAS',2,17,null,$b$Bi nau chroh nâm nđĕ lĕ, tơ lah păng mâu geh kan tâm mpơl, păng khĭt jêh yơh.$b$,false),
('bunong-vn','JAS',2,18,null,$b$Ƀiă lah du huê mra lah: “May geh nau chroh, jêh ri gâp geh kan.” Tâm mpơl ma gâp nau may chroh mâu geh kan, jêh ri gâp mra tâm mpơl nau gâp chroh tâm kan gâp ƀư.$b$,false),
('bunong-vn','JAS',2,19,null,$b$May chroh geh knŏng du huê Brah Ndu di jêh. Phung Brah mhĭk chroh tâm ban lĕ jêh ri khân păng sâr săk jăn.$b$,false),
('bunong-vn','JAS',2,20,null,$b$Hơi bunuyh rvưt, may ŭch gĭt lĕ ma nau may chroh mâu geh kan tâm mpơl jêng dơm dam?$b$,false),
('bunong-vn','JAS',2,21,null,$b$Mâu di hĕ mbơ̆ he Y-Abraham, geh nau kơp sŏng ma kan tâm mpơl yor lah păng nhhơr kon păng Y-Săk, ta klơ nơng ƀư brah?$b$,false),
('bunong-vn','JAS',2,22,null,$b$Pô ri, may saơ nau chroh tâm mpơl tâm kan, jêh ri ma kan tâm mpơl nau chroh jêng rah vah,$b$,false),
('bunong-vn','JAS',2,23,null,$b$pô ri jêng nanê̆ nau nchih jêh: “Abraham chroh ma Brah Ndu, nau nĕ kơp păng jêng sŏng,” jêh ri Brah Ndu kuăl păng jiăng ma Păng.$b$,false),
('bunong-vn','JAS',2,24,null,$b$Khân may saơ jêh ma kan tâm mpơl yơh bunuyh geh, nau kơp sŏng, mâu di knŏng nau chroh ôh.$b$,false),
('bunong-vn','JAS',2,25,null,$b$Nâm bu H'Rahap, du huê bu ur tăch săk bu kơp păng sŏng yor kan tâm mpơl, yor lah păng rom phung bunuyh mbơh jêh ri ăn khân păng hăn sĭt trong êng?$b$,false),
('bunong-vn','JAS',2,26,null,$b$Pô ri, nâm bu săk jăn mâu geh huêng, păng khĭt, nau chroh mâu geh kan tâm mpơl jêng khĭt tâm ban lĕ.$b$,false),
('bunong-vn','JAS',3,1,null,$b$Hơi phung oh nâu, tâm phung khân may lơi ăn jêng âk nơm nti ôh, yor lah khân may gĭt jêh, bu mra phat dôih khân may ktang lơn.$b$,true),
('bunong-vn','JAS',3,2,null,$b$Yor lah lĕ rngôch he tih tâm âk ntil nau. Tơ lah du huê mâu tih ôh tâm nau păng ngơi, păng jêng bunuyh rah vah, dơi chiă uănh lĕ săk jăn păng.$b$,false),
('bunong-vn','JAS',3,3,null,$b$Tơ lah he ntrŭp loih gang tâm mbung seh gay ma păng tông ma he, nâm nđĕ mơ he dơi gai lĕ săk jăn păng.$b$,false),
('bunong-vn','JAS',3,4,null,$b$Uănh nđâp ma lĕ ngôch kŭmpăn păng toyh ngăn jêh ri sial ktang njach khân păng kđôi lĕ, ƀiă lah ăt bu dơi gai khân păng tĭng nâm rmăk ŭch ma ndơ rvet jê̆ lê̆.$b$,false),
('bunong-vn','JAS',3,5,null,$b$Mpiăt tâm ban lĕ, păng jêng ndơ jê̆ tâm săk jăn, ƀiă lah păng dơi ngơi âk nau toyh. Uănh hom, krŏng toyh ngăn ŭnh jê̆ dơi sa lĕ păng!$b$,false),
('bunong-vn','JAS',3,6,null,$b$Mpiăt jêng ŭnh lĕ. Păng jêng ntŭk tih tâm săk jăn he. Păng ƀư ƀơ̆ lĕ săk jăn, su lĕ nau rêh, jêh ri ŭnh tă bơh n'gar ŭnh su nđâp ma păng lĕ.$b$,false),
('bunong-vn','JAS',3,7,null,$b$Ăp ntil mpô mpa, sĭm och, mpa vơr nđâp ka tâm dak mƀŭt, dơi ƀư ơih aƀaơ aơ jêh ri kăl e phung bunuyh ƀư ơih jêh,$b$,false),
('bunong-vn','JAS',3,8,null,$b$ƀiă lah mpiăt mâu geh nơm dơi ƀư ơih păng ôh, păng jêng ndơ tih mâu dơi blau buay ôh, păng bêng ma dak kăch nau khĭt.$b$,false),
('bunong-vn','JAS',3,9,null,$b$Ma mpiăt he dơi mât ton ma Kôranh Brah, Mbơ̆ he, ma mpiăt lĕ he vay tâm rtăp rak ma bunuyh, Brah Ndu rhăk njêng jêh kơt rup păng nơm.$b$,false),
('bunong-vn','JAS',3,10,null,$b$Tă bơh mbung lĕ luh nau mât ton tâm rnê jêh ri nau rtăp rak. Lơi ƀư pô nây ôh, phung oh nâu.$b$,true),
('bunong-vn','JAS',3,11,null,$b$Mâp geh tă bơh du tu dak, luh dak ueh jêh ri dak tăng?$b$,false),
('bunong-vn','JAS',3,12,null,$b$Hơi oh nâu tơm play rvi, dơi lĕ păng play jêng play Ôlivơ, mâu lah dơi lĕ tơm play kriăk ƀâu, play jêng play rvi? Tâm ban lĕ, bơh tu dak tăng mâu lĕ dơi luh dak ueh.$b$,false),
('bunong-vn','JAS',3,13,null,$b$Mbu nơm tâm phung khân may jêng nơm blau mĭn jêh ri gĭt rbăng? Ăn păng tâm mpơl kan păng tâm nau gŭ ngao krao sach ueh ma nau dêh rhêt bơh nau blau mĭn.$b$,true),
('bunong-vn','JAS',3,14,null,$b$Ƀiă lah tơ lah tâm nuih n'hâm khân may geh nau mâu nach, tăng jêh ri nau tâm djrel, lơi ta rnê êng nơm ôh jêh ri lơi mƀruh tâm rdâng đah nau nanê̆ ôh.$b$,true),
('bunong-vn','JAS',3,15,null,$b$Nau blau mĭn nĕ mâu geh luh bơh klơ ôh, ƀiă lah bơh neh ntu, bơh nglay săk, bơh brah mhĭk yơh.$b$,false),
('bunong-vn','JAS',3,16,null,$b$Yor lah ta ntŭk geh nau mâu nach tăng jêh ri nau tâm djrel, ta nĕ geh nau uh ah jêh ri ăp ntil nau mhĭk.$b$,true),
('bunong-vn','JAS',3,17,null,$b$Ƀiă lah nau blau mĭn, luh tă bơh klơ, lor lơn jêng kloh, jêh ri đăp mpăn, di keh, blau tâm gop bêng ma nau yô̆ jêh ri play ueh, mâu geh bar nuih mâu lah nuih n'hâm ndâp ôh.$b$,false),
('bunong-vn','JAS',3,18,null,$b$Phung joi nau đăp mpăn srih play nau sŏng tâm nau đăp mpăn.$b$,false),
('bunong-vn','JAS',4,1,null,$b$Mbah tă luh nau tâm lơh jêh ri nau tâm lah tâm djrel tâm phung khân may? Mâu di hĕ păng luh tă bơh nau nglay săk ŭch, vay tâm lơh tâm săk jăn khân may?$b$,true),
('bunong-vn','JAS',4,2,null,$b$Khân may kơnh jêh ri mâu dơi geh ôh, khân may nkhĭt bunuyh jêh ri mâu nach, ƀiă lah mâu dơi geh ôh, khân may geh nau tâm djrel jêh ri nau tâm lơh ƀiă lah khân may mâu geh ôh, yor lah khân may mâu dăn ôh.$b$,false),
('bunong-vn','JAS',4,3,null,$b$Khân may dăn jêh ri khân may mâu sŏk dơn ôh, yor lah tih khân may dăn, ŭch dŏng tĭng nâm nglay săk khân may ŭch.$b$,false),
('bunong-vn','JAS',4,4,null,$b$Khân may jêng phung ka n'hong yơh! Khân may mâu gĭt hĕ nau jêng băl đah neh ntu jêng rlăng đah Brah Ndu? Pô ri yơh, mbu nơm ŭch ƀư băl đah neh ntu, păng jêng rlăng đah Brah Ndu.$b$,true),
('bunong-vn','JAS',4,5,null,$b$Khân may mĭn ma nau nchih jêng dơm dam hĕ? Brah Huêng Ueh Brah Ndu, ăn gŭ tâm he, rŏng ma he tât păng ntôn.$b$,false),
('bunong-vn','JAS',4,6,null,$b$Ƀiă lah păng ăn nau yô̆ toyh lơn; yor nây Nau Brah Ndu Ngơi lah nâm bu pô aơ: “Brah Ndu tâm rdâng đah phung sưr, ƀiă lah păng yô̆ ma phung dêh rhêt.”$b$,false),
('bunong-vn','JAS',4,7,null,$b$Khân may tông hom ma Brah Ndu. Khân may tâm rdâng hom đah brah mhĭk, jêh ri păng mra du ngai đah khân may.$b$,true),
('bunong-vn','JAS',4,8,null,$b$Hăn dăch hom khân may ma Brah Ndu jêh ri păng mra văch dăch ma khân may. Rao hom ti khân may phung tih. Hơi phung geh nau mĭn bar đah, ƀư kloh hom nuih n'hâm khân may.$b$,false),
('bunong-vn','JAS',4,9,null,$b$Ăn khân may gĭt nau rêh ni, klâng ndrê jêh ri nhĭm nhhiăng. Tâm rgâl nau gơm khân may jêng nau klâng ndrê, jêh ri nau răm maak khân may jêng nau rngot klâng.$b$,false),
('bunong-vn','JAS',4,10,null,$b$Ntrŭnh hom săk jăn khân may ta năp Kôranh Brah jêh ri păng mra yơk khân may.$b$,false),
('bunong-vn','JAS',4,11,null,$b$Hơi oh nâu, lơi ta khân may ngơi ndjơh ndrăng khân may nơm ôh. Mbu nơm ngơi ndjơh mâu lah phat dôih ma oh nâu, păng ngơi ndjơh jêh ri phat dôih ma nau vay yơh. Ƀiă lah tơ lah may phat dôih ma nau vay, may mâu jêng bunuyh tông ma nau vay ôh, ƀiă lah may jêng kôranh phat dôih ma nau vay.$b$,true),
('bunong-vn','JAS',4,12,null,$b$Geh knŏng du huê jêng nơm ăn nau vay jêh ri jêng kôranh phat dôih. Păng yơh dơi tâm rklaih jêh ri dơi ƀư rai lôch. Ƀiă lah moh may jêng? Mâm may janh phat dôih ma phung chiau meng may?$b$,false),
('bunong-vn','JAS',4,13,null,$b$Bi ma phung lah pô aơ: “Nar aơ mâu lah ôi taơ hên mra hăn ta du ƀon, hên mra gŭ ta nĕ du năm, tăch drăp jêh ri sa kao hao âk.”$b$,true),
('bunong-vn','JAS',4,14,null,$b$Ƀiă lah khân may mâu gĭt ôh moh nau mra tât ma nar ôi taơ. Pô ri yơh, moh nau rêh khân may jêng? Khân may jêng nâm bu dak n'hôl tâm mpơl ƀât lât jêh ri roh hêng.$b$,false),
('bunong-vn','JAS',4,15,null,$b$Ueh lơn khân may mra lah nâm pô aơ: “Tơ lah Kôranh Brah ŭch, jêh ri hên ăt hôm gŭ rêh, hên mra ƀư kan aơ kan ri.”$b$,false),
('bunong-vn','JAS',4,16,null,$b$Ƀiă lah aƀaơ khân may tâm rnê ma khân may nơm tâm nau mĭn sưr. Nau tâm rnê nĕ jêng djơh ngăn.$b$,false),
('bunong-vn','JAS',4,17,null,$b$Pô ri, mbu nơm blau nau ƀư ueh jêh ri păng mâu ƀư ôh, păng jêng tih yơh.$b$,false),
('bunong-vn','JAS',5,1,null,$b$Bi ma phung ndrŏng aƀaơ aơ, nhĭm nter hom khân may, yor lah nau rêh ni mra tât ma khân may.$b$,true),
('bunong-vn','JAS',5,2,null,$b$Drăp ndơ khân may jêng ôm jêh, jêh ri kho ao khân may lĕ nchiăr reh jêh.$b$,false),
('bunong-vn','JAS',5,3,null,$b$Prăk mah khân may lĕ ek găm, jêh ri ek găm nây mra mbơh tâm rdâng đah khân may, jêh ri păng mra sa rai nglay săk khân may nâm bu ŭnh. Khân may bun jêh drăp ndơ khân may tâm nar lôch dŭt.$b$,false),
('bunong-vn','JAS',5,4,null,$b$Aơ, rnoh nkhôm phung rek ba tâm mir lŏ khân may, rnoh nĕ khân may ntŭng prăp ma khân may nơm, nter jêh ri bâr nteh phung rek nter hao tât ta tôr Kôranh Brah phung ta han.$b$,false),
('bunong-vn','JAS',5,5,null,$b$Khân may gŭ rêh ta neh ntu ma nau răm maak tĭng nâm nglay săk ŭch, khân may ƀư hơm nuih n'hâm khân may tâm nar geh nau tâm sreh tâm ntâp nkhĭt bunuyh.$b$,false),
('bunong-vn','JAS',5,6,null,$b$Khân may tâm rmal jêh, khân may tâm nkhĭt jêh phung sŏng; păng mâu tâm rdâng đah khân may ôh.$b$,false),
('bunong-vn','JAS',5,7,null,$b$Hơi oh nâu, ăn khân may srôih tât Kôranh Brah plơ̆ văch. Aơ, bunuyh ƀư mir gŭ kâp, gay geh ndơ khlay tă bơh neh, păng srôih gŭ kâp tât geh dak mih tŭp mih rah jêh ri dak mih dăch lôch.$b$,true),
('bunong-vn','JAS',5,8,null,$b$Khân may tâm ban lĕ srôih hom, jêh ri gŭ nâp nuih n'hâm khân may yor lah nar Kôranh Brah plơ̆ văch hŏ dăch jêh.$b$,false),
('bunong-vn','JAS',5,9,null,$b$Hơi phung oh nâu, lơi ngơi ƀŭk dŭk suyh ndrăng khân may, gay ma bu mâu phat dôih ma khân may; aơ, kôranh phat dôih gŭ kâp jêh ta bôk mpông.$b$,true),
('bunong-vn','JAS',5,10,null,$b$Hơi phung oh nâu, uănh nau phung kôranh nơm mbơh lor srôih jêh ri dơn nau mhĭk jêng nau tâm ntĭt ma khân may. Phung nĕ ngơi jêh ma amoh Kôranh Brah.$b$,false),
('bunong-vn','JAS',5,11,null,$b$Aơ, he lah maak yơh ma phung srôih dơn nau rêh ni. Khân may tăng jêh bu nkoch bri ma nau Y-Yôp srôih jêh ri khân may saơ jêh nau Kôranh Brah ăn ma păng dăch ma lôch. Yor lah Kôranh Brah bêng ma nau yô̆ jêh ri ueh.$b$,false),
('bunong-vn','JAS',5,12,null,$b$Hơi oh nâu, lor lơn lơi sân săk ôh đah trôk, ma neh ntu mâu lah ma ndơ ƀa ƀă, ƀiă lah nau khân may lah, mâu, lah mâu, ngăn, lah ngăn, gay ma bu mâu phat dôih khân may ôh. Nau mbơh sơm, mbơh nau tih, jêh ri nau bunuyh plơ̆ sĭt$b$,true),
('bunong-vn','JAS',5,13,null,$b$Geh lĕ bunuyh geh nau jêr jêh ri nau bunuyh tih plơ̆ sĭt tâm phung khân ay may? Ăn păng mbơh sơm hom. Geh lĕ bunuyh geh nau răm maak? Ăn păng mprơ tâm rnê hom ma Kôranh Brah.$b$,false),
('bunong-vn','JAS',5,14,null,$b$Geh lĕ bunuyh ji tâm phung khân ay may? Ăn păng kuăl hom phung bu ranh kơl kan tâm ngih Brah Ndu, jêh ri ăn phung nĕ mbơh sơm an ma păng jêh ri mhĭng dak ngi tâm amoh Kôranh Brah.$b$,false),
('bunong-vn','JAS',5,15,null,$b$Lah khân păng mbơh sơm ma nau rnơm, Kôranh Brah mra tâm rklaih bunuyh ji, păng mra ƀư bah nơm nĕ jêh ri yô̆ an nau tih păng.$b$,false),
('bunong-vn','JAS',5,16,null,$b$Pô ri ăn khân ay may tâm mbơh nau tih ndrăng nơm, jêh ri tâm kơl mbơh sơm ndrăng nơm, gay ma khân may gơnh bah. Lah du huê bunuyh sŏng mbơh sơm, geh nau dơi ngăn.$b$,false),
('bunong-vn','JAS',5,17,null,$b$Êli jêng bunuyh rdja tâm ban ma he. Păng mbơh sơm dăn gay ma trôk mâu hôm mih jêh ri mâu hôm geh dak mih ôh ta neh ntu dôl tâm pe năm n'gul.$b$,false),
('bunong-vn','JAS',5,18,null,$b$Păng mbơh sơm tay, dăn trôk ăn mih jêh ri neh jêng nse.$b$,false),
('bunong-vn','JAS',5,19,null,$b$Hơi phung oh nâu, tơ lah du huê tâm phung khân may nkhah du ngai bơh nau ngăn, jêh ri geh du huê êng jă păng sĭt.$b$,true),
('bunong-vn','JAS',5,20,null,$b$Mbu nơm njŭn du huê bunuyh tih plơ̆ sĭt cha lơi nau tih păng, nơm nây mra rklaih huêng bunuyh nĕ tă bơh nau khĭt, jêh ri âk nau tih păng bu mra yô̆ an.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','JAS',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','JAS',1,2,1,'heading',$b$Nau Rlong Uănh$b$),
('bunong-vn','JAS',1,19,2,'heading',$b$Ăn Ƀư Tĭng Nâm Nau Brah Ndu Ngơi$b$),
('bunong-vn','JAS',2,1,0,'heading',$b$Lơi Uănh Ma Bunuyh Êng Êng$b$),
('bunong-vn','JAS',2,14,1,'heading',$b$Nau Chroh Mâu Geh Kan Tâm Mpơl$b$),
('bunong-vn','JAS',3,1,0,'heading',$b$Nau Ât Rdâng Dŏng Mpiăt Ngơi$b$),
('bunong-vn','JAS',3,13,1,'heading',$b$Nau Blau Mĭn Bơh Klơ$b$),
('bunong-vn','JAS',4,1,0,'heading',$b$Tâm Rdâng Đah Nglay Săk Ŭch$b$),
('bunong-vn','JAS',4,11,1,'heading',$b$Lơi Ngơi Ndjơh Mâu Lah Phat Dôih Bu$b$),
('bunong-vn','JAS',4,13,2,'heading',$b$Nau Mâu Dơi Gĭt Nanê̆ Ma Kan Nar Kăndơ̆$b$),
('bunong-vn','JAS',5,1,0,'heading',$b$Phung Ndrŏng Djơh$b$),
('bunong-vn','JAS',5,7,1,'heading',$b$Nau Srôih Tâm Nau Rêh Ni$b$),
('bunong-vn','JAS',5,12,2,'heading',$b$Nau Sân Săk$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '1PE', $b$I Y-Pêtrôs$b$, $b$["Sămƀŭt Rơh Nguay Tĭng Nâm", "Y-PÊTRÔS"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','1PE',1,1,null,$b$Y-Pêtrôs kôranh oh mon Yêsu Krist, nchih njuăl ma phung bu năch jêh ri phung nchah du gŭ tâm n'gor Pônt, Galati, Kapadôs, Asi jêh ri Bithini,$b$,true),
('bunong-vn','1PE',1,2,null,$b$phung Brah Ndu săch jêh tĭng nâm nau Mbơ̆ , Brah Ndu, gĭt lor, tâm nau prăp an ueh ma Brah Huêng Ueh, gay ma khân păng tông jêh ri geh mham Yêsu Krist rhăk jêh khân păng; Ăn nau yô̆ jêh ri nau đăp mpăn tâm n'hao ma khân may.$b$,false),
('bunong-vn','1PE',1,3,null,$b$Mât ton ma Brah Ndu, Mbơ̆ Kôranh Brah he, Yêsu Krist! Yor nau yô̆ Păng toyh ngăn phung he dơi deh mhe rêh geh nau kâp gân, yor nau dâk rêh Brah Yêsu Krist bơh phung khĭt,$b$,true),
('bunong-vn','1PE',1,4,null,$b$gay ma he geh drăp ndơn mâu dơi blau ôm, mâu ƀơ̆ , mâu blau klêu ôh, prăp jêh tâm trôk ma khân may.$b$,false),
('bunong-vn','1PE',1,5,null,$b$Phung Brah Ndu chiă uănh ma nau Brah Păng yor nau chroh, gay geh nau tâm rklaih dăch tâm mpơl tâm nar dăch dŭt.$b$,false),
('bunong-vn','1PE',1,6,null,$b$Tâm nau nây khân may geh nau maak, ƀiă lah aƀaơ khân may vay dơn nau rngot ƀât lât tâm nau rlong uănh âk ntil kđôi lĕ,$b$,false),
('bunong-vn','1PE',1,7,null,$b$gay ma nau rlong uănh nau chroh khân may jêng khlay lơn ma mah blau rai, nđâp tơ lah bu rlong uănh păng tâm ŭnh kđôi lĕ, bu geh nau tâm rnê, nau chrêk rmah, jêh ri nau yơk tâm nar Yêsu Krist mra tâm mpơl.$b$,false),
('bunong-vn','1PE',1,8,null,$b$Khân may mâu mâp saơ Păng, ƀiă lah rŏng jêh ma păng. Khân may ê mâp saơ păng, ƀiă lah chroh jêh ma păng. Khân may rhơn ma nau răm maak, mâu blau rblang ôh, jêh ri chrêk rmah,$b$,false),
('bunong-vn','1PE',1,9,null,$b$yor lah khân may dơn nau nkhôm ma nau chroh khân may jêng nau tâm rklaih ma huêng khân may.$b$,false),
('bunong-vn','1PE',1,10,null,$b$Ma nau tâm rklaih nĕ phung kôranh nơm mbơh lor joi jêh ri sek jêh nanê̆ dôl khân păng mbơh ma nau yô̆ prăp jêh ma khân may.$b$,true),
('bunong-vn','1PE',1,11,null,$b$Khân păng joi ŭch gĭt rnôk jêh ri mâm nau Brah Huêng Ueh Brah Krist tâm khân păng tâm mpơl, dôl păng mbơh nau rêh ni Brah Krist, jêh ri nau chrêk rmah mra tĭng ndô̆.$b$,false),
('bunong-vn','1PE',1,12,null,$b$Nau nĕ tâm mpơl jêh ma khân păng, mâu di ma khân păng nơm ôh, ƀiă lah ma khân may yơh khân păng mbơh nau nĕ. Nau nây, aƀaơ phung nơm nti nau mhe mhan ueh ma Brah Huêng Ueh njuăl tă bơh trôk mbơh jêh ma khân may, nđâp phung Tông mpăr ueh Brah Ndu ŭch uănh nau nây lĕ.$b$,false),
('bunong-vn','1PE',1,13,null,$b$Yor nây ăn nâp nau mĭn khân may nâm bu rêt rse bŭt. Gŭ hom ăn di keh jêh ri kâp gân nanê̆ ma nau yô̆ Yêsu Krist mra njŭn an ma khân may, tâm nar păng mra tâm mpơl.$b$,true),
('bunong-vn','1PE',1,14,null,$b$Khân may nâm bu phung kon tông bâr, mâu hôm kơt ôh nau kơnh khân may geh kăl e dôl jăng jai khân may gŭ tâm nau rluk,$b$,false),
('bunong-vn','1PE',1,15,null,$b$ƀiă lah nâm bu nơm kuăl khân may jêng kloh ueh, ăn khân may kloh ueh tâm ban lĕ tâm lĕ nau khân may gŭ ngao krao sach;$b$,false),
('bunong-vn','1PE',1,16,null,$b$tĭng nâm nau nchih jêh: “Ăn khân may jêng kloh ueh, yor lah gâp nơm kloh ueh.”$b$,false),
('bunong-vn','1PE',1,17,null,$b$Jêh ri tơ lah khân may kuăl Mbơ̆ ma nơm phat dôih tĭng nâm kan ăp nơm mâu geh nau kơp êng êng ôh, ăn khân may gŭ ngao krao sach ma nau klach dôl khân may gŭ ƀât lât.$b$,false),
('bunong-vn','1PE',1,18,null,$b$Khân may gĭt jêh mâu di ma ndơ blau rai yot nâm bu prăk mâu lah mah ôh tâm chuai jêh khân may bơh nau rêh dơm dam, luh bơh u che khân may,$b$,false),
('bunong-vn','1PE',1,19,null,$b$ƀiă lah ma mham khlay Brah Krist, nâm bu du mlâm kon biăp mâu mâp tih mâu lah ƀơ̆ ,$b$,false),
('bunong-vn','1PE',1,20,null,$b$rơm prăp jêh bơh lor ma rhăk neh ntu, jêh ri tâm mpơl tâm rnôk nglĕ dŭt yor khân may.$b$,false),
('bunong-vn','1PE',1,21,null,$b$Ma Brah Yêsu lĕ khân may chroh ma Brah Ndu, Nơm rdâk Păng rêh tă bơh khĭt jêh ri ăn ma Păng nau chrêk rmah, gay ma nau chroh jêh ri nau khân may kâp gân mra rnơm tâm Brah Ndu.$b$,false),
('bunong-vn','1PE',1,22,null,$b$Huêng khân may kloh jêh tâm nau tông ma nau nanê̆, gay geh nau rŏng răp jăp ndrăng oh nâu, ăn khân may tâm rŏng ăn hâu ndrăng khân may ma lĕ nuih n'hâm.$b$,true),
('bunong-vn','1PE',1,23,null,$b$Khân may geh jêh nau deh mhe, mâu di ma ntil găr blau rai lôch, ƀiă lah ntil găr mâu dơi rai ôh, nây jêng Nau Ngơi rêh jêh ri ăt hôm mro bơh Brah Ndu:$b$,true),
('bunong-vn','1PE',1,24,null,$b$Yor lah: “Lĕ rngôch nglay săk nâm bu gơ̆ jêh ri lĕ nau chrêk rmah păng nâm bu kao gơ̆ . Gơ̆ kro, jêh ri kao păng rŭng,$b$,false),
('bunong-vn','1PE',1,25,null,$b$Ƀiă lah Nau Kôranh Brah Ngơi hôm mro mrăng n'ho ro”. Jêh ri nau ngơi nĕ jêng nau mhe mhan ueh mbơh jêh ma khân may. Ăn he dơi Yêsu Krist jêng lŭ njônh ngih$b$,false),
('bunong-vn','1PE',2,1,null,$b$Yor lah khân may cha lơi lĕ jêh nau ƀai, lĕ nau ƀlăch ƀlêr, nau nuih n'hâm ndâp, nau kơnh jêh ri lĕ nau ngơi ndjơh,$b$,true),
('bunong-vn','1PE',2,2,null,$b$ăn khân may rŏng ma dak toh brah jêh ri kloh nâm bu kon se mhe deh, gay ma ndơ nĕ khân may văch ma toyh ma nau tâm rklaih,$b$,false),
('bunong-vn','1PE',2,3,null,$b$tơ lah khân may chiăm ăn gĭt Kôranh Brah jêng ueh.$b$,false),
('bunong-vn','1PE',2,4,null,$b$Hăn hom khân may dăch ta păng, nơm jêng lŭ rêh, bu klŭp lơi jêh, ƀiă lah Brah Ndu săch, jêh ri jêng khlay ta năp păng,$b$,false),
('bunong-vn','1PE',2,5,null,$b$jêh ri khân may nơm jêng nâm bu lŭ rêh. Rdâk hom khân may gay njêng du mlâm ngih brah, jêng phung kôranh ƀư brah kloh ueh, gay nhơr ndơ ƀư brah, ƀư maak ma Brah Ndu ma Yêsu Krist.$b$,false),
('bunong-vn','1PE',2,6,null,$b$Yor lah geh nau nchih jêh nâm pô aơ: “Aơ, gâp dơm ta Siôn du mlâm lŭ njônh, gâp săch jêh ri khlay, Jêh ri mbu nơm chroh ma păng nĕ, mâu mra bêk ôh.”$b$,true),
('bunong-vn','1PE',2,7,null,$b$Nâm nđĕ ma khân may, phung chroh jêh, păng jêng khlay, ƀiă lah ma phung mâu chroh. “Lŭ phung ƀư ngih mƀăr lơi jêh, păng jêng lŭ tơm ta njônh”.$b$,true),
('bunong-vn','1PE',2,8,null,$b$Jêh ri, “Păng jêng lŭ chêh bu, jêh ri lŭ toyh ƀư prah bu.” Khân păng prah tom lŭ nĕ yor lah khân păng mâu tông ma nau ngơi, jêh ri nau nĕ prăp jêh ma khân păng.$b$,true),
('bunong-vn','1PE',2,9,null,$b$Ƀiă lah khân may jêng phung Brah Ndu săch jêh, phung kôranh ƀư brah ma hađăch, phung mpôl kloh ueh phung ƀon lan jêng jêh ndơ Brah Ndu ŭch, gay ma khân may mbơh nau ueh nơm kuăl khân may bơh nau ngo tât ta nau ang khlay păng.$b$,false),
('bunong-vn','1PE',2,10,null,$b$Khân may kăl e mâu jêng du phung ƀon lan ôh, ƀiă lah aƀaơ jêng phung ƀon lan Brah Ndu, kăl e ri mâu mâp geh nau yô̆ ma khân may ôh, ƀiă lah aƀaơ geh jêh nau yô̆ ma khân may.$b$,false),
('bunong-vn','1PE',2,11,null,$b$Hơi phung gâp rŏng, khân may jêng nâm bu phung bu năch jêh ri phung gŭ njưh ƀât lât tâm neh ntu, gâp vơh vơl ma khân may ăn khân may dun ma nau nglay săk kơnh, yor lah păng tâm lơh đah huêng khân may.$b$,true),
('bunong-vn','1PE',2,12,null,$b$Ăn khân may gŭ ngao krao sach ueh tâm nklang phung bu năch, ŭch ma tơ lah khân păng nchơt khân may jêng bunuyh mhĭk, khân păng mra saơ kan ueh khân may ƀư, jêh ri rnê ma Brah Ndu tâm nar Păng mra văch.$b$,false),
('bunong-vn','1PE',2,13,null,$b$Yor Kôranh Brah ăn khân may tông lĕ nau vay bunuyh nkra jêh, ma hađăch toyh lơn,$b$,true),
('bunong-vn','1PE',2,14,null,$b$Mâu lah ma kôranh toyh jêng oh mon ma hađăch, gay ma tâm rmal phung mhĭk jêh ri tâm rnê ma phung ueh.$b$,false),
('bunong-vn','1PE',2,15,null,$b$Yor lah pô aơ nau Brah Ndu ŭch, ma nau khân may ƀư ueh khân may mra ăn phung rluk mâl gŭ rklăk.$b$,false),
('bunong-vn','1PE',2,16,null,$b$Khân may jêng bunuyh kon me, mâu dŏng ôh nau kon me jêng bok nkŭm nau tih mhĭk, ƀiă lah ăn khân may ƀư nâm bu phung oh mon ma Brah Ndu.$b$,false),
('bunong-vn','1PE',2,17,null,$b$Ăn khân may yơk ma lĕ rngôch bunuyh. Rŏng ma phung oh nâu. Yơk jêh ri klach ma Brah Ndu. Yơk ma hađăch.$b$,false),
('bunong-vn','1PE',2,18,null,$b$Hơi phung oh mon ma lĕ nau klach, ăn khân may tông ma phung kôranh khân ay may, mâu di ôh knŏng ma phung kôranh ueh jêh ri rdơ̆ , ƀiă lah nđâp ma phung kôranh geh nau mĭn mhĭk tâm ban lĕ.$b$,true),
('bunong-vn','1PE',2,19,null,$b$Tơ lah knŏng ma nuih n'hâm sŏng ta năp Brah Ndu mra dơn nau rêh ni mâu di lah bơh nau tih păng ƀư, nau nĕ jêng nau ueh uĭn.$b$,false),
('bunong-vn','1PE',2,20,null,$b$Yor lah moh nau tâm rnê dơi geh tơ lah srôih dơn nau bu dong yor nau ƀư tih? Ƀiă lah tơ lah khân may srôih dơn nau rêh ni yor ƀư ueh, nau nĕ jêng nau ueh uĭn ta năp Brah Ndu.$b$,true),
('bunong-vn','1PE',2,21,null,$b$Jêh ri ma nau nĕ Brah Ndu kuăl jêh khân may, yor lah Brah Krist dơn jêh nau rêh ni ma khân may gay ăn ma khân may du nau tâm ntĭt, gay ma khân may kơt têl păng.$b$,false),
('bunong-vn','1PE',2,22,null,$b$“Păng mâu mâp ƀư tih ôh, jêh ri tâm trôm mbung păng mâu mâp saơ nau mƀruh lĕ.”$b$,true),
('bunong-vn','1PE',2,23,null,$b$Bu rtăp rak ma păng, păng mâu rtăp rak ma bu ôh; bu ƀư mhĭk ma păng, păng mâu thăm rmat ma bu ôh; ƀiă lah păng jao nau păng ma nơm phat dôih sŏng.$b$,false),
('bunong-vn','1PE',2,24,null,$b$Păng djôt nau tih he tâm săk jăn păng nơm ta klơ tơm si, gay ma he, phung khĭt jêh ma nau tih, mra rêh ma nau sŏng. Jêh ri ma sôt rmanh păng, khân may bah jêh.$b$,true),
('bunong-vn','1PE',2,25,null,$b$Yor lah khân may jêng nâm bu kon biăp nkhah du ƀiă lah aƀaơ khân may plơ̆ sĭt jêh ma rmăk biăp jêh ri ma nơm chiă huêng khân may.$b$,true),
('bunong-vn','1PE',3,1,null,$b$Hơi phung bu ur, ăn tông bâr ma sai khân ay, gay ma tơ lah geh ƀa ƀă sai mâu tông ma nau ngơi, phung bu ur mra dơi đah khân păng, mâu di knŏng nau ngơi ôh, ƀiă lah ma nau gŭ ngao krao sach ueh,$b$,true),
('bunong-vn','1PE',3,2,null,$b$yor lah khân păng saơ nau khân may gŭ ngao ueh jêh ri klach.$b$,false),
('bunong-vn','1PE',3,3,null,$b$Lơi ta khân ay may n'hĭ nkrơ̆ pa dih nâm bu păch sŏk, mblum ma mah mâu lah ma kho ao khân ay soh.$b$,false),
('bunong-vn','1PE',3,4,null,$b$Ƀiă lah joi hom nau tâm rnglăp tâm trôm ndâp tâm nuih n'hâm nau kloh mâu blau rai lôch tâm huêng rdơ̆ jêh ri gŭ rklăk. Nau aơ jêng rnoh khlay ta năp Brah Ndu.$b$,true),
('bunong-vn','1PE',3,5,null,$b$Nâm nđĕ yơh kăl e phung bu ur kloh ueh kâp gân tâm Brah Ndu ndrăp khân păng nơm. Khân păng tông ma sai khân păng.$b$,true),
('bunong-vn','1PE',3,6,null,$b$Nâm bu H'Sara tông ma Y-Abraham jêh ri kuăl ma păng kôranh păng. Tơ lah khân ay ƀư ueh jêh ri mâu geh du ntil nau klach ƀư uh ah khân ay, khân ay jêng kon bu ur H'Sara yơh.$b$,true),
('bunong-vn','1PE',3,7,null,$b$Mpeh ma khân may tâm ban lĕ, hơi phung sai, ăn khân may tâm mpơl nau gĭt rbăng tâm nau khân may gŭ ndrel ma ur khân may nâm bu đah phung rdja lơn. Yơk ma khân păng, yor lah khân păng tâm ban lĕ mra dơn ndrel ma khân may nau rêh bơh nau yô̆ gay lơi ăn geh nau buay ma nau khân may mbơh sơm. Nau nti ma nau rŏng, nau đăp mpăn jêh ri nau srôih$b$,true),
('bunong-vn','1PE',3,8,null,$b$Jêh ri ăn lĕ rngôch khân may geh nau mĭn tâm ban jêh ri geh du nuih n'hâm, bêng ma nau tâm rŏng ndrăng oh nâu, nau blau yô̆ jêh ri nau dêh rhêt.$b$,false),
('bunong-vn','1PE',3,9,null,$b$Lơi ta mplơ̆ nau mhĭk, ma nau mhĭk bu ôh, mâu lĕ mplơ̆ sĭt nau rtăp rak ma nau bu rtăp rak lĕ; ƀiă lah ăn mât ton hom yor lah nau nĕ Brah Ndu kuăl jêh khân may, gay ma khân may dơi dơn nau mât ton.$b$,false),
('bunong-vn','1PE',3,10,null,$b$Yor lah: “Tơ lah mbu nơm ŭch rŏng ma nau rêh jêh ri saơ nar ueh maak, ăn păng nkân mpiăt păng lơi ngơi nau mhĭk. Jêh ri trôm mbung păng lơi ngơi nau Ndơm.$b$,false),
('bunong-vn','1PE',3,11,null,$b$Ăn păng tĭt ngai, bơh nau ƀai, jêh ri ƀư nau ueh ăn păng joi nau đăp mpăn jêh ri tĭng ndô̆.$b$,true),
('bunong-vn','1PE',3,12,null,$b$Yor lah măt Kôranh Brah uănh ta phung sŏng srăng. Jêh ri tôr Păng kâp iăt ma nau khân păng mbơh sơm ƀiă lah muh măt Kôranh Brah mra rle rdâng đah phung ƀư mhĭk”.$b$,true),
('bunong-vn','1PE',3,13,null,$b$Tơ lah khân may duh nđơr ma nau ueh, mbu mra ƀư mhĭk ma khân may?$b$,true),
('bunong-vn','1PE',3,14,null,$b$Ƀiă lah tơ lah khân may dơn nau rêh ni yor nau sŏng, khân may geh nau ueh maak yơh. Lơi klach ma nau khân păng klach, jêh ri lơi ƀư uh ah ôh,$b$,false),
('bunong-vn','1PE',3,15,null,$b$ƀiă lah ăn khân may yơk ma Brah Krist jêng Kôranh Brah ƀư kloh tâm nuih n'hâm khân may. Ăn khân may gŭ njrăng ƀa ƀơ gay dơi plơ̆ lah ma nau yơk jêh ri nau rdơ̆ ma mbu nơm ôp ăn gĭt ma nau khân may kâp gân.$b$,false),
('bunong-vn','1PE',3,16,null,$b$Ăn khân may geh nuih n'hâm ueh sŏng, gay ma phung nchơt ma nau khân may gŭ ngao krao sach ueh tâm Brah Krist mra geh nau prêng dôl khân păng nchơt pô nây.$b$,false),
('bunong-vn','1PE',3,17,null,$b$Yor lah tơ lah Brah Ndu ŭch pô nây, nau bu dơn nau rêh ni yor nau păng ƀư ueh jêng ueh lơn ma dơn nau rêh ni yor nau păng ƀư mhĭk.$b$,false),
('bunong-vn','1PE',3,18,null,$b$Brah Krist tâm ban lĕ dơn jêh du tơ̆ nau rêh ni yor nau tih. Păng nơm sŏng tâm tang ma phung mâu sŏng ôh, gay ma njŭn leo he ma Brah Ndu. Bu nkhĭt jêh Păng tâm nglay săk, ƀiă lah tâm huêng Păng dâk rêh jêh.$b$,true),
('bunong-vn','1PE',3,19,null,$b$Tâm huêng nây lĕ Păng hăn mbơh jêh ma phung huêng bu krŭng jêh.$b$,false),
('bunong-vn','1PE',3,20,null,$b$Phung nây kăl e rĭ mâu tông ôh, tơ lah Brah Ndu srôih jŏ ndrel khân păng tâm rnôk Y-Nôê, dôl păng ƀư du mlâm kŭmpăn. Tâm kŭmpăn nây geh knŏng djê̆ bunuyh dơi klaih bơh dak, nâm bu ntĭt, knŏng pham nuyh.$b$,false),
('bunong-vn','1PE',3,21,null,$b$Dak nây jêng tâm ntĭt ma nau ƀaptem, dơi tâm rklaih khân may aƀaơ, mâu di nau ƀư kloh nau ƀơ̆ săk jăn ôh, ƀiă lah nau nuih n'hâm sŏng ueh, plơ̆ lah ta năp Brah Ndu, ma nau Yêsu Krist dâk rêh,$b$,false),
('bunong-vn','1PE',3,22,null,$b$nơm hao jêh ta klơ trôk jêh ri gŭ pa ma Brah Ndu. Phung Tông mpăr ueh, phung chiă uănh, jêh ri phung brah lăp tâm păng da dê jêh.$b$,false),
('bunong-vn','1PE',4,1,null,$b$Pô ri, nâm bu Brah Krist hŏ dơn jêh nau rêh ni tâm nglay săk, ăn khân may tâm ban lĕ geh nau mĭn nây, yor lah mbu nơm dơn jêh nau rêh ni tâm nglay săk, păng lôch jêh đah nau tih,$b$,true),
('bunong-vn','1PE',4,2,null,$b$gay ma dôl gŭ rêh tâm nglay săk, mâu hôm rêh tĭng nâm bunuyh kơnh ôh, ƀiă lah tĭng nâm Brah Ndu ŭch.$b$,false),
('bunong-vn','1PE',4,3,null,$b$Găp jêh ƀư kơt kăl e tĭng nâm nau phung bu năch ŭch, dôl ƀư nau tih ƀơ̆ ƀơch, nau kơnh, nhŭl ndrănh, nau nhêt sa rlau keh, jêh ri nau mbah ma rup brah ƀơ̆ mhĭk.$b$,false),
('bunong-vn','1PE',4,4,null,$b$Khân păng hih rhâl jêh ri ngơi nau mhĭk ma khân may, yor lah khân may mâu tĭng ndô̆ nau ƀơ̆ ƀơch rlau keh ndrel ma khân păng.$b$,false),
('bunong-vn','1PE',4,5,null,$b$Khân păng mra mbơh ma nơm kâp phat dôih ma phung rêh jêh ri phung khĭt.$b$,false),
('bunong-vn','1PE',4,6,null,$b$Yor nây nau mhe mhan ueh bu mbơh jêh ma phung khĭt, gay ma jêh phat dôih khân păng kơt nâm bu bunuyh tâm nglay săk, khân păng gŭ rêh tâm huêng tĭng nâm Brah Ndu.$b$,false),
('bunong-vn','1PE',4,7,null,$b$Nau dăch lôch ma lĕ rngôch ntil ndơ êp jêh. Pô ri ăn khân may gĭt mĭn jêh ri blau njrăng ma nau mbơh sơm.$b$,true),
('bunong-vn','1PE',4,8,null,$b$Rplay khlay ngăn, ăn khân may geh nau tâm rŏng ktang ndrăng khân may, yor lah nau rŏng nkŭm âk nau tih.$b$,false),
('bunong-vn','1PE',4,9,null,$b$Tâm rom hom ndrăng khân may, lơi ngơi ƀŭk dŭk suyh ôh.$b$,false),
('bunong-vn','1PE',4,10,null,$b$Nâm bu phung ueh kơl pă nau yô̆ Brah Ndu ăn, ăn ăp nơm tâm phung khân may blau dŏng nau yô̆ khân may geh jêh bơh Brah Ndu kơl phung êng.$b$,false),
('bunong-vn','1PE',4,11,null,$b$Tơ lah du huê ngơi, ăn păng ngơi nâm bu mbơh nau ngơi rêh tă bơh Brah Ndu. Tơ lah du huê pah kan, ăn păng pah kan ma nau ktang Brah Ndu ăn, gay ma Brah Ndu geh nau tâm rnê ma Yêsu Krist tâm lĕ rngôch ndơ. Ma Brah Krist yơh geh nau chrêk rmah jêh ri nau brah tâm lĕ rngôch rnôk. Amen!$b$,false),
('bunong-vn','1PE',4,12,null,$b$Hơi phung gâp rŏng, tơ lah khân may gŭ ta nklang ŭnh năk nau rlong uănh, lơi ta khân may ndrŏt ôh nâm bu nau hih rhâl tât ma khân may.$b$,true),
('bunong-vn','1PE',4,13,null,$b$Ƀiă lah maak hom khân may tâm nau rêh ni khân may dơn ndrel ma Brah Krist, gay ma tâm nar chrêk rmah Păng mra tâm mpơl, khân may mra geh nau răm jêh ri nau maak ngăn.$b$,false),
('bunong-vn','1PE',4,14,null,$b$Tơ lah bu suai rak khân may yor amoh Brah Krist, khân may geh nau răm maak yơh, yor lah nau chrêk rmah jêh ri Brah Huêng Ueh Brah Ndu gŭ tâm khân may.$b$,false),
('bunong-vn','1PE',4,15,null,$b$Lơi ăn du huê tâm phung khân may dơn nau rêh ni yor păng jêng nơm nkhĭt bunuyh, mâu lah nơm ntŭng, mâu lah nơm ƀư ƀai, mâu lah nơm lăp tâm kan bu êng ôh;$b$,false),
('bunong-vn','1PE',4,16,null,$b$ƀiă lah tơ lah du huê dơn nau rêh ni yor păng jêng phung Brah Krist, lơi ăn păng bêk ôh, ƀiă lah yor nây ăn păng tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','1PE',4,17,null,$b$Yor lah tât jêh mông nau phat dôih mra ntơm ma ngih Brah Ndu; pô ri, tơ lah păng ntơm đah phung he, moh mra jêng nau dăch dŭt ma phung mâu tông nau mhe mhan ueh Brah Ndu?$b$,false),
('bunong-vn','1PE',4,18,null,$b$Jêh ri: “Tơ lah phung sŏng tâm rklaih ma nau jêr moh mra jêng ma phung mhĭk jêh ri ma phung tih?”$b$,false),
('bunong-vn','1PE',4,19,null,$b$Pô ri ăn phung dơn nau rêh ni tĭng nâm Brah Ndu ŭch ƀư nau ueh jêh ri jao huêng khân păng ma nơm rhăk răp jăp.$b$,true),
('bunong-vn','1PE',5,1,null,$b$Aƀaơ, gâp njuăl nau ntĭnh ma phung bu ranh tâm phung khân may. Gâp jêng bu ranh nâm bu khân păng lĕ, jêh ri nơm saơ nau rêh ni Brah Krist dơn, jêh ri nơm mra geh nau chrêk rmah mra tâm mpơl.$b$,true),
('bunong-vn','1PE',5,2,null,$b$Ăn khân may chiă phung biăp Brah Ndu jao jêh ma khân may, mâu geh ƀư ma nau nchâp ôh, ƀiă lah ma nau ŭch, mâu di yor ma rnoh nkhôm ƀơ̆ ƀơch ôh ƀiă lah ma nau rŏng ma lĕ nuih n'hâm.$b$,false),
('bunong-vn','1PE',5,3,null,$b$Mâu di chiă uănh ma nau ktang kan pă ăn ma khân may ƀiă lah ăn khân may jêng nau tâm ntĭt ueh ma phung biăp.$b$,false),
('bunong-vn','1PE',5,4,null,$b$Jêh ri tơ lah kôranh phung rmăk biăp mra tâm mpơl, khân may mra geh đon hađăch nau chrêk rmah mâu dơi blau rai ôh.$b$,false),
('bunong-vn','1PE',5,5,null,$b$Bi ma khân may phung dôl druh ndăm tâm ban lĕ, ăn khân may tông ma phung bu ranh, jêh ri ăn lĕ rngôch khân may geh nau dêh rhêt ndrăng khân may, yor lah: “Brah Ndu tâm rdâng đah phung sưr, ƀiă lah păng ăn nau yô̆ ma phung dêh rhêt”.$b$,true),
('bunong-vn','1PE',5,6,null,$b$Pô ri ăn khân may dêh rhêt tâm dâng ti brah, Brah Ndu, gay ma păng n'hao khân may tâm nar di$b$,true),
('bunong-vn','1PE',5,7,null,$b$Ăn khân may jao ma păng lĕ rngôch nau rngot klâng khân may, yor lah păng nơm mât mơh khân may.$b$,false),
('bunong-vn','1PE',5,8,null,$b$Ăn khân may gŭ di keh, jêh ri gŭ njrăng. Nơm rlăng đah khân may Brah mhĭk, nâm bu yau mŭr ngrông ndăch nsong jŭm khân may joi mbu nơm păng dơi sa hêk,$b$,true),
('bunong-vn','1PE',5,9,null,$b$tâm rdâng hom đah păng ma nau chroh rjăp, yor lah khân may gĭt jêh ma nau rêh ni nâm nđĕ tât jêh ma phung oh nâu khân may lam bri neh.$b$,false),
('bunong-vn','1PE',5,10,null,$b$Brah Ndu ma lĕ nau yô̆ kuăl jêh khân may ma nau chrêk rmah păng n'ho ro tâm Yêsu Krist, ŭch ma jêh khân may dơn nau rêh ni ƀât lât, păng nơm mra njêng khân may rah vah, mra ƀư nâp khân may,$b$,false),
('bunong-vn','1PE',5,11,null,$b$mra ăn ktang khân may ma păng yơh geh nau brah tâm lĕ rngôch rnôk. Amen.$b$,false),
('bunong-vn','1PE',5,12,null,$b$Y-Silvan, nơm gâp uănh jêng nâm bu oh nâu răp jăp, gâp đă păng nchih bar pe rplay aơ ma khân may, gay nti jêh ri mbơh ma khân may gĭt ma nau yô̆ aơ bơh Brah Ndu jêng nanê̆ ăn khân may gŭ rjăp tâm nau nây.$b$,true),
('bunong-vn','1PE',5,13,null,$b$Phung ngih Brah Ndu ta ƀon Babilôn jêng phung săch jêh ndrel ma khân may, khâl đah khân may, Y-Markôs, kon gâp khâl đah khân may tâm ban lĕ.$b$,true),
('bunong-vn','1PE',5,14,null,$b$Ăn khân may tâm khâl ndrăng khân may ma nau chŭm tâm rŏng. Ăn nau đăp mpăn gŭ ndrel ma lĕ rngôch khân may tâm Brah Krist.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','1PE',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','1PE',1,3,1,'heading',$b$Nau Kâp Gân Jêh Ri Nau Rlong Uănh Nau Chroh$b$),
('bunong-vn','1PE',1,10,2,'heading',$b$Phung Kôranh Nơm Mbơh Lor Mbơh Jêh Nau Tâm Rklaih Tâm Brah Krist$b$),
('bunong-vn','1PE',1,13,3,'heading',$b$Nau Nti Kloh Ueh Jêh Ri Nau Rŏng$b$),
('bunong-vn','1PE',2,11,0,'heading',$b$Nau Nti Êng Êng$b$),
('bunong-vn','1PE',3,1,0,'heading',$b$Nau Vay Ndrăng Ur Sai$b$),
('bunong-vn','1PE',4,1,0,'heading',$b$Lơi Hôm Ƀư Tĭng Nâm Nau Bunuyh Kơnh Ôh$b$),
('bunong-vn','1PE',4,7,1,'heading',$b$Nau Njrăng Nau Rŏng Jêh Ri Kan Phung Chroh$b$),
('bunong-vn','1PE',4,12,2,'heading',$b$Nau Nti Ma Phung Dơn Nau Rêh Ni Yor Nau Chroh$b$),
('bunong-vn','1PE',5,1,0,'heading',$b$Kan Phung Bu Ranh Jêh Ri Phung Druh Ndăm$b$),
('bunong-vn','1PE',5,6,1,'heading',$b$Nau Dêh Rhêt Nau Njrăng Nau Chroh Nâp Rjăp$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '2PE', $b$II Y-Pêtrôs$b$, $b$["Sămƀŭt Rơh Bar Tĭng Nâm", "Y-PÊTRÔS"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','2PE',1,1,null,$b$Y-Simôn Pêtrôs, oh mon jêh ri kôranh oh mon Yêsu Krist. Nchih njuăl ma phung dơn jêh nau chroh khlay nâm bu nau hên chroh ma nau sŏng Brah Ndu he, jêh ri nơm tâm rklaih he, Yêsu Krist.$b$,true),
('bunong-vn','2PE',1,2,null,$b$Ăn nau yô̆ jêh ri nau đăp mpăn tâm n'hao khân may tâm nau gĭt năl Brah Ndu jêh ri Brah Krist, Kôranh Brah he.$b$,false),
('bunong-vn','2PE',1,3,null,$b$Nau brah Brah Ndu ăn jêh ma he lĕ rngôch nau khlay ma nau rêh jêh ri ma nau blau yơk ma Brah Ndu dôl păng ăn he gĭt năl nơm kuăl jêh he ma nau chrêk rmah jêh ri nau ueh păng nơm.$b$,true),
('bunong-vn','2PE',1,4,null,$b$Ma nau nĕ păng ăn jêh ma he nau ton toyh ngăn, gay ma nau ton nĕ khân may sŏk dơn nau khư Brah Ndu, dôl he du đah nau rai yot tâm neh ntu yor nau kơnh.$b$,false),
('bunong-vn','2PE',1,5,null,$b$Pô ri, yor nau nĕ ma lĕ nuih n'hâm ăn khân may ntop nau ueh ma nau khân may chroh, nau gĭt rbăng ma nau ueh,$b$,false),
('bunong-vn','2PE',1,6,null,$b$nau di keh ma nau gĭt rbăng, nau srôih ma nau di keh, nau blau yơk ma Brah Ndu ma nau srôih,$b$,false),
('bunong-vn','2PE',1,7,null,$b$jêh ri nau rŏng ndrăng oh nâu ma nau blau yơk ma Brah Ndu, jêh ri nau rŏng ma nau rŏng ndrăng oh nâu.$b$,false),
('bunong-vn','2PE',1,8,null,$b$Yor lah tơ lah lĕ nau nĕ gŭ tâm khân may jêh ri jêng bêng ler, khân păng mâu ăn khân may gŭ dơm dam mâu lah mâu geh play tâm nau gĭt năl Yêsu Krist, Kôranh Brah he.$b$,false),
('bunong-vn','2PE',1,9,null,$b$Ƀiă lah mbu nơm pưt nau nĕ jêng bunuyh chieh măt. Păng mâu dơi saơ ngai ôh jêh ri păng chuêl nau ƀư kloh nau tih păng sa ơm ri.$b$,false),
('bunong-vn','2PE',1,10,null,$b$Pô ri, hơi oh nâu, ăn khân may njrăng ăn gĭt nanê̆ ma nau Brah Ndu kuăl jêh ri săch khân may, yor lah dôl ƀư nâm nđĕ khân may mâu mra tŭp ôh,$b$,false),
('bunong-vn','2PE',1,11,null,$b$pô ri yơh khân may mra lăp ma nau nơih pơih tâm ƀon bri hađăch n'ho ro Yêsu Krist, Kôranh Brah jêh ri nơm tâm rklaih he.$b$,false),
('bunong-vn','2PE',1,12,null,$b$Yor nĕ tơ lah may gĭt jêh lĕ nau aơ jêh ri gŭ nâp jêh tâm nau nanê̆ aơ kđôi, ăt gâp kah gĭt ƀa ƀơ đŏng, lĕ nau ma khân may.$b$,true),
('bunong-vn','2PE',1,13,null,$b$Ƀiă lah dôl gâp gŭ tâm ngih njưh aơ, gâp uănh nau gâp mbơh gay ma rlay khân may jêng kan di ma gâp,$b$,false),
('bunong-vn','2PE',1,14,null,$b$yor lah gâp gĭt, gâp mra du gơnh bơh ngih njưh aơ, nâm bu Kôranh Brah he, Yêsu Krist, mbơh jêh ma gâp.$b$,false),
('bunong-vn','2PE',1,15,null,$b$Ƀiă lah gâp mra njrăng gay ma lah jêh gâp du, khân may dơi kah gĭt ƀa ƀơ ma lĕ nau aơ.$b$,false),
('bunong-vn','2PE',1,16,null,$b$Yor lah hên ăn khân may gĭt nau brah Kôranh Brah he, Yêsu Krist, jêh ri nau păng văch, mâu di nâm bu nau ngơi hôr ndơm, ƀiă lah tĭng nâm, hên saơ jêh nau chrêk rmah păng ma măt hên nơm.$b$,true),
('bunong-vn','2PE',1,17,null,$b$Yor lah păng sŏk dơn jêh nau yơk jêh ri nau chrêk rmah bơh mbơ̆ păng, Brah Ndu, tơ lah bu tăng bâr ma nau chrêk rmah brah ngăn lah nâm pô aơ: “Păng aơ yơh Kon rŏng ngăn ngên. Tâm Păng gâp geh lĕ nau maak.”$b$,false),
('bunong-vn','2PE',1,18,null,$b$Jêh ri hên tăng jêh bâr aơ bơh trôk dôl hên gŭ ndrel ma Păng ta klơ yôk kloh ueh.$b$,true),
('bunong-vn','2PE',1,19,null,$b$Jêh ri hên geh nau phung kôranh nơm mbơh lor ngơi rah vah lơn. Njrăng hom ăn ueh ma nau nĕ nâm bu ŭnh kđen sol tâm ntŭk ngo tât ang ôi jêh ri mbing luh tâm nuih n'hâm khân may.$b$,true),
('bunong-vn','2PE',1,20,null,$b$Lor lơn khân may gĭt jêh mâu geh du ntil nau mbơh lor tâm nau nchih geh nau rblang tĭng nâm nau mĭn êng,$b$,false),
('bunong-vn','2PE',1,21,null,$b$yor lah mâu mâp geh du ntil nau mbơh lor luh tă bơh bunuyh ŭch, ƀiă lah Brah Huêng Ueh nchâp bunuyh ngơi nau luh bơh Brah Ndu.$b$,false),
('bunong-vn','2PE',2,1,null,$b$Geh jêh tâm phung ƀon lan phung kôranh nơm mbơh lor tih, jêh ri mra geh lĕ phung kôranh nơm nti tih tâm phung khân may. Khân păng mra ntŭng nkoch mbơh nau nti dơi ƀư rai. Khân păng dun ma nơm tâm chuai khân păng jêh ri khân păng rgum ma khân păng nơm nau ƀư rai gơnh.$b$,true),
('bunong-vn','2PE',2,2,null,$b$Âk bunuyh mra tĭng trong nau tih khân păng jêh ri yor khân păng yơh bu mra ngơi mhĭk ma trong nau ngăn ngên.$b$,false),
('bunong-vn','2PE',2,3,null,$b$Tâm nau kơnh ir khân păng mra ngơi ndơm gay ma sa drăp khân may, ƀiă lah nau phat dôih ma khân păng thăm bơh jŏ jêh, jêh ri nau rai lôch khân păng mâu blau dŭt ôh.$b$,false),
('bunong-vn','2PE',2,4,null,$b$Yor lah tơ lah Brah Ndu mâu nhhuach ma phung Tông mpăr ueh ƀư tih, ƀiă lah klŭp lơi khân păng tâm brŏng jru ntŭk ngo ngăn, gay krŭng prăp khân păng ma nau phat dôih;$b$,true),
('bunong-vn','2PE',2,5,null,$b$tơ lah păng mâu nhhuach ma neh ntu ơm, ƀiă lah ăn dak lip tâm rmal neh ntu phung tih jêh ri tâm rklaih knŏng Y-Nôê, du huê nơm nti sŏng, ndrel ma pơh nuyh êng;$b$,false),
('bunong-vn','2PE',2,6,null,$b$tơ lah păng tâm rmal ƀon Sôdôm jêh ri ƀon Gômôrơ ƀư rai khân păng tât jêng ŭnh buh gay ma geh nau tâm ntĭt ma phung tih kăndơ̆ ;$b$,false),
('bunong-vn','2PE',2,7,null,$b$jêh ri tơ lah păng tâm rklaih Y-Lot, nơm sŏng nơm rngot ngăn ma nau gŭ ngao krao sach mhĭk phung tih ƀai nĕ.$b$,false),
('bunong-vn','2PE',2,8,null,$b$Yor lah bunuyh sŏng aơ gŭ ta nklang khân păng, ăp nar tăng jêh ri saơ kan tih khân păng ƀư ji huêng sŏng păng.$b$,false),
('bunong-vn','2PE',2,9,null,$b$Yor Kôranh Brah blau tâm rklaih phung yơk ma Brah Ndu bơh nau rlong uănh, jêh ri păng prăp phung kue ma nau tâm rmal ta nar phat dôih.$b$,true),
('bunong-vn','2PE',2,10,null,$b$Rplay ngăn ma phung tĭng nau nglay săk ŭch ƀơ̆ ƀơch jêh ri rmot ma phung kôranh chiă uănh. Phung nĕ janh jêh ri sưr, khân păng mâu klach ôh suai rak ma phung toyh.$b$,false),
('bunong-vn','2PE',2,11,null,$b$Ƀiă lah phung Tông mpăr ueh phung ktang brah lơn mâu geh phat dôih ma nau suai rak ma phung toyh nĕ ôh ta năp Kôranh Brah.$b$,false),
('bunong-vn','2PE',2,12,null,$b$Bi phung tĭng nau nglay săk ŭch jêng nâm bu mpô mpa, mâu gĭt rbăng. Bu deh ma khân păng prăp ma bu nhŭp jêh ri ăn rai. Khân păng vay mưch ma nau khân păng mâu gĭt rbăng, jêh ri khân păng mra rai yot ma nau ƀơ̆ ƀơch khân păng.$b$,false),
('bunong-vn','2PE',2,13,null,$b$Pô ri khân păng sŏk dơn rnoh nkhôm ma nau tih khân păng. Khân păng uănh nau ƀư tih dôl nar jêng nau maak; khân păng jêng ndơ ƀơ̆ ƀơch. Khân păng rŏng ngăn ma nau khân păng ndơm dôl gŭ sông sa ndrel ma khân may.$b$,false),
('bunong-vn','2PE',2,14,null,$b$Măt khân păng bêng ma nau kơnh jêh ri khân păng ƀư tih mâu blau dĭl ôh. Khân păng ndơm phung mâu nâp, khân păng geh nuih n'hâm mơng kơnh. Khân păng jêng phung kon nau rtăp rak!$b$,true),
('bunong-vn','2PE',2,15,null,$b$Jêh khân păng cha lơi trong sŏng khân păng nhhơt bri tĭng trong Y-Balam kon Y-Bôsôr, nơm rŏng rnoh nkhôm ma nau tih,$b$,false),
('bunong-vn','2PE',2,16,null,$b$ƀiă lah păng geh nau nduyh jêh ma nau tih păng, du mlâm seh bri me mlo ngơi nâm bu du huê bunuyh buay nau rluk du huê nơm mbơh lor nĕ.$b$,false),
('bunong-vn','2PE',2,17,null,$b$Phung nĕ jêng nâm bu ntu dak sơh nâm bu tơm sial phŭt vănh ngo rvêt, krăk kher prăp ma khân păng.$b$,true),
('bunong-vn','2PE',2,18,null,$b$Khân păng dŏng nau ngơi bêng ma nau sưr. Ma nau nglay săk kơnh ƀơ̆ ƀơch khân păng ndơm phung mhe luh bơh phung tĭng trong tih.$b$,false),
('bunong-vn','2PE',2,19,null,$b$Khân păng ton nau kon me ma bu dôl khân păng nơm jêng dĭk ma nau rai yot; yor lah ăp nơm jêng dĭk ma nơm dơi jêh đah păng.$b$,false),
('bunong-vn','2PE',2,20,null,$b$Pô ri yơh jêh bu luh tă bơh nau ƀơ̆ ƀơch neh ntu ma nau păng gĭt năl Kôranh Brah jêh ri Brah Krist, Nơm Tâm Rklaih, tơ lah păng lăp jêh ri nau ƀơ̆ ƀơch dơi đah păng, nau păng jêng tâm kăndơ̆ mra mhĭk lơn tal lor.$b$,true),
('bunong-vn','2PE',2,21,null,$b$Yor lah ueh lơn khân păng mâu gĭt trong nau sŏng, ma jêh khân păng gĭt jêh ri vĭ vĭr bơh nau vay kloh ueh ăn jêh ma khân păng.$b$,false),
('bunong-vn','2PE',2,22,null,$b$Tât jêh ma khân păng di nâm bu nau hôr nâm pô aơ, “So plơ̆ sa mpa păng hŏ hok jêh,” jêh ri “Sŭr me hŏ nđŭm jêh pung tay tâm dak rhang.”$b$,false),
('bunong-vn','2PE',3,1,null,$b$Hơi phung gâp rŏng, aơ sămƀŭt tơ̆ bar gâp nchih ma khân may, tâm sămƀŭt aơ jêh ri sămƀŭt lor gâp joi ŭch rlay an nau mĭn sŏng khân may ăn kah gĭt;$b$,true),
('bunong-vn','2PE',3,2,null,$b$gay ma khân may kah gĭt ma nau phung kôranh nơm mbơh lor kloh ueh mbơh jêh, he ntăm an phung kôranh oh mon ma khân may nti.$b$,false),
('bunong-vn','2PE',3,3,null,$b$Lor lơn khân may gĭt jêh tâm rnôk lôch dŭt, geh ƀa ƀă phung mưch mra văch ma nau khân păng ngơi bir ngơi srơh, ƀư tĭng nâm nau khân păng nơm kơnh.$b$,true),
('bunong-vn','2PE',3,4,null,$b$Khân păng lah: “Hŏ nau ton ma nau păng plơ̆ văch? Yor lah bơh rnôk phung u che he khĭt jêh lĕ rngôch ndơ ăt jêng nâm bu rnôk ntơm nau rhăk.”$b$,false),
('bunong-vn','2PE',3,5,null,$b$Khân păng ŭch chuêl lơi ntơm sa ơm ma nau Brah Ndu ngơi geh trôk jêh ri neh ntu luh tă bơh dak jêh ri njêng tâm dak.$b$,false),
('bunong-vn','2PE',3,6,null,$b$Ma nau nĕ neh ntu rai jêh lĕ ma nau dak lip.$b$,false),
('bunong-vn','2PE',3,7,null,$b$Pô ri ma nau ngơi nĕ lĕ trôk jêh ri neh aƀaơ aơ hôm jêh ri prăp ma ŭnh ta nar phat dôih jêh ri nau ƀư rai lôch phung tih mhĭk.$b$,false),
('bunong-vn','2PE',3,8,null,$b$Ƀiă lah, hơi phung gâp rŏng, lơi ta khân may chuêl ôh ma nau aơ, ta năp Kôranh Brah du nar jêng nâm bu du rbăn năm, jêh ri du rbăn năm jêng nâm bu du nar.$b$,false),
('bunong-vn','2PE',3,9,null,$b$Yor lah Kôranh Brah mâu hôm njong ôh, ăn nanê̆ nau păng ton tĭng nâm ƀa ƀă mĭn, ƀiă lah păng srôih đah khân may, mâu ŭch ôh du huê roh, ƀiă lah ŭch ma lĕ rngôch mra tât ma nau tâm rmal nau tih.$b$,false),
('bunong-vn','2PE',3,10,null,$b$Nar Kôranh Brah mra tât nâm bu bunuyh ntŭng, dôl nĕ trôk mra rlau lôch ma âk nteh huy ktang, jêh ri mpa tâm trôk ŭnh mra sa tât lêk, jêh ri neh ntu nđâp kan păng ŭnh mra sa lĕ.$b$,false),
('bunong-vn','2PE',3,11,null,$b$Yor lah lĕ rngôch ndơ nĕ mra rai lôch, pô ri ueh lơn khân may jêng bunuyh kloh ueh tâm nau khân may gŭ ngao krao sach jêh ri tâm nau yơk mbah ma Brah Ndu.$b$,true),
('bunong-vn','2PE',3,12,null,$b$Dôl gŭ kâp rmiăng nar Brah Ndu gơnh tât. Nar nĕ ŭnh sa trôk tât rai jêh ri lĕ rngôch ndơ dŭm duh tât lêk,$b$,true),
('bunong-vn','2PE',3,13,null,$b$ƀiă lah he gŭ kâp, tĭng nâm nau păng ton, trôk mhe jêh ri neh ntu mhe, ta nĕ yơh ntŭk nau sŏng gŭ.$b$,false),
('bunong-vn','2PE',3,14,null,$b$Hơi phung gâp rŏng, yor nĕ dôl gŭ kâp nau nĕ, ăn khân may njrăng ma lĕ nuih n'hâm gay ma păng saơ khân may gŭ tâm nau đăp mpăn, mâu geh nau ƀơ̆ mâu lah nau dơi nduyh khân may ôh.$b$,true),
('bunong-vn','2PE',3,15,null,$b$Ăn khân may chroh ma nau Kôranh Brah srôih jêng nau tâm rklaih khân may, nâm bu Y-Pôl, nâu he rŏng ngăn ngên, nchih jêh ma khân may tĭng nâm nau blau mĭn ăn jêh ma păng.$b$,false),
('bunong-vn','2PE',3,16,null,$b$Tâm lĕ rngôch sămƀŭt păng ngơi ma nau nĕ tâm ban lĕ, jêh ri geh ƀa ƀă nau jêr gĭt rbăng, jêh ri phung rluk phung chroh mâu nâp rjăp rblang tih, tâm ban ma khân păng ƀư ma nau nchih êng jêng nau ƀư roh khân păng nơm.$b$,true),
('bunong-vn','2PE',3,17,null,$b$Hơi phung gâp rŏng, yor lah khân may gĭt jêh lor, ăn khân may njrăng hom, klach lah phung tih mhĭk nĕ mra njŭn leo khân may tâm nau khân păng vĭ, jêh ri khân may roh nau nâp khân may.$b$,false),
('bunong-vn','2PE',3,18,null,$b$Ƀiă lah ăn khân may văch ma toyh tâm nau yô̆ jêh ri nau gĭt năl Kôranh Brah, Yêsu Krist, Nơm Tâm Rklaih he, ma Păng yơh nau chrêk rmah aƀaơ n'ho ma kăndơ̆ ƀa ƀơ n'ho ro. Amen.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','2PE',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','2PE',1,3,1,'heading',$b$Nau Phung Chroh Văch Ma Toyh$b$),
('bunong-vn','2PE',1,12,2,'heading',$b$Phung Oh Mon Jêh Ri Phung Kôranh Nơm Mbơh Lor Geh Nau Dơi$b$),
('bunong-vn','2PE',2,1,0,'heading',$b$Phung Kôranh Nơm Nti Tih$b$),
('bunong-vn','2PE',3,1,0,'heading',$b$Nau Kôranh Brah Plơ̆ Văch$b$),
('bunong-vn','2PE',3,3,1,'heading',$b$jêh ri nau Kôranh Brah Nơm Tâm Rklaih$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '1JN', $b$I Y-Yôhan$b$, $b$["Sămƀŭt Tal Nguay Tĭng Nâm", "Y-YÔHAN"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','1JN',1,1,null,$b$Nau geh bơh ntơm sa ơm, nau nĕ hên tăng jêh, nau nĕ măt hên saơ jêh, nau nĕ hên uănh jêh, jêh ri ti hên pah bi jêh ma nau ngơi rêh,$b$,true),
('bunong-vn','1JN',1,2,null,$b$nau rêh tâm mpơl jêh. Hên saơ jêh nau rêh jêh ri jêng phung mbơh ma păng, jêh ri nkoch bri ma khân may nau rêh n'ho ro. Păng gŭ ndrel ma Brah Mbơ̆ jêh, jêh ri bu mpơl jêh păng ma hên,$b$,false),
('bunong-vn','1JN',1,3,null,$b$nau nĕ hên saơ jêh ri tăng jêh, jêh ri mbơh ma khân may, gay ma khân may dơi geh nau tâm rnglăp tâm ban lĕ đah hên, jêh ri he geh nau tâm rnglăp đah Brah Mbơ̆ , jêh ri đah Kon Păng, Yêsu Krist.$b$,false),
('bunong-vn','1JN',1,4,null,$b$Jêh ri hên nchih nau aơ gay ma nau maak he dơi jêng rah vah.$b$,false),
('bunong-vn','1JN',1,5,null,$b$Pô aơ nau mhe hên tăng jêh bơh păng jêh ri mbơh ma khân may, Brah Ndu jêng nau ang, jêh ri tâm păng mâu geh nau ngo ôh.$b$,true),
('bunong-vn','1JN',1,6,null,$b$Tơ lah he lah, he tâm rnglăp đah păng dôl he hăn tâm nau ngo, pô ri jêng he mƀruh jêh ri mâu ƀư tĭng nâm nau nanê̆ ôh.$b$,false),
('bunong-vn','1JN',1,7,null,$b$Ƀiă lah tơ lah he hăn tâm nau ang nâm bu păng gŭ tâm nau ang, he geh nau tâm rnglăp ndrăng he, jêh ri mham Brah Yêsu, Kon Păng, ƀư kloh he bơh lĕ rngôch nau tih.$b$,false),
('bunong-vn','1JN',1,8,null,$b$Tơ lah he lah, he mâu geh nau tih ôh, he ndơm he nơm yơh jêh ri nau nanê̆ mâu gŭ tâm he ôh$b$,true),
('bunong-vn','1JN',1,9,null,$b$Tơ lah he mbơh nau tih he, Păng nơm răp jăp jêh ri sŏng ŭch yô̆ an nau tih he jêh ri ƀư kloh he bơh lĕ rngôch nau kue.$b$,false),
('bunong-vn','1JN',1,10,null,$b$Tơ lah he lah, he mâu mâp ƀư tih, he ngơi mƀruh Păng jêh ri nau Păng ngơi mâu gŭ tâm he ôh.$b$,false),
('bunong-vn','1JN',2,1,null,$b$Hơi phung kon jê̆ gâp, gâp nchih nau aơ ma khân may gay ma lơi ăn khân may ƀư tih ôh; ƀiă lah tơ lah bu ƀư tih, he geh du huê Nơm king, Yêsu Krist, Nơm sŏng ta năp Brah Mbơ̆ .$b$,true),
('bunong-vn','1JN',2,2,null,$b$Păng nơm jêng ndơ ƀư brah yor nau tih he, jêh ri mâu di knŏng ma nau tih he ôh, ƀiă lah nđâp ma nau tih lĕ neh ntu.$b$,false),
('bunong-vn','1JN',2,3,null,$b$Tơ lah he tông nau Păng ntăm, ma nau nĕ yơh he gĭt he nơm gĭt năl Păng jêh.$b$,true),
('bunong-vn','1JN',2,4,null,$b$Mbu nơm lah: “Gâp gĭt năl păng jêh”, jêh ri mâu tông ôh nau Păng ntăm, bunuyh nĕ jêng du huê mƀruh, jêh ri nau nanê̆ mâu gŭ tâm Păng ôh.$b$,true),
('bunong-vn','1JN',2,5,null,$b$Ƀiă lah mbu nơm tông nau Păng ngơi, nau Brah Ndu rŏng jêng rah vah ngăn tâm Păng. Ma nau nĕ yơh he gĭt he gŭ tâm Păng.$b$,false),
('bunong-vn','1JN',2,6,null,$b$Mbu nơm lah, Păng gŭ tâm Brah Yêsu mra hăn tâm ban ma Brah Yêsu lĕ.$b$,false),
('bunong-vn','1JN',2,7,null,$b$Hơi phung gâp rŏng, mâu geh nau ntăm mhe ôh gâp nchih ma khân may ƀiă lah nau ntăm ơm khân may geh jêh ntơm bơh kăl e; nau ntăm ơm nĕ jêng nau ngơi khân may tăng jêh.$b$,true),
('bunong-vn','1JN',2,8,null,$b$Ƀiă lah nau ntăm ơm ăt gâp nchih jêh ma khân may jêng nau nanê̆ tâm Păng jêh ri tâm khân may, yor lah nau ngo hŏ ntơm du jêh, jêh ri nau ang ngăn ntơm sol jêh.$b$,false),
('bunong-vn','1JN',2,9,null,$b$Mbu nơm lah păng gŭ tâm nau ang, ƀiă lah păng tâm rmot ma oh nâu păng, păng ăt gŭ tâm nau ngo yơh.$b$,false),
('bunong-vn','1JN',2,10,null,$b$Mbu nơm rŏng ma oh nâu, păng gŭ tâm nau ang jêh ri tâm nau nĕ mâu geh nau chêh ôh.$b$,false),
('bunong-vn','1JN',2,11,null,$b$Ƀiă lah mbu nơm tâm rmot ma oh nâu, păng gŭ tâm nau ngo, hăn tâm nau ngo, jêh ri mâu gĭt ôh mbah ntŭk păng hăn yor lah nau ngo ƀư chieh jêh măt păng.$b$,false),
('bunong-vn','1JN',2,12,null,$b$Hơi phung kon jê̆, gâp nchih ma khân may yor nau tih khân may yô̆ an jêh yor amoh Păng.$b$,true),
('bunong-vn','1JN',2,13,null,$b$Hơi phung mbơ̆ , gâp nchih ma khân may yor khân may năl jêh nơm jêng sa ơm lor lơn. Hơi phung druh ndăm gâp nchih ma khân may yor khân may dơi jêh đah nơm mhĭk. Hơi phung kon jê̆, gâp nchih ma khân may yor lah khân may gĭt năl jêh Mbơ̆ .$b$,false),
('bunong-vn','1JN',2,14,null,$b$Hơi phung mbơ̆ , gâp nchih ma khân may gĭt năl jêh Nơm jêng sa ơm lor lơn, hơi phung druh ndăm gâp nchih ma khân may yor lah khân may jêng ktang jêh ri Nau Brah Ndu Ngơi gŭ tâm khân may jêh ri khân may dơi jêh đah nơm mhĭk.$b$,false),
('bunong-vn','1JN',2,15,null,$b$Lơi rŏng ma neh ntu ôh, mâu lĕ rŏng ma ndơ neh ntu. Tơ lah du huê rŏng ma neh ntu nau Mbơ̆ rŏng mâu gŭ tâm păng ôh.$b$,true),
('bunong-vn','1JN',2,16,null,$b$Yor lah lĕ ndơ tâm neh ntu, nâm bu nglay săk kơnh nau măt kơnh jêh ri nau sưr tâm nau rêh, mâu geh luh tă bơh Mbơ̆ ôh, ƀiă lah bơh neh ntu.$b$,false),
('bunong-vn','1JN',2,17,null,$b$Jêh ri neh ntu rlau lôch jêh ri nau păng kơnh tâm ban lĕ, ƀiă lah mbu nơm ƀư nau Brah Ndu ŭch gŭ rêh ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','1JN',2,18,null,$b$Hơi phung kon jê̆, aơ jêng mông nglĕ dŭt; jêh ri nâm bu khân may hŏ tăng jêh ma nơm rlăng ma Brah Krist văch, aƀaơ geh âk jêh nơm rlăng đah Brah Krist; ma nau nĕ he dơi gĭt mông lôch dŭt tât jêh.$b$,true),
('bunong-vn','1JN',2,19,null,$b$Khân păng du luh jêh tă bơh nklang phung he, ƀiă lah khân păng mâu jêng phung he ôh; yor lah tơ lah khân păng jêng phung he, khân păng mra gŭ ndrel ma he; ƀiă lah nau nĕ tât jêh gay tâm mpơl ma lĕ rngôch ma khân păng mâu jêng phung he ôh.$b$,false),
('bunong-vn','1JN',2,20,null,$b$Khân may sŏk dơn jêh nau troch dak ngi tă bơh Nơm Kloh Ueh, jêh ri lĕ rngôch khân may geh jêh nau gĭt rbăng.$b$,true),
('bunong-vn','1JN',2,21,null,$b$Gâp nchih ma khân may mâu di yor lah khân may mâu gĭt nau nanê̆ ôh, ƀiă lah yor khân may gĭt nanê̆, jêh ri yor lah mâu geh ôh du ntil nau mƀruh tă bơh nau nanê̆,$b$,false),
('bunong-vn','1JN',2,22,null,$b$mbu jêng bunuyh mƀruh? Mâu di hĕ nơm dun Brah Yêsu jêng Brah Krist, nơm nĕ yơh jêng nơm rlăng đah Brah Krist, nơm dun kon jêh ri dun Mbơ̆ .$b$,false),
('bunong-vn','1JN',2,23,null,$b$Mbu nơm dun kon, mâu lĕ geh Mbơ̆ . Mbu nơm mbơh sŏk dơn kon, geh lĕ Mbơ̆ .$b$,false),
('bunong-vn','1JN',2,24,null,$b$Ăn lĕ nau khân may tăng jêh bơh sa ơm ntơm gŭ tâm khân may. Tơ lah nau khân may tăng jêh bơh sa ơm ntơm gŭ tâm khân may, khân may gŭ tâm kon jêh ri tâm Mbơ̆ tâm ban lĕ.$b$,false),
('bunong-vn','1JN',2,25,null,$b$Jêh ri nau păng ton ăn jêh ma he jêng nau rêh n'ho ro.$b$,false),
('bunong-vn','1JN',2,26,null,$b$Gâp nchih nau aơ ma khân may yor phung ŭch ndơm khân may;$b$,true),
('bunong-vn','1JN',2,27,null,$b$ƀiă lah nau troch dak ngi khân may sŏk dơn jêh bơh Păng gŭ tâm khân may, jêh ri khân may mâu ŭch ôh bu mra nti ma khân may tâm ban ma nau Păng troch dak ngi nti ma khân may lĕ rngôch nau jêh ri jêng nau nanê̆, jêh ri mâu jêng nau mƀruh ôh, tĭng nâm Păng nti ma khân may gŭ hom tâm Păng.$b$,false),
('bunong-vn','1JN',2,28,null,$b$Jêh ri aƀaơ, hơi phung kon jê̆, gŭ hom tâm Păng, gay nôk Păng mpơl he dơi geh nau nănh, mâu prêng ta năp măt Păng dôl Păng tât.$b$,true),
('bunong-vn','1JN',2,29,null,$b$Tơ lah khân may gĭt Păng jêng sŏng, khân may gĭt ngăn ma mbu nơm ƀư nau sŏng geh nau deh tă bơh Păng jêh.$b$,false),
('bunong-vn','1JN',3,1,null,$b$Uănh hom moh nau rŏng Brah Mbơ̆ tâm mpơl jêh ma he gay ma rnha he kon Brah Ndu; pô ri he jêng jêh. Yor nĕ neh ntu mâu gĭt năl he yor lah păng mâu mâp gĭt năl Brah Ndu ôh.$b$,true),
('bunong-vn','1JN',3,2,null,$b$Hơi phung gâp rŏng, aƀaơ he jêng kon Brah Ndu; jêh ri moh nau he mra jêng ê tâm mpơl ôh, ƀiă lah he gĭt tơ lah păng tâm mpơl, he mra jêng nâm bu păng, yor lah he mra saơ păng nâm bu păng jêng.$b$,false),
('bunong-vn','1JN',3,3,null,$b$Mbu nơm geh nau kâp gân aơ tâm păng ƀư kloh păng nơm nâm bu Brah Ndu nơm jêng kloh.$b$,false),
('bunong-vn','1JN',3,4,null,$b$Mbu nơm ƀư tih, rlau nau vay; jêh ri nau tih jêng nau gao nau vay.$b$,true),
('bunong-vn','1JN',3,5,null,$b$Khân may gĭt Brah Yêsu tâm mpơl jêh gay sŏk lơi nau tih jêh ri tâm păng mâu geh nau tih ôh.$b$,false),
('bunong-vn','1JN',3,6,null,$b$Mbu nơm gŭ tâm păng mâu ƀư tih ôh; mbu nơm ƀư tih mâu mâp saơ păng ôh jêh ri mâu gĭt năl păng ôh.$b$,false),
('bunong-vn','1JN',3,7,null,$b$Hơi phung kon jê̆, lơi ăn bu ndơm khân may ôh. Mbu nơm ƀư nau sŏng jêng sŏng nơm bu Brah Ndu nơm jêng sŏng.$b$,true),
('bunong-vn','1JN',3,8,null,$b$Mbu nơm ƀư tih luh tă bơh brah mhĭk; yor lah brah mhĭk ƀư tih ntơm bơh sa ơm. Kon Brah Ndu tâm mpơl jêh gay ƀư rai kan brah mhĭk.$b$,false),
('bunong-vn','1JN',3,9,null,$b$Mbu nơm deh tă bơh Brah Ndu, mâu ƀư tih ôh; yor ntil găr Brah Ndu gŭ tâm păng, jêh ri păng mâu ƀư tih tay đŏng ôh yor lah păng deh tă bơh Brah Ndu.$b$,false),
('bunong-vn','1JN',3,10,null,$b$Ma nau nĕ bu dơi gĭt năl phung kon Brah Ndu jêh ri phung kon brah mhĭk; mbu nơm mâu ƀư nau sŏng mâu luh tă bơh Brah Ndu ôh, mâu lĕ ma nơm mâu rŏng ma oh nâu păng.$b$,false),
('bunong-vn','1JN',3,11,null,$b$Yor lah nau aơ jêng nau Brah Mbơh khân may tăng jêh bơh sa ơm ntơm ăn he tâm rŏng ndrăng he,$b$,true),
('bunong-vn','1JN',3,12,null,$b$jêh ri lơi jêng nâm bu Y-Kain ôh, nơm luh tă bơh Brah mhĭk jêh ri nkhĭt lơi oh nơm. Jêh ri mâm ƀư păng nkhĭt ô băl? Yor lah kan păng mhĭk jêh ri kan oh păng jêng sŏng.$b$,false),
('bunong-vn','1JN',3,13,null,$b$Hơi phung oh nâu, lơi ta hih rhâl ôh tơ lah neh ntu tâm rmot ma khân may.$b$,false),
('bunong-vn','1JN',3,14,null,$b$He gĭt he hŏ rgăn jêh bơh nau khĭt hăn tâm nau rêh yor lah he rŏng ma phung oh nâu. Mbu nơm mâu blau tâm rŏng gŭ tâm nau khĭt.$b$,false),
('bunong-vn','1JN',3,15,null,$b$Mbu nơm tâm rmot ma phung oh nâu păng jêng bunuyh tâm nkhĭt bunuyh, jêh ri khân may gĭt mâu geh ôh du huê nkhĭt bunuyh geh nau rêh n'ho ro gŭ tâm păng.$b$,false),
('bunong-vn','1JN',3,16,null,$b$He gĭt năl jêh nau rŏng tâm nau păng ăn jêh nau rêh păng yor he, jêh ri he tâm ban lĕ mra ăn nau rêh he ma phung oh nâu.$b$,false),
('bunong-vn','1JN',3,17,null,$b$Tơ lah du huê geh drăp neh ntu aơ, jêh ri păng saơ oh nâu păng gŭ tâm nau pưt kƀah ƀiă lah dun kơl ô băl nĕ, mâm ƀư nau Brah Ndu rŏng dơi gŭ tâm păng?$b$,false),
('bunong-vn','1JN',3,18,null,$b$Hơi phung kon jê̆, lơi he rŏng tâm nau ngơi ta mpiăt ôh, ƀiă lah tâm nau ƀư jêh ri ma nau nanê̆.$b$,true),
('bunong-vn','1JN',3,19,null,$b$Ma nau nĕ he gĭt năl ma he luh tă bơh nau nanê̆, jêh ri he geh nau rnơm tâm nuih n'hâm he ta năp păng.$b$,false),
('bunong-vn','1JN',3,20,null,$b$Tơ lah nuih n'hâm he nduyh he, Brah Ndu jêng toyh lơn ma nuih n'hâm he jêh ri păng gĭt lĕ rngôch ndơ.$b$,false),
('bunong-vn','1JN',3,21,null,$b$Hơi phung gâp rŏng, tơ lah nuih n'hâm he mâu nduyh he ôh, he geh nuih n'hâm brât hăn ta năp Brah Ndu,$b$,false),
('bunong-vn','1JN',3,22,null,$b$jêh ri he sŏk dơn tă bơh păng moh ndơ he dăn, yor he tông ma nau păng ntăm, jêh ri ƀư nau maak ma păng.$b$,false),
('bunong-vn','1JN',3,23,null,$b$Jêh ri aơ nau păng ntăm: Ăn he chroh ma amoh Kon Păng, Yêsu Krist jêh ri ăn he tâm rŏng ndrăng he tĭng nâm nau păng ntăm jêh ma he.$b$,false),
('bunong-vn','1JN',3,24,null,$b$Mbu nơm tông nau păng ntăm gŭ tâm Brah Ndu jêh ri Brah Ndu gŭ tâm păng. Jêh ri he gĭt năl păng gŭ tâm he ma Brah Huêng Ueh, Păng ăn jêh ma he.$b$,false),
('bunong-vn','1JN',4,1,null,$b$Hơi phung gâp rŏng, lơi chroh ôh ma lĕ brah êng, ƀiă lah lŏng nâl uănh huêng brah nây, gĭt lah tă Brah Ndu; yor lah geh âk kôranh nơm mbơh lor tih văch jêh tâm neh ntu.$b$,true),
('bunong-vn','1JN',4,2,null,$b$Ma nau aơ khân may dơi gĭt Brah Huêng Ueh Brah Ndu; lĕ rngôch brah mbơh Yêsu Krist văch jêh tâm nglay săk luh bơh Brah Ndu,$b$,false),
('bunong-vn','1JN',4,3,null,$b$jêh ri lĕ rngôch brah mâu mbơh Brah Yêsu mâu di luh bơh Brah Ndu ôh. Păng nĕ jêng rlăng đah Brah Krist. Khân may tăng jêh păng mra văch, jêh ri aƀaơ păng gŭ jêh tâm neh ntu.$b$,false),
('bunong-vn','1JN',4,4,null,$b$Hơi phung kon jê̆ khân may luh bơh Brah Ndu jêh ri dơi đah khân păng jêh, yor lah nơm gŭ tâm khân may jêng toyh lơn ma nơm gŭ tâm neh ntu.$b$,true),
('bunong-vn','1JN',4,5,null,$b$Khân păng luh bơh neh ntu, pô ri khân păng ngơi nâm bu neh ntu, jêh ri neh ntu gŭ iăt khân păng.$b$,false),
('bunong-vn','1JN',4,6,null,$b$He luh bơh Brah Ndu. Mbu nơm gĭt năl Brah Ndu gŭ iăt nau he, jêh ri mbu nơm mâu luh bơh Brah Ndu mâu iăt nau he ôh. Ma nau nĕ he gĭt năl brah nau nanê̆, jêh ri brah nau vĭ.$b$,true),
('bunong-vn','1JN',4,7,null,$b$Hơi phung gâp rŏng, ăn he tâm rŏng ndrăng he, yor lah nau rŏng luh bơh Brah Ndu, jêh ri mbu nơm rŏng deh jêh bơh Brah Ndu, jêh ri gĭt năl Brah Ndu.$b$,true),
('bunong-vn','1JN',4,8,null,$b$Mbu nơm mâu blau tâm rŏng mâu mâp gĭt năl Brah Ndu ôh, yor lah Brah Ndu jêng nau rŏng.$b$,false),
('bunong-vn','1JN',4,9,null,$b$Nau Brah Ndu rŏng tâm mpơl jêh ma he tâm nau Brah Ndu njuăl jêh kon păng, geh knŏng du huê, tâm neh ntu gay ma he gŭ rêh yor păng.$b$,true),
('bunong-vn','1JN',4,10,null,$b$Tâm nau aơ jêng nau rŏng mâu di he rŏng jêh ma Brah Ndu ôh, ƀiă lah Brah Ndu rŏng jêh ma he, jêh ri njuăl kon păng văch nâm bu ndơ ƀư brah ƀư kloh nau tih he.$b$,false),
('bunong-vn','1JN',4,11,null,$b$Hơi phung gâp rŏng, tơ lah Brah Ndu rŏng jêh ma he, pô ri, ăn he tâm rŏng lĕ ndrăng he.$b$,true),
('bunong-vn','1JN',4,12,null,$b$Mâu geh du huê bunuyh mâp saơ Brah Ndu ôh; tơ lah he tâm rŏng ndrăng he, Brah Ndu gŭ tâm he jêh ri nau păng jêng rah vah tâm he.$b$,false),
('bunong-vn','1JN',4,13,null,$b$He gĭt năl he gŭ tâm păng jêh ri păng tâm he yor lah păng ăn jêh Brah Huêng Ueh păng ma he.$b$,false),
('bunong-vn','1JN',4,14,null,$b$Jêh ri he saơ jêh ri mbơh Brah Mbơ̆ njuăl văch jêh kon păng jêng nâm bu nơm tâm rklaih ma neh ntu.$b$,true),
('bunong-vn','1JN',4,15,null,$b$Mbu nơm mbơh Brah Yêsu jêng kon Brah Ndu, Brah Ndu gŭ tâm păng, jêh ri păng tâm Brah Ndu.$b$,false),
('bunong-vn','1JN',4,16,null,$b$Pô ri he gĭt jêh ri chroh ma Brah Ndu geh nau rŏng ma he. Brah Ndu jêng nau rŏng. Mbu nơm gŭ tâm nau rŏng jêng păng gŭ tâm Brah Ndu, jêh ri Brah Ndu gŭ tâm păng.$b$,false),
('bunong-vn','1JN',4,17,null,$b$Nâm bu păng jêng, he jêng tâm ban lĕ tâm neh ntu aơ. Yor nau nĕ yơh nau rŏng jêng rah vah tâm he, gay ma he geh nau rnơm ta nar phat dôih.$b$,true),
('bunong-vn','1JN',4,18,null,$b$Nau klach mâu gŭ ôh tâm nau rŏng, ƀiă lah nau rŏng rah vah mprơh lơi nau klach, yor lah nau klach mĭn ma nau tâm rmal, jêh ri mbu nơm klach mâu jêng rah vah ôh tâm nau rŏng.$b$,false),
('bunong-vn','1JN',4,19,null,$b$He rŏng ma păng yor lah păng rŏng jêh ma he lor.$b$,false),
('bunong-vn','1JN',4,20,null,$b$Tơ lah du huê lah: “Gâp rŏng ma Brah Ndu”, ƀiă lah tâm rmot ma oh nâu păng, păng jêng du huê bunuyh mƀruh yơh; yor lah mbu nơm mâu rŏng ma oh nâu, nơm păng dơi saơ mâm păng dơi rŏng ma Brah Ndu, nơm păng mâu dơi saơ ôh?$b$,false),
('bunong-vn','1JN',4,21,null,$b$Jêh ri he geh bơh Păng nau ntăm aơ: Mbu nơm rŏng ma Brah Ndu, ăn păng rŏng ma oh nâu păng tâm ban lĕ.$b$,false),
('bunong-vn','1JN',5,1,null,$b$Mbu nơm chroh ma Brah Yêsu jêng Brah Krist geh nau deh jêh bơh Brah Ndu jêh ri mbu nơm rŏng ma nơm deh jêh ma păng, jêng rŏng ma nơm deh jêh bơh păng tâm ban lĕ.$b$,true),
('bunong-vn','1JN',5,2,null,$b$He gĭt năl ma he rŏng ma phung kon Brah Ndu, tơ lah he rŏng ma Brah Ndu, jêh ri ƀư tĭng nâm nau păng ntăm.$b$,false),
('bunong-vn','1JN',5,3,null,$b$Pô aơ, jêng nau rŏng bơh Brah Ndu, tơ lah he tông nau păng ntăm, jêh ri nau păng ntăm mâu jêng nau jâk ôh.$b$,false),
('bunong-vn','1JN',5,4,null,$b$Yor lah lĕ rngôch mbu nơm deh bơh Brah Ndu dơi đah neh ntu, jêh ri nau dơi đah neh ntu jêng nau he chroh.$b$,false),
('bunong-vn','1JN',5,5,null,$b$Mbu nơm dơi jêh đah neh ntu? Mâu di hĕ mbu nơm chroh ma Brah Yêsu jêng Kon Brah Ndu?$b$,false),
('bunong-vn','1JN',5,6,null,$b$Yêsu Krist nơm yơh văch jêh ma dak jêh ri ma mham; mâu di. Knŏng ma dak ôh, ƀiă lah dak nđâp ma mham.$b$,true),
('bunong-vn','1JN',5,7,null,$b$Brah Huêng Ueh yơh jêng nơm mbơh yor lah Brah Huêng Ueh jêng nau nanê̆.$b$,false),
('bunong-vn','1JN',5,8,null,$b$Geh pe ntil nau mbơh: Brah Huêng Ueh, dak jêh ri mham, lĕ pe ntil tâm rnglăp dơn da dê.$b$,false),
('bunong-vn','1JN',5,9,null,$b$Tơ lah he dơn nau mbơh bơh bunuyh, nau Brah Ndu mbơh jêng toyh lơn, yor lah nau Brah Ndu mbơh jêng nau mbơh ma Kon Păng.$b$,true),
('bunong-vn','1JN',5,10,null,$b$Mbu nơm chroh ma Kon Brah Ndu geh nau mbơh nĕ tâm păng nơm. Mbu nơm mâu chroh ma Brah Ndu, njêng Brah Ndu mƀruh, yor lah păng mâu chroh ma nau Brah Ndu mbơh jêh ma Kon Păng Nơm.$b$,false),
('bunong-vn','1JN',5,11,null,$b$Pô aơ jêng nau Păng mbơh: Brah Ndu ăn jêh ma he nau rêh n'ho ro, jêh ri nau rêh aơ gŭ tâm Kon Păng Nơm.$b$,false),
('bunong-vn','1JN',5,12,null,$b$Mbu nơm geh kon geh nau rêh; mbu nơm mâu geh Kon Brah Ndu mâu geh nau rêh ôh.$b$,false),
('bunong-vn','1JN',5,13,null,$b$Gâp nchih jêh nau nĕ ma khân may phung chroh jêh ma amoh Kon Brah Ndu, gay ma khân may gĭt khân may geh jêh nau rêh n'ho ro.$b$,true),
('bunong-vn','1JN',5,14,null,$b$Pô aơ nau rnơm phung he geh ta năp Brah Ndu, tơ lah he dăn ndơ tĭng nâm păng ŭch, păng iăt nau he.$b$,false),
('bunong-vn','1JN',5,15,null,$b$Tơ lah he gĭt păng iăt nau he dăn, he gĭt ma he geh ndơ he dăn jêh ma Păng.$b$,false),
('bunong-vn','1JN',5,16,null,$b$Tơ lah du huê saơ oh nâu păng ƀư nau tih mâu tât ma nau khĭt ôh, ăn păng mbơh sơm kơl ô băl, jêh ri Brah Ndu mra ăn nau rêh ma phung ƀư nau tih mâu tât ma nau khĭt ôh. Geh du ntil nau tih tât geh nau khĭt; mâu di ma nau tih nĕ ôh gâp ăn bu mbơh sơm,$b$,true),
('bunong-vn','1JN',5,17,null,$b$lĕ rngôch nau kue jêng nau tih, ƀiă lah geh nau tih mâu tât nau khĭt ôh.$b$,false),
('bunong-vn','1JN',5,18,null,$b$He gĭt mbu nơm deh rngloi bơh Brah Ndu mâu ƀư tih ôh, ƀiă lah mbu nơm deh jêh bơh Brah Ndu chiă uănh păng nơm, jêh ri brah mhĭk mâu pah bi păng ôh.$b$,true),
('bunong-vn','1JN',5,19,null,$b$He gĭt he luh bơh Brah Ndu jêh ri lĕ neh ntu gŭ tâm dâng nau brah, brah mhĭk.$b$,false),
('bunong-vn','1JN',5,20,null,$b$He gĭt lĕ ma Kon Brah Ndu văch jêh, jêh ri ăn jêh ma he nau gĭt rbăng, gay ma he gĭt năl nơm jêng nanê̆, jêh ri he gŭ tâm nơm jêng nanê̆, tâm Kon Păng, Yêsu Krist. Păng yơh jêng Brah Ndu nanê̆ jêh ri nau rêh n'ho ro.$b$,false),
('bunong-vn','1JN',5,21,null,$b$Hơi phung kon jê̆, njrăng hom, lơi mbah ma rup brah ôh.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
